import { Info } from 'lucide-react'
import { Button } from '@components/Button/Button'
import { useTranslations } from '../providers/ContactServiceProvider'

interface ContactGridEmptyStateProps {
  mode: 'edit' | 'view'
  onAddContact: () => void
}

export function ContactGridEmptyState({ mode, onAddContact }: ContactGridEmptyStateProps) {
  const t = useTranslations()

  return (
    <div className="flex flex-col items-center gap-4">
      <div className="flex w-full items-center gap-3 rounded-lg bg-cyan-50 px-4 py-3 dark:bg-cyan-950/30">
        <Info className="h-5 w-5 shrink-0 text-cyan-600 dark:text-cyan-400" />
        <p className="text-sm text-cyan-800 dark:text-cyan-200">
          {t.grid.emptyBanner}
        </p>
      </div>
      {mode === 'edit' && (
        <Button type="outline" htmlType="button" onClick={onAddContact}>
          {t.grid.button.addContact}
        </Button>
      )}
    </div>
  )
}
