import React, { createContext, useContext, useEffect, useState, useMemo } from 'react';
import type { TranslationEngine, TranslationProviderProps, Language } from '../types';
import { DefaultTranslationEngine } from '../engines/DefaultTranslationEngine';
import { languageStorage } from '../storage/languageStorage';

/**
 * Interfaz del contexto interno de traducción
 */
interface TranslationContextType {
  translate: (key: string) => string;
  t: (key: string) => string; // Alias común
  setLanguage: (lang: string) => Promise<void>;
  currentLanguage: string;
  languages: Language[];
  isReady: boolean;
  error: string | null;
}

const TranslationContext = createContext<TranslationContextType | undefined>(undefined);

/**
 * Provider principal para la internacionalización de Siesa
 */
export const TranslationProvider: React.FC<TranslationProviderProps> = ({
  children,
  mode = 'standalone',
  broadcastEventName = 'siesa:language-changed',
  apiAdapter,
  staticLanguages,
  staticResources,
  defaultLanguage = 'es',
  autoSetAxiosHeader = false,
  axiosInstance,
}) => {
  const [currentLanguage, setCurrentLanguage] = useState<string>(
    languageStorage.getLanguage() || defaultLanguage
  );
  const [languages, setLanguages] = useState<Language[]>(staticLanguages || []);
  const [isReady, setIsReady] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Instanciamos el motor de traducción (una sola vez)
  const engine = useMemo(() => new DefaultTranslationEngine(defaultLanguage), [defaultLanguage]);

  // Actualizar header de axios si es necesario
  const updateAxiosHeader = (lang: string) => {
    if (autoSetAxiosHeader && axiosInstance) {
      if (axiosInstance.defaults && axiosInstance.defaults.headers) {
        axiosInstance.defaults.headers.common['Accept-Language'] = lang;
      }
    }
  };

  /**
   * Carga los recursos de un idioma (estáticos, cache o API)
   */
  const loadLanguageResources = async (lang: string) => {
    try {
      // 1. Intentar desde staticResources (Modo Desconectado)
      if (staticResources && staticResources[lang]) {
        engine.loadResources(lang, staticResources[lang]);
        return;
      }

      // 2. Intentar cargar desde localStorage (Cache)
      let resources = languageStorage.getTranslations(lang);

      // 3. Si no hay cache y hay adaptador de API, llamar al backend
      if (!resources && apiAdapter) {
        resources = await apiAdapter.getTranslations(lang);
        // Solo guardar en caché si somos shell o standalone (evitar sobre-escrituras cruzadas de MFEs)
        if (mode !== 'mfe') {
          languageStorage.setTranslations(lang, resources);
        }
      }

      // 4. Registrar en el motor si tenemos algo
      if (resources) {
        engine.loadResources(lang, resources);
      }
    } catch (err) {
      console.error(`Error cargando recursos de idioma [${lang}]:`, err);
      setError(`No se pudieron cargar las traducciones para el idioma: ${lang}`);
    }
  };

  /**
   * Carga la lista de idiomas disponibles
   */
  const loadAvailableLanguages = async () => {
    try {
      // 1. Si ya tenemos idiomas estáticos, usarlos directamente
      if (staticLanguages && staticLanguages.length > 0) {
        setLanguages(staticLanguages);
        return;
      }

      // 2. Intentar cargar desde cache para disponibilidad inmediata
      let availableLangs = languageStorage.getAvailableLanguages();
      if (availableLangs) {
        setLanguages(availableLangs);
      }

      // 3. Refrescar desde el API si hay adaptador
      // OPTIMIZACIÓN MFE: Si somos un microfrontend y ya tenemos caché, omitimos la llamada a la API
      // para que solo el Shell sea el que interactúe con la red
      if (apiAdapter && !(mode === 'mfe' && availableLangs)) {
        const freshLangs = await apiAdapter.getLanguages();
        if (freshLangs && JSON.stringify(freshLangs) !== JSON.stringify(availableLangs)) {
          setLanguages(freshLangs);
          if (mode !== 'mfe') {
            languageStorage.setAvailableLanguages(freshLangs);
          }
        }
      }
    } catch (err) {
      console.error('Error cargando idiomas disponibles:', err);
    }
  };

  /**
   * Cambia el idioma activo de la aplicación
   */
  const setLanguage = async (lang: string, fromBroadcast = false) => {
    // Si somos MFE y el cambio no viene del broadcast, ignoramos o avisamos.
    // Solo el Shell o un Standalone deberían cambiar el idioma por acción del usuario directamente
    // Pero permitimos el cambio si es forzado por el broadcast global
    if (mode === 'mfe' && !fromBroadcast) {
      console.warn('Los MFEs no deberían cambiar el idioma manualmente. Use el Shell para cambiar el idioma global.');
      return;
    }

    setIsReady(false);
    
    // 1. Asegurar recursos cargados
    await loadLanguageResources(lang);
    
    // 2. Actualizar estado y motor
    setCurrentLanguage(lang);
    engine.changeLanguage(lang);
    
    if (mode !== 'mfe') {
      languageStorage.setLanguage(lang);
    }
    
    updateAxiosHeader(lang);
    
    setIsReady(true);

    // 3. BROADCAST (Si somos Shell, avisar al ecosistema)
    if (mode === 'shell' && !fromBroadcast) {
      const event = new CustomEvent(broadcastEventName, { detail: lang });
      window.dispatchEvent(event);
    }
  };

  /**
   * Inicialización del sistema
   */
  useEffect(() => {
    const init = async () => {
      // 1. Cargar lista de idiomas en paralelo
      loadAvailableLanguages();

      // 2. Cargar recursos del idioma actual
      await loadLanguageResources(currentLanguage);
      
      // 3. Si el actual no es el default, precargar el default para fallbacks
      if (currentLanguage !== defaultLanguage) {
        await loadLanguageResources(defaultLanguage);
      }

      // 4. Sincronizar motor y header inicial
      engine.changeLanguage(currentLanguage);
      updateAxiosHeader(currentLanguage);
      
      setIsReady(true);
    };

    init();
  }, [apiAdapter, defaultLanguage, mode]);

  /**
   * Suscripción a eventos de Microfrontends (Modo MFE)
   */
  useEffect(() => {
    if (mode !== 'mfe') return;

    const handleLanguageChange = (e: Event) => {
      const customEvent = e as CustomEvent<string>;
      const newLang = customEvent.detail;
      
      if (newLang && newLang !== currentLanguage) {
        // Forzar cambio viniendo del evento global
        setLanguage(newLang, true);
      }
    };

    window.addEventListener(broadcastEventName, handleLanguageChange);

    return () => {
      window.removeEventListener(broadcastEventName, handleLanguageChange);
    };
  }, [mode, broadcastEventName, currentLanguage]);

  const value: TranslationContextType = {
    translate: (key) => engine.translate(key),
    t: (key) => engine.translate(key),
    setLanguage,
    currentLanguage,
    languages,
    isReady,
    error,
  };

  return (
    <TranslationContext.Provider value={value}>
      {children}
    </TranslationContext.Provider>
  );
};

/**
 * Hook para acceder al contexto de traducción
 * Implementa una política de "Fallo Amistoso" (Graceful Fallback): 
 * Si no hay un TranslationProvider en la raíz, no rompe la aplicación,
 * sino que devuelve un estado seguro por defecto.
 */
export const useTranslationInternal = () => {
  const context = useContext(TranslationContext);
  
  if (context === undefined) {
    // Intentar recuperar idiomas del localStorage como último recurso
    const cachedLangs = languageStorage.getAvailableLanguages() || [
      { codigo: 'es', nombre: 'Español' },
      { codigo: 'en', nombre: 'English' }
    ];
    
    const currentLang = languageStorage.getLanguage() || 'es';

    return {
      translate: (key: string) => key,
      t: (key: string) => key,
      setLanguage: async (lang: string) => { 
        console.warn('TranslationProvider no encontrado. Usando fallback básico (solo LocalStorage).');
        languageStorage.setLanguage(lang);
        // Forzar un reload simple si estamos en modo fallback extremo para aplicar el cambio
        window.location.reload();
      },
      currentLanguage: currentLang,
      languages: cachedLangs,
      isReady: true,
      error: null,
    } as TranslationContextType;
  }
  
  return context;
};
