import { useTranslationInternal } from '../core/TranslationProvider';

/**
 * Hook para gestionar el idioma actual
 * Uso: const { currentLanguage, languages, setLanguage } = useLanguage();
 */
export const useLanguage = () => {
  const { currentLanguage, languages, setLanguage, isReady } = useTranslationInternal();
  return {
    currentLanguage,
    languages,
    setLanguage,
    isLanguageChanging: !isReady,
  };
};
