import { clsx } from 'clsx';
import type { ContentLayoutProps } from './MasterDocument.types';

/**
 * Layout flex que organiza el contenido principal y el panel FactBox.
 * El FactBox se renderiza como sidebar estática en xl+ o como overlay en pantallas menores.
 *
 * @see MasterDocument.types - ContentLayoutProps
 */
export function ContentLayout({
  children,
  factBox,
  factBoxOpen,
  onFactBoxClose,
  className,
}: ContentLayoutProps) {
  return (
    <div
      className={clsx(
        'flex flex-1 min-h-0',
        className,
      )}
    >
      {/* Main panel */}
      <div className="flex-1 min-w-0 overflow-y-auto bg-[#F0F2F5] dark:bg-dark-bg-secondary">
        {children}
      </div>

      {/* FactBox — rendered by the FactBox component itself handles responsiveness.
          On xl+, it renders as a static sidebar within this flex container.
          On smaller screens, it renders as overlay/drawer independently. */}
      {factBox}
    </div>
  );
}
