import React, { Suspense, useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { GripVertical, Maximize2, Minimize2, X, AlertCircle, RefreshCw, AlertTriangle } from 'lucide-react';
import { useIsFetching, useQueryClient } from '@tanstack/react-query';
import type { BaseWidgetProps } from '../components/DashboardEngine/types';
import { WidgetErrorBoundary } from '../components/DashboardEngine/components/WidgetErrorBoundary';

interface WrapperProps extends BaseWidgetProps {
  children: React.ReactNode;
  onRemove?: (id: string) => void;
}

export const WidgetSkeleton = () => (
  <div className="w-full h-full flex flex-col p-4 bg-white animate-pulse">
    <div className="h-6 bg-gray-200 rounded w-1/3 mb-4"></div>
    <div className="flex-1 bg-gray-100 rounded"></div>
  </div>
);

function formatTimestamp(ms: number): string {
  if (!ms) return 'Sin datos';
  const diff = Math.floor((Date.now() - ms) / 1000);
  if (diff < 60) return 'Justo ahora';
  if (diff < 3600) return `hace ${Math.floor(diff / 60)} min`;
  if (diff < 86400) return `hace ${Math.floor(diff / 3600)} h`;
  return new Date(ms).toLocaleString('es-CO', {
    day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
  });
}

export const WidgetWrapper: React.FC<WrapperProps> = ({
  preference,
  definition,
  isEditMode,
  globalFilters,
  onRemove,
  children
}) => {
  const [isMaximized, setIsMaximized] = useState(false);

  // ── Refresh manual: observar la query del widget via cache ──
  const queryClient = useQueryClient();
  const queryKey = ['widget-data', definition.widget_id, globalFilters?.period];

  // Reactivo: true si la query con este key está en curso
  const isRefetching = useIsFetching({ queryKey }) > 0;

  // Reactivo: timestamp + data length via suscripción al cache
  const [dataUpdatedAt, setDataUpdatedAt] = useState(0);
  const [dataLength, setDataLength] = useState(0);
  const [, forceRender] = useState(0);
  useEffect(() => {
    let isMounted = true;

    const readState = () => {
      if (!isMounted) return;
      const state = queryClient.getQueryState(queryKey);
      const cachedResult = queryClient.getQueryData<{
        data: unknown;
        schema: unknown;
        meta: { generatedAt?: string; rowCount?: number } | null;
      }>(queryKey);

      // Timestamp: preferir meta.generatedAt del envelope, fallback a React Query timestamp
      const generatedAt = cachedResult?.meta?.generatedAt
        ? new Date(cachedResult.meta.generatedAt).getTime()
        : null;
      const ts = generatedAt ?? (state?.dataUpdatedAt ?? 0);
      setDataUpdatedAt(prev => ts !== prev ? ts : prev);

      // Volumen: preferir rowCount del envelope (autoritativo), fallback a length del array
      const rowCount = cachedResult?.meta?.rowCount
        ?? (Array.isArray(cachedResult?.data) ? (cachedResult.data as unknown[]).length : 0);
      setDataLength(rowCount);
    };

    readState();
    const unsubscribe = queryClient.getQueryCache().subscribe(readState);
    const tick = setInterval(() => { if (isMounted) forceRender(n => n + 1); }, 30_000);

    return () => {
      isMounted = false;
      unsubscribe();
      clearInterval(tick);
    };
  }, [queryClient, definition.widget_id, globalFilters?.period]);

  // Umbral de volumen configurable por widget via config_schema. Default: 5000 registros.
  const configSchema = (definition as unknown as Record<string, unknown>).config_schema as Record<string, unknown> | undefined;
  const criticalVolume = (configSchema?.criticalVolumeThreshold as number | undefined) ?? 5000;
  const isHighVolume = dataLength > criticalVolume;

  const handleRefresh = (e: React.MouseEvent) => {
    e.stopPropagation();
    queryClient.refetchQueries({ queryKey });
  };

  const handleRemove = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onRemove) onRemove(preference.id);
  };

  const refreshButton = (
    <button
      onClick={handleRefresh}
      className="p-1 text-gray-400 hover:text-blue-600 rounded transition-colors"
      title="Actualizar datos"
    >
      <RefreshCw className={`w-3.5 h-3.5 ${isRefetching ? 'animate-spin' : ''}`} />
    </button>
  );

  const timestamp = (
    <span className="text-[11px] text-gray-400 whitespace-nowrap">
      {formatTimestamp(dataUpdatedAt)}
    </span>
  );

  const widgetContent = (
    <WidgetErrorBoundary widgetId={definition.widget_id}>
      <Suspense fallback={<WidgetSkeleton />}>
        {children}
      </Suspense>
    </WidgetErrorBoundary>
  );

  return (
    <>
      <div
        className={`
          w-full h-full flex flex-col bg-white rounded-[10px] overflow-hidden
          transition-all duration-200 border border-[#E2E8F0]
          ${isEditMode ? 'hover:shadow-md' : 'shadow-sm'}
        `}
      >
        {/* Cabecera */}
        <div
          className={`
            flex items-center justify-between px-3 py-2 border-b border-[#E2E8F0] bg-[#F4F6F8]
            ${isEditMode ? 'cursor-move drag-handle group' : ''}
          `}
        >
          <div className="flex items-center gap-2 overflow-hidden min-w-0">
            {isEditMode && (
              <GripVertical className="w-4 h-4 text-gray-400 group-hover:text-blue-500 flex-shrink-0" />
            )}
            <AlertCircle className="w-4 h-4 text-gray-500 flex-shrink-0" />
            <h3 className="text-sm font-semibold text-gray-800 truncate" title={definition.nombre}>
              {(preference.config_json?.title as string) || definition.nombre}
            </h3>
            {timestamp}
          </div>

          <div className="flex items-center gap-1 flex-shrink-0">
            {isHighVolume && (
              <span className="p-1 text-amber-500" title={`Este widget procesa ${dataLength.toLocaleString('es-CO')} registros. El rendimiento puede verse afectado.`}>
                <AlertTriangle className="w-3.5 h-3.5" />
              </span>
            )}
            {refreshButton}
            <button
              onClick={(e) => { e.stopPropagation(); setIsMaximized(true); }}
              className="p-1 text-gray-400 hover:text-blue-600 rounded transition-colors"
              title="Maximizar widget"
            >
              <Maximize2 className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={handleRemove}
              className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
              title="Quitar del dashboard"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Cuerpo — oculto cuando está maximizado (el portal lo muestra en fullscreen) */}
        <div className={`flex-1 overflow-hidden relative bg-white transition-opacity duration-300 ${isRefetching ? 'opacity-60' : ''} ${isMaximized ? 'invisible' : ''}`}>
          {widgetContent}
        </div>
      </div>

      {/* Modal maximizado */}
      {isMaximized && createPortal(
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 md:p-8">
          <div className="w-full h-full max-w-7xl max-h-[90vh] bg-white rounded-xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between px-4 py-3 border-b border-[#E2E8F0] bg-[#F4F6F8]">
              <div className="flex items-center gap-2">
                <AlertCircle className="w-5 h-5 text-gray-500" />
                <h3 className="text-lg font-semibold text-gray-800">{definition.nombre}</h3>
                {timestamp}
              </div>
              <div className="flex items-center gap-2">
                {refreshButton}
                <button
                  onClick={(e) => { e.stopPropagation(); setIsMaximized(false); }}
                  className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-200 rounded-md transition-colors"
                  title="Minimizar"
                >
                  <Minimize2 className="w-5 h-5" />
                </button>
              </div>
            </div>
            <div className={`flex-1 overflow-auto bg-white relative p-4 transition-opacity duration-300 ${isRefetching ? 'opacity-60' : ''}`}>
              {widgetContent}
            </div>
          </div>
        </div>,
        document.body
      )}
    </>
  );
};
