import { useState, useEffect } from 'react';
import { clsx } from 'clsx';
import type { FactBoxProps, FactBoxSectionConfig } from './MasterDocument.types';

// ─── Chevron icon ──────────────────────────────────────────

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <svg
      className={clsx('w-3.5 h-3.5 transition-transform duration-200', open ? 'rotate-90' : 'rotate-0')}
      viewBox="0 0 20 20"
      fill="currentColor"
    >
      <path fillRule="evenodd" d="M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z" clipRule="evenodd" />
    </svg>
  );
}

function XIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 20 20" fill="currentColor" {...props}>
      <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
    </svg>
  );
}

// ─── FactBox Widget ────────────────────────────────────────

function FactBoxWidget({ section }: { section: FactBoxSectionConfig }) {
  const [open, setOpen] = useState(section.defaultOpen);

  return (
    <div
      className={clsx(
        'bg-bg-primary rounded-[10px] mb-2',
        'shadow-[0_1px_3px_rgba(60,64,67,.15),0_1px_2px_rgba(60,64,67,.10)]',
        'dark:bg-dark-bg-primary dark:shadow-none dark:border dark:border-dark-border-primary',
      )}
    >
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="flex items-center justify-between w-full px-3.5 py-2.5 text-left focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary"
        aria-expanded={open}
      >
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold text-content-primary dark:text-dark-content-primary">
            {section.label}
          </span>
          {section.badge}
        </div>
        <ChevronIcon open={open} />
      </button>

      {open && (
        <div className="border-t border-border-secondary dark:border-dark-border-primary px-3.5 py-3">
          {section.children}
        </div>
      )}
    </div>
  );
}

// ─── FactBox Panel Content ─────────────────────────────────

function FactBoxContent({ sections }: { sections: FactBoxSectionConfig[] }) {
  return (
    <div className="flex flex-col gap-0">
      {sections.map((section) => (
        <FactBoxWidget key={section.key} section={section} />
      ))}
    </div>
  );
}

// ─── FactBox ───────────────────────────────────────────────

/**
 * Panel de información contextual (FactBox) del documento maestro.
 *
 * Se adapta a tres breakpoints:
 * - **xl+**: barra lateral estática a la derecha del formulario.
 * - **md–lg**: panel deslizante desde la derecha (drawer), controlado por `open`/`onClose`.
 * - **xs–sm**: hoja inferior deslizante (bottom sheet), controlada por `open`/`onClose`.
 *
 * Acepta un arreglo de `FactBoxSectionConfig`, cada una con su propia clave,
 * etiqueta, insignia opcional y nodo hijo. Cada sección se renderiza como un
 * widget colapsable independiente (acordeón).
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - FactBoxProps, FactBoxSectionConfig
 *
 * @example
 * ```tsx
 * <FactBox
 *   sections={[
 *     { key: 'totals', label: 'Totales', defaultOpen: true, children: <FactBoxTotals ... /> },
 *     { key: 'cfde',   label: 'DIAN',    defaultOpen: false, children: <FactBoxCfde ... /> },
 *   ]}
 *   open={drawerOpen}
 *   onClose={() => setDrawerOpen(false)}
 * />
 * ```
 */
export function FactBox({ sections, open, onClose, className }: FactBoxProps) {
  // Lock body scroll when open as drawer/sheet
  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = '';
      };
    }
  }, [open]);

  return (
    <>
      {/* Desktop (xl+): static sidebar */}
      <aside
        className={clsx(
          'hidden xl:block w-[264px] shrink-0 sticky top-[52px] self-start',
          'max-h-[calc(100vh-100px)] overflow-y-auto',
          'bg-[#F0F2F5] dark:bg-dark-bg-secondary pl-1 pr-4 pt-4 pb-8',
          className,
        )}
        aria-label="Panel de información"
      >
        <FactBoxContent sections={sections} />
      </aside>

      {/* Tablet (md-lg): Right drawer */}
      <div
        className={clsx(
          'hidden md:block xl:hidden',
          'fixed inset-0 z-[250] transition-opacity duration-250',
          open ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none',
        )}
      >
        {/* Overlay */}
        <div
          className="absolute inset-0 bg-black/30 dark:bg-black/50"
          onClick={onClose}
          aria-hidden="true"
        />
        {/* Panel */}
        <aside
          className={clsx(
            'absolute top-0 right-0 bottom-0 w-[300px] bg-background-secondary dark:bg-dark-bg-secondary p-3 overflow-y-auto',
            'shadow-lg',
            'transition-transform duration-250 ease-out',
            open ? 'translate-x-0' : 'translate-x-full',
          )}
          aria-label="Panel de información"
        >
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-bold text-content-primary dark:text-dark-content-primary">
              Información
            </span>
            <button
              type="button"
              onClick={onClose}
              className="p-1 rounded-md hover:bg-bg-primary/60 dark:hover:bg-dark-bg-primary/60 text-content-secondary dark:text-dark-content-secondary transition-all duration-150 focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary"
              aria-label="Cerrar panel"
            >
              <XIcon className="w-4 h-4" />
            </button>
          </div>
          <FactBoxContent sections={sections} />
        </aside>
      </div>

      {/* Mobile (xs/sm): Bottom sheet */}
      <div
        className={clsx(
          'block md:hidden',
          'fixed inset-0 z-[250] transition-opacity duration-250',
          open ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none',
        )}
      >
        <div
          className="absolute inset-0 bg-black/30 dark:bg-black/50"
          onClick={onClose}
          aria-hidden="true"
        />
        <aside
          className={clsx(
            'absolute bottom-0 left-0 right-0 h-[70vh] bg-background-secondary dark:bg-dark-bg-secondary rounded-t-2xl p-4 overflow-y-auto',
            'shadow-lg',
            'transition-transform duration-250 ease-out',
            open ? 'translate-y-0' : 'translate-y-full',
          )}
          aria-label="Panel de información"
        >
          {/* Drag handle */}
          <div className="flex justify-center mb-3">
            <div className="w-10 h-1 rounded-full bg-border-primary dark:bg-dark-border-primary" />
          </div>
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-bold text-content-primary dark:text-dark-content-primary">
              Información
            </span>
            <button
              type="button"
              onClick={onClose}
              className="p-1 rounded-md hover:bg-bg-primary/60 dark:hover:bg-dark-bg-primary/60 text-content-secondary dark:text-dark-content-secondary transition-all duration-150 focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary"
              aria-label="Cerrar panel"
            >
              <XIcon className="w-4 h-4" />
            </button>
          </div>
          <FactBoxContent sections={sections} />
        </aside>
      </div>
    </>
  );
}
