import { useEffect } from 'react';
import { clsx } from 'clsx';
import type { DocumentCreationWizardProps, WizardOption } from './MasterDocument.types';

// ─── Icons ─────────────────────────────────────────────────

function XIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 20 20" fill="currentColor" {...props}>
      <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
    </svg>
  );
}

// ─── Option Card ───────────────────────────────────────────

function OptionCard({
  option,
  selected,
  onClick,
}: {
  option: WizardOption;
  selected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={clsx(
        'flex items-start gap-3 w-full rounded-xl px-4 py-3 text-left transition-all duration-150',
        'border-2',
        'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
        'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
        selected
          ? 'bg-primary-100 border-primary-600 border-l-[3px] dark:bg-primary-600/10 dark:border-primary-600'
          : 'bg-bg-primary border-border-secondary hover:border-border-primary hover:bg-background-secondary dark:bg-dark-bg-primary dark:border-dark-border-primary dark:hover:bg-dark-bg-secondary',
      )}
      style={selected && option.color ? { borderLeftColor: option.color } : undefined}
    >
      {option.icon && (
        <span className="shrink-0 mt-0.5">{option.icon}</span>
      )}
      <div className="min-w-0">
        <span className={clsx(
          'text-sm font-semibold',
          selected ? 'text-primary-600 dark:text-primary-400' : 'text-content-primary dark:text-dark-content-primary',
        )}>
          {option.label}
        </span>
        {option.description && (
          <p className="text-xs text-content-secondary dark:text-dark-content-secondary mt-0.5">
            {option.description}
          </p>
        )}
      </div>
    </button>
  );
}

// ─── Skeleton Loader ───────────────────────────────────────

function StepSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-3">
      {Array.from({ length: 4 }).map((_, i) => (
        <div key={i} className="h-16 rounded-xl bg-gradient-to-r from-background-secondary to-background-secondary animate-pulse" />
      ))}
    </div>
  );
}

// ─── DocumentCreationWizard ────────────────────────────────

/**
 * Asistente paso a paso para crear un nuevo documento maestro.
 *
 * Guía al usuario a seleccionar compañía, centro de operación y tipo de
 * documento en tres pasos secuenciales. Soporta estados de carga y error
 * por paso, y confirma la creación cuando los tres campos están completos.
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - DocumentCreationWizardProps, WizardOption
 *
 * @example
 * ```tsx
 * <DocumentCreationWizard
 *   open={showWizard}
 *   onClose={() => setShowWizard(false)}
 *   companies={[{ id: '1', label: 'Siesa SAS' }]}
 *   onSelectCompany={(id) => setCompany(id)}
 *   onConfirm={() => createDocument()}
 *   {...otherProps}
 * />
 * ```
 */
export function DocumentCreationWizard({
  open,
  onClose,
  companies,
  selectedCompany,
  onSelectCompany,
  operationCenters,
  selectedCO,
  onSelectCO,
  documentTypes,
  selectedType,
  onSelectType,
  onConfirm,
  loadingStep,
  errorStep,
  className,
}: DocumentCreationWizardProps) {
  // Close on Escape
  useEffect(() => {
    if (!open) return;
    function handleKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose();
    }
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [open, onClose]);

  if (!open) return null;

  const canConfirm = !!selectedCompany && !!selectedCO && !!selectedType;

  return (
    <>
      {/* Overlay */}
      <div
        className="fixed inset-0 z-[300] bg-black/30 animate-[fadeIn_150ms_ease-out]"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Modal */}
      <div
        className={clsx(
          'fixed z-[301] top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2',
          'w-[calc(100%-32px)] max-w-[620px] max-h-[85vh] overflow-hidden',
          'bg-bg-primary rounded-2xl',
          'shadow-lg',
          'animate-[fadeIn_150ms_ease-out]',
          'dark:bg-dark-bg-primary dark:shadow-none dark:border dark:border-dark-border-primary',
          className,
        )}
        role="dialog"
        aria-modal="true"
        aria-label="Nuevo documento"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border-secondary dark:border-dark-border-primary">
          <div>
            <h2 className="text-lg font-bold text-content-primary dark:text-dark-content-primary">
              Nuevo documento
            </h2>
            <p className="text-sm text-content-secondary dark:text-dark-content-secondary mt-0.5">
              Selecciona la configuración para crear el documento
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-md hover:bg-background-secondary text-content-secondary transition-all duration-150 focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary dark:hover:bg-dark-bg-secondary"
            aria-label="Cerrar"
          >
            <XIcon className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="overflow-y-auto px-6 py-5 flex flex-col gap-5" style={{ maxHeight: 'calc(85vh - 140px)' }}>
          {/* Step 1: Company */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-[0.06em] text-content-secondary mb-2">
              Compañía <span className="text-error-content">*</span>
            </label>
            {loadingStep === 1 ? (
              <StepSkeleton />
            ) : errorStep?.step === 1 ? (
              <StepError message={errorStep.message} onRetry={errorStep.onRetry} />
            ) : (
              <select
                className="w-full rounded-md border border-border-primary bg-bg-primary px-3 py-2.5 text-sm text-content-primary focus:outline-hidden focus:border-primary-600 focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:border-dark-border-primary dark:bg-dark-bg-primary dark:text-dark-content-primary"
                value={selectedCompany ?? ''}
                onChange={(e) => onSelectCompany(e.target.value)}
              >
                <option value="" disabled>Seleccionar compañía...</option>
                {companies.map((c) => (
                  <option key={c.id} value={c.id}>{c.label}</option>
                ))}
              </select>
            )}
          </div>

          {/* Step 2: Operation Center */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-[0.06em] text-content-secondary mb-2">
              Centro de operación <span className="text-error-content">*</span>
            </label>
            {loadingStep === 2 ? (
              <StepSkeleton />
            ) : errorStep?.step === 2 ? (
              <StepError message={errorStep.message} onRetry={errorStep.onRetry} />
            ) : (
              <select
                className="w-full rounded-md border border-border-primary bg-bg-primary px-3 py-2.5 text-sm text-content-primary focus:outline-hidden focus:border-primary-600 focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 disabled:bg-background-secondary disabled:cursor-not-allowed dark:border-dark-border-primary dark:bg-dark-bg-primary dark:text-dark-content-primary dark:disabled:bg-dark-bg-secondary"
                value={selectedCO ?? ''}
                onChange={(e) => onSelectCO(e.target.value)}
                disabled={!selectedCompany}
              >
                <option value="" disabled>Seleccionar centro de operación...</option>
                {operationCenters.map((co) => (
                  <option key={co.id} value={co.id}>{co.label}</option>
                ))}
              </select>
            )}
          </div>

          {/* Step 3: Document Type */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-[0.06em] text-content-secondary mb-2">
              Tipo de documento <span className="text-error-content">*</span>
            </label>
            {loadingStep === 3 ? (
              <StepSkeleton />
            ) : errorStep?.step === 3 ? (
              <StepError message={errorStep.message} onRetry={errorStep.onRetry} />
            ) : !selectedCO ? (
              <p className="text-xs text-content-secondary italic">
                Selecciona un centro de operación para ver los tipos disponibles
              </p>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {documentTypes.map((dt) => (
                  <OptionCard
                    key={dt.id}
                    option={dt}
                    selected={dt.id === selectedType}
                    onClick={() => onSelectType(dt.id)}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-border-secondary dark:border-dark-border-primary">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 rounded-md text-sm font-semibold text-content-tertiary hover:bg-background-secondary transition-all duration-150 focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary dark:text-dark-content-secondary dark:hover:bg-dark-bg-secondary"
          >
            Cancelar
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={!canConfirm}
            className={clsx(
              'px-5 py-2 rounded-md text-sm font-semibold transition-all duration-150 min-h-[36px]',
              'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
              'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
              canConfirm
                ? 'bg-primary-inverse-background text-white hover:bg-primary-700 dark:bg-dark-bg-inverse dark:text-dark-content-inverse dark:hover:bg-dark-bg-inverse/90'
                : 'bg-border-primary text-content-secondary cursor-not-allowed dark:bg-dark-bg-secondary dark:text-dark-content-secondary',
            )}
          >
            Crear documento
          </button>
        </div>
      </div>
    </>
  );
}

// ─── Step Error ────────────────────────────────────────────

function StepError({ message, onRetry }: { message: string; onRetry: () => void }) {
  return (
    <div className="flex items-center gap-3 px-4 py-3 rounded-xl bg-error-bg dark:bg-error-content/10">
      <span className="text-xs text-error-content">{message}</span>
      <button
        type="button"
        onClick={onRetry}
        className="px-3 py-1 rounded-md text-xs font-semibold text-error-content border border-error-border/30 hover:bg-error-content/10 transition-all duration-150 shrink-0 focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2"
      >
        Reintentar
      </button>
    </div>
  );
}
