import { clsx } from 'clsx';
import type { DocumentTraceabilityTreeProps, TraceabilityTreeNode } from './MasterDocument.types';

interface DisplayNode {
  node: TraceabilityTreeNode;
  depth: number;
  isLastSibling: boolean;
  connectorPath: boolean[];
}

function buildDisplayList(root: TraceabilityTreeNode): DisplayNode[] {
  const result: DisplayNode[] = [];

  function walkAncestors(node: TraceabilityTreeNode, depth: number, connectorPath: boolean[]): void {
    for (const parent of node.parents) {
      walkAncestors(parent, depth, connectorPath);
    }
    result.push({ node, depth, isLastSibling: true, connectorPath });
  }

  function walkDescendants(
    nodes: TraceabilityTreeNode[],
    depth: number,
    connectorPath: boolean[],
  ): void {
    nodes.forEach((node, index) => {
      const isLast = index === nodes.length - 1;
      const path = [...connectorPath, !isLast];
      result.push({ node, depth, isLastSibling: isLast, connectorPath: path });
      if (node.children.length > 0) {
        walkDescendants(node.children, depth + 1, path);
      }
    });
  }

  for (const parent of root.parents) {
    walkAncestors(parent, 0, []);
  }

  result.push({ node: root, depth: root.parents.length > 0 ? 1 : 0, isLastSibling: true, connectorPath: [] });

  if (root.children.length > 0) {
    const rootDepth = root.parents.length > 0 ? 1 : 0;
    walkDescendants(root.children, rootDepth + 1, []);
  }

  return result;
}

