import { autoUpdate, flip, offset, type Placement, size, useFloating } from '@floating-ui/react'

export interface UseFloatingDropdownOptions {
  placement?: Placement
  offsetPx?: number
  enabled?: boolean
}

/**
 * Hook for dropdown positioning using @floating-ui/react.
 * Handles viewport boundary detection and auto-positioning.
 */
export function useFloatingDropdown({
  placement = 'bottom-start',
  offsetPx = 4,
  enabled = true,
}: UseFloatingDropdownOptions = {}) {
  const { refs, floatingStyles, context } = useFloating({
    placement,
    middleware: [
      offset(offsetPx),
      flip({
        fallbackAxisSideDirection: 'end',
        padding: 8,
      }),
      size({
        apply({ rects, elements }) {
          // Match dropdown width to trigger width
          Object.assign(elements.floating.style, {
            minWidth: `${rects.reference.width}px`,
          })
        },
        padding: 8,
      }),
    ],
    whileElementsMounted: enabled ? autoUpdate : undefined,
  })

  return {
    refs,
    floatingStyles,
    context,
  }
}
