/**
 * MasterPatternViewForm — root form component.
 *
 * Orchestrates the form panel: navigation container (sidebar/modal/page),
 * FormActionBar, TabBar, and tab content rendering.
 * Uses forwardRef to expose MasterPatternViewRef to consumers.
 *
 * @module components/form/MasterPatternViewForm
 * @see FMPV-MVWC-E003-S001 I-001
 */
import React, { forwardRef, useCallback, useMemo } from 'react';
import type { ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';
import type { MasterPatternViewEntity, MasterPatternViewCompany } from '../../types/service.types';
import type { MasterPatternViewProps, MasterPatternViewRef, MasterPatternViewDetailTabConfig, MasterPatternViewFormProps as ExternalFormProps } from '../../types/props.types';
import { useMasterViewStore } from '../../store/MasterViewContext';
import { useToast } from '../../hooks/useToast';
import { FormActionBar } from './FormActionBar';
import { TabBar } from './TabBar';
import type { TabBarProps } from './TabBar';
import { SidebarPanel } from './SidebarPanel';
import { ModalPanel } from './ModalPanel';
import { PagePanel } from './PagePanel';
import { BasicDataTab } from './BasicDataTab';
import { ContentTab } from './ContentTab';

export interface MasterPatternViewFormProps<T extends MasterPatternViewEntity> {
  definition: MasterPatternViewProps<T>['definition'];
  entityName: string;
  navigationType?: 'sidebar' | 'modal' | 'page';
  /** Custom panel width. For sidebar: panel width (default '480px'). For modal: modal width (default '640px'). No effect on page. */
  formWidth?: string;
  /** Custom modal max-height (default '90vh'). Only affects navigationType='modal'. */
  formHeight?: string;
  tabs?: MasterPatternViewProps<T>['tabs'];
  headerFields?: string[];
  onSave: () => void;
  onCancel: () => void;
  onRequestRefresh: () => void;
  /** Company context for the form action bar */
  companies?: MasterPatternViewCompany[];
  onCompanyChange?: (company: MasterPatternViewCompany) => void;
  /** Fully custom form renderer — replaces auto-generated form when provided. FR-007. */
  renderForm?: (props: ExternalFormProps<T>) => ReactNode;
  /** Detail tabs — custom render tabs shown only in editing mode. FR-010. */
  detailTabs?: MasterPatternViewDetailTabConfig<T>[];
  /**
   * Handler for "Habilitar compañía" in the form's Acciones menu.
   * When provided, replaces the default bare openCompanyEnableModal so the caller
   * can load getAssignedCompanyIds before the modal opens (mirrors the list row action).
   */
  onHamburgerEnableCompany?: () => void;
  /** Called when the user clicks "Reintentar" after a getById failure. */
  onRetryLoad?: () => void;
  /**
   * Fields used to build the form title when viewing or editing a record.
   * Non-empty values are joined with `" - "`.
   * Falls back to the automatic `code → name` convention when omitted.
   */
  recordTitleFields?: string[];
  /** Disables the company selector in the form action bar. */
  companyDisabled?: boolean;
  /**
   * Called in view mode to determine whether the active record can be edited.
   * - `true`   — allow (default)
   * - `false`  — hide the Editar button
   * - `string` — show the button but display a warning toast with the returned message on click
   */
  canEdit?: (record: T) => boolean | string | { disabled: true; reason?: string };
}

function MasterPatternViewFormInner<T extends MasterPatternViewEntity>(
  {
    definition,
    entityName,
    navigationType = 'sidebar',
    formWidth,
    formHeight,
    tabs: tabConfigs,
    headerFields,
    onSave,
    onCancel,
    onRequestRefresh,
    companies,
    onCompanyChange,
    renderForm,
    detailTabs,
    onHamburgerEnableCompany: onHamburgerEnableCompanyProp,
    onRetryLoad,
    recordTitleFields,
    companyDisabled,
    canEdit,
  }: MasterPatternViewFormProps<T>,
  ref: React.ForwardedRef<MasterPatternViewRef>,
) {
  const { showWarning } = useToast();
  const mode = useMasterViewStore((s) => s.mode);
  const activeTabKey = useMasterViewStore((s) => s.activeTabKey);
  const errors = useMasterViewStore((s) => s.errors);
  const values = useMasterViewStore((s) => s.values);
  const isDirty = useMasterViewStore((s) => s.isDirty);
  const setActiveTabKey = useMasterViewStore((s) => s.setActiveTabKey);
  const setValues = useMasterViewStore((s) => s.setValues);
  const openEdit = useMasterViewStore((s) => s.openEdit);
  const activeRecord = useMasterViewStore((s) => s.activeRecord);
  const openCreate = useMasterViewStore((s) => s.openCreate);
  const closeForm = useMasterViewStore((s) => s.closeForm);
  const setIsDirty = useMasterViewStore((s) => s.setIsDirty);
  const openChangeStatusModal = useMasterViewStore((s) => s.openChangeStatusModal);
  const openCompanyEnableModal = useMasterViewStore((s) => s.openCompanyEnableModal);
  const activeCompanyContext = useMasterViewStore((s) => s.activeCompanyContext);
  const toggleShowGlobalValues = useMasterViewStore((s) => s.toggleShowGlobalValues);
  const isShowGlobalValuesEnabled = useMasterViewStore((s) => s.isShowGlobalValuesEnabled);
  const globalValues = useMasterViewStore((s) => s.globalValues);
  const setOverrides = useMasterViewStore((s) => s.setOverrides);
  const overrides = useMasterViewStore((s) => s.overrides);
  const revertedFields = useMasterViewStore((s) => s.revertedFields);
  const setRevertedFields = useMasterViewStore((s) => s.setRevertedFields);

  const isLoadingRecord = useMasterViewStore((s) => s.isLoadingRecord);
  const recordLoadFailed = useMasterViewStore((s) => s.recordLoadFailed);
  const isOpen = mode !== 'closed';
  const isReadOnly = mode === 'viewing';

  // Derive field context for GLOBAL type override rendering.
  // Must be declared before any useCallback that references it (avoids TDZ).
  // - viewing mode → undefined (no overlay, no hints, no notice)
  // - creating mode → undefined (all fields editable, no disabled overlays, no revert buttons)
  // - editing in global context → 'global'
  // - editing in company context → 'company'
  const isCreating = mode === 'creating';
  const fieldContext: 'global' | 'company' | undefined =
    !isReadOnly && !isCreating && definition.type === 'GLOBAL'
      ? activeCompanyContext && activeCompanyContext !== 'global'
        ? 'company'
        : 'global'
      : undefined;

  // Expose imperative ref API
  React.useImperativeHandle(
    ref,
    () => ({
      resetDirty: () => setIsDirty(false),
      refresh: () => onRequestRefresh(),
      openCreate: () => openCreate(),
      openEdit: (id: string) => {
        if (activeRecord && (activeRecord as T & { id: string }).id === id) {
          openEdit(activeRecord as T);
        }
      },
      closeForm: () => closeForm(),
    }),
    [setIsDirty, onRequestRefresh, openCreate, openEdit, closeForm, activeRecord],
  );

  const handleFieldChange = useCallback(
    (field: string, value: unknown) => {
      setValues((prev) => ({ ...prev, [field]: value }));
      setIsDirty(true);
      // Track overridden fields in company context so service.update can tell the backend
      // which fields are actively overridden vs which should revert to null (inherit global).
      if (fieldContext === 'company') {
        setOverrides({ ...overrides, [field]: value });
      }
    },
    [setValues, setIsDirty, fieldContext, overrides, setOverrides],
  );

  const handleTabChange = useCallback(
    (key: string) => {
      setActiveTabKey(key);
    },
    [setActiveTabKey],
  );

  // Evaluate canEdit against the active record once, then derive the three modes:
  // - isEditHidden:    ocultar  — button removed from DOM
  // - isEditGrayed:    inhabilitar — button shown but disabled (+ optional tooltip)
  // - editBlockReason: mostrar mensaje — button shown, click triggers toast
  const editCheck = canEdit && activeRecord ? canEdit(activeRecord as T) : true;
  const isEditHidden = editCheck === false;
  const isEditGrayed = typeof editCheck === 'object' && editCheck.disabled === true;
  const editGrayedReason = isEditGrayed ? (editCheck as { disabled: true; reason?: string }).reason : undefined;
  const editBlockReason = typeof editCheck === 'string' ? editCheck : undefined;

  const handleEdit = useCallback(() => {
    if (editBlockReason) {
      showWarning(editBlockReason);
      return;
    }
    if (activeRecord) openEdit(activeRecord as T);
  }, [activeRecord, openEdit, editBlockReason, showWarning]);

  const handleUseGlobalData = useCallback(() => {
    // Reset overridable field values back to global values and clear overrides
    if (Object.keys(globalValues).length > 0) {
      setValues({ ...values, ...globalValues });
      setIsDirty(true);
    }
    setOverrides({});
    setRevertedFields([]);
  }, [globalValues, values, setValues, setIsDirty, setOverrides, setRevertedFields]);

  // Lightweight revert tracker for detail tabs — they manage their own form state,
  // so we only need to register the field in the store (no setValues call here).
  const handleDetailTabFieldReverted = useCallback(
    (fieldName: string) => {
      if (!revertedFields.includes(fieldName)) {
        setRevertedFields([...revertedFields, fieldName]);
      }
    },
    [revertedFields, setRevertedFields],
  );

  const handleFieldRevert = useCallback(
    (fieldName: string, globalValue: unknown) => {
      setValues({ ...values, [fieldName]: globalValue });
      setIsDirty(true);
      // Remove from overrides store
      const { [fieldName]: _removed, ...remaining } = overrides;
      setOverrides(remaining);
      // Track this field as explicitly reverted so the service sends null to backend
      if (!revertedFields.includes(fieldName)) {
        setRevertedFields([...revertedFields, fieldName]);
      }
    },
    [overrides, revertedFields, values, setValues, setIsDirty, setOverrides, setRevertedFields],
  );

  // Derive a stable form mode string for renderFormField context
  const formMode = mode === 'creating' ? 'create' : mode === 'editing' ? 'edit' : 'view';

  // Merge definition tabs with prop tabs
  const allTabConfigs = useMemo(
    () => tabConfigs ?? definition.tabs ?? [],
    [tabConfigs, definition.tabs],
  );

  // Filter tabs whose `visible` condition evaluates to false with current form values
  const visibleTabConfigs = useMemo(
    () => allTabConfigs.filter((tab) => !tab.visible || tab.visible(values)),
    [allTabConfigs, values],
  );

  // Convert detailTabs to the shape TabBar expects (MasterDetailTabConfig)
  // Inject activeCompanyContext as _companyId so isVisible always has current company
  const detailTabConfigs = useMemo(() => {
    if (!detailTabs || detailTabs.length === 0) return undefined;
    const companyId = activeCompanyContext && activeCompanyContext !== 'global' ? activeCompanyContext : undefined;
    if (!activeRecord) {
      // Creating mode — evaluate isVisible against form values (no id → tabs with isVisible hide)
      const enrichedValues = { ...values, _companyId: companyId } as unknown as T;
      return detailTabs
        .filter((dt) => !dt.isVisible || dt.isVisible(enrichedValues))
        .map((dt) => ({ key: dt.key, label: dt.label }));
    }
    const enrichedRecord = { ...activeRecord, _companyId: companyId } as T;
    return detailTabs
      .filter((dt) => !dt.isVisible || dt.isVisible(enrichedRecord))
      .map((dt) => ({ key: dt.key, label: dt.label }));
  }, [detailTabs, activeRecord, values, mode, activeCompanyContext]);

  // If the active tab becomes hidden (visible condition), reset to basicData
  React.useEffect(() => {
    if (!activeTabKey || activeTabKey === 'basicData') return;
    const isVisibleRegular = visibleTabConfigs.some((t) => t.key === activeTabKey);
    const isVisibleDetail = detailTabConfigs?.some((dt) => dt.key === activeTabKey);
    if (!isVisibleRegular && !isVisibleDetail) {
      setActiveTabKey('basicData');
    }
  }, [activeTabKey, visibleTabConfigs, detailTabConfigs, setActiveTabKey]);

  // Check if current active tab is a detail tab
  const activeDetailTab = useMemo(() => {
    if (!detailTabs || !activeTabKey) return undefined;
    return detailTabs.find((dt) => dt.key === activeTabKey);
  }, [detailTabs, activeTabKey]);

  // renderForm escape hatch: when provided, replaces the auto-generated form entirely
  const customFormContent = useMemo(() => {
    if (!renderForm) return undefined;
    const formMode = mode === 'creating' ? 'creating'
      : mode === 'editing' ? 'editing'
      : 'viewing';
    return renderForm({
      values: values as Partial<T>,
      errors,
      isDirty,
      submit: onSave,
      mode: formMode as 'creating' | 'editing' | 'viewing',
    });
  }, [renderForm, values, errors, isDirty, onSave, mode]);

  const loadingOverlay = isLoadingRecord && (
    <div className="absolute inset-0 z-[15] flex items-center justify-center rounded-xl bg-bg-primary/60 dark:bg-dark-bg-primary/60 backdrop-blur-[1px]">
      <div className="w-6 h-6 rounded-full border-2 border-border-primary dark:border-dark-border-primary border-t-[#0e79fd] animate-spin" />
    </div>
  );

  const errorBanner = recordLoadFailed && (
    <div className="flex items-center gap-3 mx-5 mt-3 px-4 py-3 rounded-lg bg-[#fef2f2] dark:bg-[#450a0a] border border-[#fecaca] dark:border-[#7f1d1d] text-sm text-[#dc2626] dark:text-[#f87171]">
      <AlertTriangle size={16} className="shrink-0" />
      <span className="flex-1">No se pudo cargar la información completa del registro.</span>
      {onRetryLoad && (
        <button
          type="button"
          onClick={onRetryLoad}
          className="flex items-center gap-1.5 px-2.5 py-1 rounded text-xs font-semibold border border-[#fecaca] dark:border-[#7f1d1d] hover:bg-[#fee2e2] dark:hover:bg-[#7f1d1d] cursor-pointer bg-transparent transition-colors"
        >
          <RefreshCw size={12} />
          Reintentar
        </button>
      )}
    </div>
  );

  const tabContent = (
    <div className="flex-1 min-h-0 overflow-y-auto scrollbar-none">
      {customFormContent ? (
        // renderForm escape hatch — consumer controls the entire form content
        customFormContent
      ) : activeDetailTab ? (
        // Detail tab custom content — render receives activeRecord (edit/view) or values (create)
        // Inject activeCompanyContext as _companyId so detailTab render always has the current company
        <div className="px-5 pt-4 pb-6">
          {activeDetailTab.render(
            {
              ...(activeRecord ?? values),
              _companyId: activeCompanyContext && activeCompanyContext !== 'global' ? activeCompanyContext : undefined,
            } as T,
            mode as 'creating' | 'editing' | 'viewing',
            {
              isShowGlobalValuesEnabled,
              globalValues: globalValues as Record<string, unknown> | null,
              revertedFields,
              onFieldReverted: handleDetailTabFieldReverted,
            },
          )}
        </div>
      ) : (
        <>
          {(!activeTabKey || activeTabKey === 'basicData') && (
            <BasicDataTab
              definition={definition}
              values={values}
              errors={errors}
              onChange={handleFieldChange}
              headerFields={headerFields}
              readOnly={isReadOnly}
              fieldContext={fieldContext}
              isShowGlobalValuesEnabled={isShowGlobalValuesEnabled}
              globalValues={globalValues}
              onFieldRevert={handleFieldRevert}
              formMode={formMode}
            />
          )}
          {visibleTabConfigs.map((tabConfig) => {
            if (activeTabKey !== tabConfig.key) return null;
            return (
              <ContentTab
                key={tabConfig.key}
                definition={definition}
                tabConfig={tabConfig}
                values={values}
                errors={errors}
                onChange={handleFieldChange}
                readOnly={isReadOnly}
                fieldContext={fieldContext}
                isShowGlobalValuesEnabled={isShowGlobalValuesEnabled}
                globalValues={globalValues}
                onFieldRevert={handleFieldRevert}
                formMode={formMode}
              />
            );
          })}
        </>
      )}
    </div>
  );

  // Derive a human-readable record title for edit/view modes.
  //
  // Priority:
  //   1. recordTitleFields (explicit consumer override) — fields joined with " - "
  //   2. Automatic convention: code → name → entityName
  //
  // Creating mode always uses entityName.
  const formTitle = useMemo(() => {
    if (mode === 'creating') return entityName;

    if (recordTitleFields && recordTitleFields.length > 0) {
      const parts = recordTitleFields
        .map((field) => values[field])
        .filter((v) => v !== undefined && v !== null && v !== '')
        .map(String);
      return parts.length > 0 ? parts.join(' - ') : entityName;
    }

    // Default convention: code - name
    const code = values['code'];
    const name = values['name'];
    const hasCode = code !== undefined && code !== null && code !== '';
    const hasName = name !== undefined && name !== null && name !== '';
    if (hasCode && hasName) return `${String(code)} - ${String(name)}`;
    if (hasCode) return String(code);
    if (hasName) return String(name);
    return entityName;
  }, [mode, values, entityName, recordTitleFields]);

  const actionBar = (
    <FormActionBar
      mode={mode}
      title={formTitle}
      isDirty={isDirty}
      onSave={onSave}
      onCancel={onCancel}
      onEdit={handleEdit}
      editHidden={isEditHidden}
      editGrayed={isEditGrayed}
      editGrayedReason={editGrayedReason}
      onHamburgerCreate={openCreate}
      onHamburgerChangeStatus={() => {
        if (activeRecord) openChangeStatusModal();
      }}
      onHamburgerEnableCompany={onHamburgerEnableCompanyProp ?? openCompanyEnableModal}
      onHamburgerUseGlobalData={handleUseGlobalData}
      onHamburgerToggleShowGlobal={toggleShowGlobalValues}
      showGlobalValues={isShowGlobalValuesEnabled}
      companies={companies}
      activeCompanyId={activeCompanyContext}
      onCompanyChange={onCompanyChange}
      definitionType={definition.type}
      recordIsActive={typeof values?.isActive === 'boolean' ? (values.isActive as boolean) : undefined}
      compact={navigationType === 'sidebar'}
      saveDisabled={recordLoadFailed}
      companyDisabled={companyDisabled}
    />
  );

  const tabBar = (
    <TabBar
      definition={{ ...definition, tabs: visibleTabConfigs }}
      activeTabKey={activeTabKey || 'basicData'}
      errors={errors}
      onTabChange={handleTabChange}
      navigationType={navigationType}
      formMode={mode}
      detailTabConfigs={detailTabConfigs as TabBarProps['detailTabConfigs']}
    />
  );

  if (navigationType === 'modal') {
    return (
      <ModalPanel isOpen={isOpen} onClose={onCancel} width={formWidth} maxHeight={formHeight}>
        <div className="flex-shrink-0">{actionBar}</div>
        {errorBanner}
        <div className="bg-background-secondary dark:bg-dark-bg-secondary flex flex-col flex-1 min-h-0 overflow-hidden">
          <div className="flex-shrink-0 mx-3">{tabBar}</div>
          <div className="flex-1 min-h-0 mx-3 mb-3 flex flex-col">
            <div className="relative bg-bg-primary dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary rounded-xl shadow-[0_1px_3px_rgba(0,0,0,0.06)] flex-1 min-h-0 flex flex-col overflow-hidden">
              {tabContent}
              {loadingOverlay}
            </div>
          </div>
        </div>
      </ModalPanel>
    );
  }

  if (navigationType === 'page') {
    return (
      <PagePanel isOpen={isOpen}>
        {actionBar}
        {errorBanner}
        <div className="flex flex-col mx-5">
          {tabBar}
          <div className="relative bg-bg-primary dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary rounded-xl shadow-[0_1px_3px_rgba(0,0,0,0.06)] mb-5 overflow-hidden">
            {tabContent}
            {loadingOverlay}
          </div>
        </div>
      </PagePanel>
    );
  }

  return (
    <SidebarPanel isOpen={isOpen} width={formWidth} onBackdropClick={isDirty ? undefined : onCancel}>
      <div className="flex-shrink-0">{actionBar}</div>
      {errorBanner}
      <div className="bg-background-secondary dark:bg-dark-bg-secondary flex flex-col flex-1 min-h-0 overflow-hidden">
        <div className="flex-shrink-0 mx-3">{tabBar}</div>
        <div className="flex-1 min-h-0 mx-3 mb-3 flex flex-col">
          <div className="relative bg-bg-primary dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary rounded-xl shadow-[0_1px_3px_rgba(0,0,0,0.06)] flex-1 min-h-0 flex flex-col overflow-hidden">
            {tabContent}
            {loadingOverlay}
          </div>
        </div>
      </div>
    </SidebarPanel>
  );
}

export const MasterPatternViewForm = forwardRef(MasterPatternViewFormInner) as <
  T extends MasterPatternViewEntity,
>(
  props: MasterPatternViewFormProps<T> & { ref?: React.ForwardedRef<MasterPatternViewRef> },
) => React.ReactElement | null;
