import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Select } from '../../Select/Select';
import { CloseIcon as XMarkIcon, DragHandleIcon } from '../icons';
import type { MasterCrudField, AdvancedFilter } from '../MasterCrud.types';

interface AdvancedSearchRuleProps {
  filter: AdvancedFilter;
  fields: MasterCrudField[];
  onUpdate: (id: string, updates: Partial<AdvancedFilter>) => void;
  onRemove: (id: string) => void;
  index: number;
  t: (key: string, defaultValue?: string) => string;
}

export const AdvancedSearchRule: React.FC<AdvancedSearchRuleProps> = ({
  filter,
  fields,
  onUpdate,
  onRemove,
  t,
}) => {
  const OPERATORS = [
    { value: 'contains', label: t('contains', 'Contiene') },
    { value: 'equals', label: t('equals', 'Es igual a') },
    { value: 'startsWith', label: t('startsWith', 'Empieza con') },
    { value: 'endsWith', label: t('endsWith', 'Termina con') },
    { value: 'gt', label: t('gt', 'Mayor que') },
    { value: 'lt', label: t('lt', 'Menor que') },
    { value: 'notEquals', label: t('notEquals', 'No es igual a') },
    { value: 'isEmpty', label: t('isEmpty', 'Está vacío') },
    { value: 'isNotEmpty', label: t('isNotEmpty', 'No está vacío') },
  ];
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: filter.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : undefined,
    opacity: isDragging ? 0.5 : undefined,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="flex items-center gap-1.5 group/rule w-full h-full"
    >
      {/* 1. Drag Handle - Más compacto */}
      <div 
        {...attributes} 
        {...listeners}
        className="flex-none p-1 text-content-tertiary cursor-grab active:cursor-grabbing hover:text-primary-600 transition-colors"
      >
        <DragHandleIcon className="w-3.5 h-3.5" />
      </div>

      {/* 2. El "Input Group" Indivisible */}
      <div className="flex-1 flex items-center h-8 border border-border-primary dark:border-dark-border-primary rounded-md bg-white dark:bg-dark-bg-primary hover:border-primary-400 dark:hover:border-dark-border-custom transition-all duration-200">

        {/* Selector de Campo — flex-[3]: ~33% del ancho */}
        <div className="flex-[3] min-w-0 h-full bg-gray-50/50 dark:bg-gray-800/20 border-r border-border-primary dark:border-dark-border-primary rounded-l-md">
          <Select
            options={fields.map(f => ({
              value: f.accessorKey as string,
              label: t(f.accessorKey as string, f.header)
            }))}
            value={filter.field}
            onChange={(val) => onUpdate(filter.id, { field: String(val) })}
            className="!gap-0 !h-full"
            showLabel={false}
            showDescription={false}
            selectSize="sm"
          />
        </div>

        {/* Selector de Operador — flex-[2]: ~22% del ancho */}
        <div className="flex-[2] min-w-0 h-full border-r border-border-primary dark:border-dark-border-primary">
          <Select
            options={OPERATORS}
            value={filter.operator || 'contains'}
            onChange={(val) => onUpdate(filter.id, { operator: String(val) })}
            className="!gap-0 !h-full"
            showLabel={false}
            showDescription={false}
            selectSize="sm"
          />
        </div>

        {/* Input de Valor — flex-[4]: ~44% del ancho */}
        <div className="flex-[4] min-w-0 h-full flex items-center px-2.5">
          {!['isEmpty', 'isNotEmpty'].includes(filter.operator || '') ? (
            <input
              type="text"
              placeholder={`${t('value', 'Valor')}...`}
              value={filter.value || ''}
              onChange={(e) => onUpdate(filter.id, { value: e.target.value })}
              className="w-full h-full bg-transparent border-none outline-none focus:ring-0 text-xs text-content-primary dark:text-dark-content-primary placeholder:text-content-tertiary"
            />
          ) : (
            <span className="text-[10px] text-content-tertiary italic">{t('notApplicable', 'N/A')}</span>
          )}
        </div>

        {/* Botón Eliminar */}
        <button
          type="button"
          onClick={() => onRemove(filter.id)}
          className="flex-none h-full px-2.5 flex items-center justify-center border-l border-border-primary dark:border-dark-border-primary rounded-r-md hover:bg-red-50 dark:hover:bg-red-900/20 text-content-tertiary hover:text-error-content transition-colors"
          title={t('removeRule', 'Eliminar regla')}
        >
          <XMarkIcon className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
};
