/**
 * Contratos e Interfaces del Módulo Dashboard Comercial (BMAD 6)
 * 
 * Este archivo es la fuente única de verdad para las entidades que viajan entre
 * el frontend (React) y el backend (Dashboard Module / Proxy).
 */

// ==========================================
// 1. Tipos Base y Dominios
// ==========================================

export type DomainCategory = 'Ventas' | 'Compras' | 'Inventario' | 'Operaciones' | string;

export type WidgetPresentationType = 
  | 'kpi' 
  | 'chart_line' 
  | 'chart_bar_vertical' 
  | 'chart_bar_horizontal' 
  | 'chart_donut' 
  | 'table' 
  | 'image' 
  | 'custom';

export type DashboardPeriod = 'Hoy' | 'Semana' | 'Mes';

/**
 * Función de fetch inyectada por el host (Master Data, Core Frontend, etc.).
 * El host es responsable de agregar autenticación, headers JWT y cualquier
 * lógica de interceptores. El Dashboard usa esta función para TODOS sus requests.
 *
 * @example — Con axios del host
 * const fetcher: DashboardFetcher = (url, opts) =>
 *   axiosInstance.request({ url, method: opts?.method ?? 'GET', data: opts?.body })
 *     .then(r => r.data);
 *
 * @example — Con fetch nativo del host
 * const fetcher: DashboardFetcher = (url, opts) =>
 *   fetch(url, {
 *     method: opts?.method ?? 'GET',
 *     headers: { Authorization: `Bearer ${getToken()}`, 'Content-Type': 'application/json' },
 *     body: opts?.body ? JSON.stringify(opts.body) : undefined,
 *   }).then(r => r.json());
 */
export type DashboardFetcher = <T = unknown>(
  url: string,
  options?: {
    method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
    body?: unknown;
  }
) => Promise<T>;

/**
 * Punto de dato genérico para gráficas de Recharts.
 * Todos los widgets de gráfica deben usar este tipo en lugar de `any[]`.
 */
export type ChartDataPoint = Record<string, string | number>;

/**
 * Field mapping semántico del widget (estándar v2).
 * Define el rol de cada campo para el chart, en lugar de un mapeo plano de renombrado.
 * Almacenado en cmp_kpi_dashboard_widgets.field_mapping (JSONB).
 */
export interface WidgetFieldMapping {
  /** Campo del endpoint que actúa como eje X / dimensión de agrupación. */
  category?: string;
  /** Campos del endpoint que se grafican como series / métricas. */
  values?: string[];
  /** Labels de visualización para leyenda y tooltip. No cambia el dataKey de Recharts. */
  aliases?: Record<string, string>;
  /** Mapeo de renombrado de campos del endpoint (campo_api → nombre_canónico). Solo para APIs con nombres no estándar. */
  rename?: Record<string, string>;
  /** Campos conocidos del endpoint (schema hints). Permite mostrar todos los campos disponibles sin que el widget haya cargado datos. */
  fields?: { name: string; type: 'string' | 'number' | 'date' | 'boolean'; label: string }[];
}

// ==========================================
// 2. Catálogo de Widgets (Definición Global)
// ==========================================

/**
 * Representa la definición base de un widget en el catálogo (tabla `dashboard_widgets`).
 * Gestionado por administradores o a través del Widget Builder.
 */
export interface WidgetDefinition {
  widget_id: string;
  nombre: string;
  descripcion: string;
  categoria: DomainCategory;
  tipo: WidgetPresentationType;
  icono: string; // Nombre del ícono en lucide-react
  roles_permitidos: string[];

  col_min: number;
  col_max: number;
  altura_default: number; // En unidades de fila (row_span)
  cols_default: number;   // En unidades de columna (col_span)
  orden_default: number;
  activo: boolean;
  version: string;

  // Ruta de importación dinámica para React.lazy (ej. '../widgets/KpiVentasHoy')
  componente_ruta?: string;
  // JSON Schema que valida los parámetros configurables del widget (config_json)
  config_schema?: Record<string, unknown>;

  // Propiedades opcionales para Widgets dinámicos (Widget Builder)
  endpoint_url?: string;
  endpoint_method?: 'GET' | 'POST';
  endpoint_headers?: Record<string, string>;
  endpoint_params?: Record<string, string | number | boolean>;
  field_mapping?: WidgetFieldMapping;
  refresh_policy?: number; // TTL en segundos
  es_privado?: boolean;
  is_internal?: boolean; // true = propaga auth del usuario al endpoint (widgets de Siesa); false = widget externo (terceros)
  propietario_id?: string;
}

/** Configuracion publica del whitelist de rutas internas (GET /api/dashboard/widgets/allowed-internal-routes) */
export interface AllowedInternalRoutes {
  enforce_whitelist: boolean;
  allowed_prefixes: string[];
  allowed_hosts: string[];
}

/** Fuente de datos disponible en el dropdown del Widget Builder (GET /api/dashboard/widgets/data-sources) */
export interface DataSourceOption {
  name: string;
  url: string;
  description?: string;
  category?: string;
  method: 'GET' | 'POST';
  suggested_type?: string;
  default_field_mapping?: Record<string, string>;
}

// ==========================================
// 3. Layout y Preferencias de Usuario
// ==========================================

/**
 * Representa la configuración específica de un widget para un usuario particular (tabla `dashboard_preferences`).
 */
export interface UserWidgetPreference {
  id: string; // Identificador único de esta instancia en el grid
  user_id: string;
  widget_id: string; // Referencia a WidgetDefinition
  activo: boolean;
  orden: number;

  col_span: number;
  row_span: number;
  pos_x: number;
  pos_y: number;

  config_json?: Record<string, unknown>; // Configuraciones específicas del usuario (ej. filtros aplicados al widget)
  modificado_en: string;
}

export interface LayoutUpdatePayload {
  userId: string;
  period: DashboardPeriod; // Estado actual de la UI a persistir opcionalmente
  layout: UserWidgetPreference[];
}

// ==========================================
// 4. Proxy Fetching y Comunicación
// ==========================================

/**
 * Payload enviado al endpoint `/api/dashboard/proxy/fetch`
 */
export interface FetchProxyPayload {
  widgetId: string;
  period: DashboardPeriod; // Crucial para que el backend filtre fechas
  userParams?: Record<string, string | number | boolean>;
}

// ==========================================
// 5. Contrato para Componentes React (Widgets)
// ==========================================

/**
 * Props estandarizadas que recibe CADA componente de widget que sea montado en el grid.
 */
export interface WidgetProps {
  preference: UserWidgetPreference;
  definition: WidgetDefinition;
  isEditMode: boolean;
  period: DashboardPeriod;
  onConfigChange?: (newConfig: Record<string, unknown>) => void;
}

// ==========================================
// Envelope Estándar de Endpoints Internos
// ==========================================

/** Descriptor de un campo en el schema del envelope. */
export interface SchemaField {
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean';
  label: string;
  format?: 'currency' | 'percent' | 'integer' | 'decimal';
}

/** Respuesta estándar de un endpoint interno de dashboard. */
export interface EndpointEnvelope {
  data: Record<string, unknown>[];
  schema: { fields: SchemaField[] };
  meta: { generatedAt: string; period: string; rowCount: number };
}

/** Configuracion de mapeo discriminada por tipo de widget */
/** Funciones de agregación disponibles para KPIs y gráficos */
export type AggregationType = 'none' | 'sum' | 'average' | 'count' | 'min' | 'max' | 'last' | 'first';

/** Familias de tipos de widget — los tipos de una misma familia son intercambiables */
export type ChartFamily = 'scalar' | 'categorical' | 'tabular';

export const TYPE_FAMILIES: Record<string, ChartFamily> = {
  kpi:                  'scalar',
  chart_bar_vertical:   'categorical',
  chart_bar_horizontal: 'categorical',
  chart_line:           'categorical',
  chart_donut:          'categorical',
  table:                'tabular',
};

/**
 * Retorna los tipos hermanos (excluye el actual).
 * Si valuesCount > 1, excluye donut (solo acepta 1 valor).
 */
export function getCompatibleTypes(tipo: string, valuesCount?: number): string[] {
  const family = TYPE_FAMILIES[tipo];
  if (!family) return [];
  return Object.entries(TYPE_FAMILIES)
    .filter(([t, f]) => {
      if (f !== family || t === tipo) return false;
      if (t === 'chart_donut' && valuesCount != null && valuesCount > 1) return false;
      return true;
    })
    .map(([t]) => t);
}

/**
 * Contrato unificado de datos para todos los charts categóricos.
 * Almacenado en config_schema. Agnóstico del tipo de chart —
 * el mismo contrato sirve para barras, líneas y donut.
 */
export interface ChartDataContract {
  categoryField: string;
  valueFields: string[];
  aggregation?: AggregationType;
}

/**
 * Override de field mapping por usuario.
 * Almacenado en preference.config_json.fieldMapping.
 * Se mergea sobre el contrato del widget (config_schema).
 */
export interface FieldMappingOverride {
  category?: string;
  values?: string[];
  aliases?: Record<string, string>;
}

/**
 * Extrae un ChartDataContract normalizado de config_schema.
 * Soporta: forma directa (categoryField+valueFields), MappingConfig (Builder), o null.
 */
export function extractChartContract(
  configSchema: Record<string, unknown> | undefined | null
): ChartDataContract | null {
  if (!configSchema) return null;

  // Forma directa: { categoryField, valueFields }
  if ('categoryField' in configSchema && 'valueFields' in configSchema) {
    const c = configSchema as unknown as ChartDataContract;
    if (typeof c.categoryField === 'string' && Array.isArray(c.valueFields)) {
      return c;
    }
  }

  // Forma MappingConfig (Builder widgets)
  const type = configSchema.type as string | undefined;
  if (!type) return null;

  switch (type) {
    case 'chart_bar_vertical':
    case 'chart_bar_horizontal': {
      const cfg = configSchema as { xField?: string; yField?: string; aggregation?: AggregationType };
      if (cfg.xField && cfg.yField) {
        return { categoryField: cfg.xField, valueFields: [cfg.yField], aggregation: cfg.aggregation };
      }
      return null;
    }
    case 'chart_line': {
      const cfg = configSchema as { xField?: string; yField?: string; seriesFields?: string[]; aggregation?: AggregationType };
      if (cfg.xField && cfg.yField) {
        return { categoryField: cfg.xField, valueFields: [cfg.yField, ...(cfg.seriesFields ?? [])], aggregation: cfg.aggregation };
      }
      return null;
    }
    case 'chart_donut': {
      const cfg = configSchema as { categoryField?: string; valueField?: string; aggregation?: AggregationType };
      if (cfg.categoryField && cfg.valueField) {
        return { categoryField: cfg.categoryField, valueFields: [cfg.valueField], aggregation: cfg.aggregation };
      }
      return null;
    }
    default:
      return null;
  }
}

export type MappingConfig =
  | {
      type: 'kpi';
      valueField: string;
      labelField?: string;
      aggregation: 'sum' | 'average' | 'count' | 'last' | 'min' | 'max';
      valuePrefix?: string;
      valueSuffix?: string;
    }
  | {
      type: 'chart_bar_vertical';
      xField: string;
      yField: string;
      groupByField?: string;
      aggregation?: AggregationType;
    }
  | {
      type: 'chart_bar_horizontal';
      xField: string;
      yField: string;
      groupByField?: string;
      aggregation?: AggregationType;
    }
  | {
      type: 'chart_line';
      xField: string;
      yField: string;
      seriesFields?: string[];
      aggregation?: AggregationType;
    }
  | {
      type: 'chart_donut';
      categoryField: string;
      valueField: string;
      aggregation?: AggregationType;
    }
  | {
      type: 'table';
      visibleColumns: string[];
      sortField?: string;
      sortDirection?: 'asc' | 'desc';
    };
