/**
 * Formateadores por defecto del panel de Instrumento Financiero. El consumidor
 * puede sobrescribirlos por props (`formatAmount` / `formatDate`).
 */

/** Monto con 2 decimales en formato es-CO. */
export const defaultFormatAmount = (value: number): string =>
  new Intl.NumberFormat('es-CO', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(
    value,
  );

/**
 * Fecha `YYYY-MM-DD` → `dd/MM/yyyy` (es-CO) sin desfase por zona horaria
 * (`new Date('YYYY-MM-DD')` interpreta UTC; aquí formateamos por partes).
 */
export const defaultFormatDate = (isoDate: string): string => {
  if (!isoDate) return '';
  const [year, month, day] = isoDate.split('-');
  if (!year || !month || !day) return isoDate;
  return `${day}/${month}/${year}`;
};
