/**
 * CompanyEnableModal — manage which companies a GLOBAL record is enabled for.
 *
 * Accumulates enable/disable changes locally (pendingChanges Map) and only calls
 * onConfirm when the user explicitly clicks "Confirmar cambios".
 *
 * @module components/modals/CompanyEnableModal
 * @see FMPV-MVWC-E004-S005
 */
import React, { useState, useMemo, useEffect } from 'react';
import { Building2, X, Search } from 'lucide-react';
import { Button } from '../../../Button/Button';
import type { MasterPatternViewCompany } from '../../types/service.types';

export interface CompanyEnableChange {
  companyId: string;
  action: 'enable' | 'disable';
}

export interface CompanyEnableModalProps {
  isOpen: boolean;
  recordId: string;
  companies: MasterPatternViewCompany[];
  assignedCompanyIds: string[];
  onClose: () => void;
  onConfirm: (changes: CompanyEnableChange[]) => void;
  isLoading: boolean;
}

export function CompanyEnableModal({
  isOpen,
  companies,
  assignedCompanyIds,
  onClose,
  onConfirm,
  isLoading,
}: CompanyEnableModalProps): React.ReactElement | null {
  const [searchQuery, setSearchQuery] = useState('');
  const [pendingChanges, setPendingChanges] = useState<Map<string, 'enable' | 'disable'>>(
    new Map(),
  );

  // Reset pending changes and search every time the modal opens
  useEffect(() => {
    if (isOpen) {
      setPendingChanges(new Map());
      setSearchQuery('');
    }
  }, [isOpen]);

  const assignedSet = useMemo(() => new Set(assignedCompanyIds), [assignedCompanyIds]);

  const filteredCompanies = useMemo(
    () =>
      companies.filter(
        (c) =>
          c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
          c.code.toLowerCase().includes(searchQuery.toLowerCase()),
      ),
    [companies, searchQuery],
  );

  if (!isOpen) return null;

  function isEffectivelyAssigned(companyId: string): boolean {
    const pending = pendingChanges.get(companyId);
    if (pending === 'enable') return true;
    if (pending === 'disable') return false;
    return assignedSet.has(companyId);
  }

  function handleToggle(companyId: string, action: 'enable' | 'disable') {
    setPendingChanges((prev) => {
      const next = new Map(prev);
      const originallyAssigned = assignedSet.has(companyId);
      const wouldBeOriginal =
        (action === 'enable' && originallyAssigned) ||
        (action === 'disable' && !originallyAssigned);
      if (wouldBeOriginal) {
        next.delete(companyId);
      } else {
        next.set(companyId, action);
      }
      return next;
    });
  }

  function handleEnableAll() {
    setPendingChanges((prev) => {
      const next = new Map(prev);
      companies.forEach((c) => {
        if (!assignedSet.has(c.id) && next.get(c.id) !== 'enable') {
          next.set(c.id, 'enable');
        }
      });
      return next;
    });
  }

  function handleConfirm() {
    const changes: CompanyEnableChange[] = Array.from(pendingChanges.entries()).map(
      ([companyId, action]) => ({ companyId, action }),
    );
    onConfirm(changes);
  }

  const pendingCount = pendingChanges.size;

  const btnAssign = 'flex-shrink-0 rounded-md px-3 py-1 text-[11px] font-semibold cursor-pointer transition-all bg-bg-primary dark:bg-dark-bg-secondary text-[#0e79fd] border border-[#93d1fd] dark:border-[rgba(14,121,253,0.4)] hover:bg-[#eff8ff] dark:hover:bg-[rgba(14,121,253,0.15)] hover:border-[#3c9bf6]';
  const btnUnassign = 'flex-shrink-0 rounded-md px-3 py-1 text-[11px] font-semibold cursor-pointer transition-all bg-bg-primary dark:bg-dark-bg-secondary text-[#dc2626] border border-[#fca5a5] dark:border-[rgba(220,38,38,0.4)] hover:bg-[#fef2f2] dark:hover:bg-[rgba(220,38,38,0.1)] hover:border-[#f87171]';

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-[9000] flex items-center justify-center"
      style={{ background: 'rgba(15,23,42,0.45)', backdropFilter: 'blur(2px)' }}
    >
      <div className="bg-bg-primary dark:bg-dark-bg-secondary border border-transparent dark:border-dark-border-primary rounded-xl flex flex-col overflow-hidden max-h-[78vh] w-[420px]"
        style={{ boxShadow: '0 24px 64px rgba(0,0,0,.22), 0 4px 16px rgba(0,0,0,.1)' }}>

        {/* Header */}
        <div className="flex items-start justify-between px-5 py-4 border-b border-border-primary dark:border-dark-border-primary gap-3">
          <div className="flex items-start gap-3">
            <div className="w-9 h-9 rounded-lg bg-[#eff8ff] text-[#0e79fd] flex items-center justify-center flex-shrink-0">
              <Building2 size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-content-primary dark:text-dark-content-primary leading-snug">Habilitar por compañía</div>
              <div className="text-xs text-content-tertiary dark:text-dark-content-tertiary mt-0.5 leading-relaxed">
                Gestiona en qué compañías está habilitado este registro.
              </div>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-content-secondary dark:text-dark-content-secondary hover:text-content-tertiary dark:hover:text-dark-content-tertiary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary p-1 rounded-md transition-colors flex-shrink-0"
          >
            <X size={16} />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 flex-1 overflow-y-auto flex flex-col gap-3">
          {/* Search + Enable All */}
          <div className="flex items-center gap-2">
            <div
              className="flex items-center gap-2 flex-1 border border-border-primary dark:border-dark-border-primary rounded-lg px-2.5 py-1.5 bg-bg-primary dark:bg-dark-bg-primary focus-within:border-[#93d1fd] focus-within:ring-[3px] focus-within:ring-[rgba(14,121,253,0.1)] transition-all"
            >
              <Search size={14} className="text-content-secondary dark:text-dark-content-secondary flex-shrink-0" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar compañía…"
                className="border-none outline-none text-xs text-content-primary dark:text-dark-content-primary flex-1 bg-transparent placeholder-content-secondary dark:placeholder-dark-content-secondary"
                data-testid="company-search-input"
              />
            </div>
            <button
              type="button"
              onClick={handleEnableAll}
              disabled={isLoading}
              className={btnAssign + ' whitespace-nowrap'}
              data-testid="enable-all-button"
            >
              Habilitar todos
            </button>
          </div>

          {/* Company list */}
          <div className="border border-border-primary dark:border-dark-border-primary rounded-lg overflow-hidden">
            {filteredCompanies.length === 0 && (
              <div className="px-4 py-6 text-center text-xs text-content-secondary dark:text-dark-content-secondary">
                No se encontraron compañías
              </div>
            )}
            {filteredCompanies.map((company, idx) => {
              const effective = isEffectivelyAssigned(company.id);
              const isPendingAdd = pendingChanges.get(company.id) === 'enable';
              const isPendingRemove = pendingChanges.get(company.id) === 'disable';
              return (
                <div
                  key={company.id}
                  className={[
                    'flex items-center gap-2.5 px-3.5 py-2.5 transition-colors',
                    idx > 0 ? 'border-t border-border-primary dark:border-dark-border-primary' : '',
                    isPendingAdd ? 'bg-[#eff8ff] dark:bg-[rgba(14,121,253,0.12)]' : '',
                    isPendingRemove ? 'bg-[#fef2f2] dark:bg-[rgba(220,38,38,0.1)]' : '',
                  ].join(' ')}
                >
                  <div className="flex-1 flex items-center gap-2 min-w-0">
                    <span className="text-xs font-medium text-content-primary dark:text-dark-content-primary truncate">{company.name}</span>
                    <span className="text-[11px] text-content-secondary dark:text-dark-content-secondary flex-shrink-0">{company.code}</span>
                  </div>
                  {!effective ? (
                    <button
                      type="button"
                      onClick={() => handleToggle(company.id, 'enable')}
                      disabled={isLoading}
                      className={btnAssign}
                      data-testid={`enable-company-${company.id}`}
                    >
                      Habilitar
                    </button>
                  ) : (
                    <button
                      type="button"
                      onClick={() => handleToggle(company.id, 'disable')}
                      disabled={isLoading}
                      className={btnUnassign}
                      data-testid={`disable-company-${company.id}`}
                    >
                      Deshabilitar
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-border-primary dark:border-dark-border-primary bg-background-secondary dark:bg-dark-bg-primary">
          <Button
            type="outline"
            size="l"
            onClick={onClose}
            disabled={isLoading}
            data-testid="company-enable-cancel-button"
          >
            Cancelar
          </Button>
          <Button
            type="default"
            size="l"
            onClick={handleConfirm}
            disabled={pendingCount === 0 || isLoading}
            data-testid="confirm-changes-button"
          >
            {isLoading
              ? 'Guardando…'
              : pendingCount > 0
                ? `Confirmar cambios (${pendingCount})`
                : 'Confirmar cambios'}
          </Button>
        </div>
      </div>
    </div>
  );
}
