import React from 'react';
import { Badge } from '../../components/Badge/Badge';
import { AuditTimestamp } from './AuditTimestamp';
import { formatAuditValue, isEmptyAuditValue } from '../utils/formatAuditValue';
import type { AuditEntryDetailProps } from './AuditEntryDetail.types';
import type { AuditHistoryItem } from '../types/audit.types';

type BadgeColor = 'green' | 'amber' | 'red';

const ACTION_CONFIG: Record<AuditHistoryItem['action'], { color: BadgeColor; label: string }> = {
  Created: { color: 'green', label: 'Creado' },
  Modified: { color: 'amber', label: 'Actualizado' },
  Deleted: { color: 'red', label: 'Eliminado' },
};

const Placeholder: React.FC = () => (
  <div className="flex flex-col items-center justify-center h-full min-h-[200px] text-slate-400 dark:text-slate-600 gap-3 p-8">
    <svg
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      strokeWidth={1.5}
      stroke="currentColor"
      className="w-10 h-10 text-slate-300 dark:text-slate-700"
      aria-hidden="true"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        d="M19.5 14.25v-2.625a3.375 3.375 0 0 0-3.375-3.375h-1.5A1.125 1.125 0 0 1 13.5 7.125v-1.5a3.375 3.375 0 0 0-3.375-3.375H8.25m5.231 13.481L15 17.25m-4.5-15H5.625c-.621 0-1.125.504-1.125 1.125v16.5c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 0 0-9-9Zm3.75 11.625a2.625 2.625 0 1 1-5.25 0 2.625 2.625 0 0 1 5.25 0Z"
      />
    </svg>
    <p className="text-sm text-center">Selecciona un registro del historial para ver los detalles</p>
  </div>
);

/**
 * Panel derecho del split view: muestra el diff campo por campo de una entrada de auditoría.
 * Si no hay entrada seleccionada, muestra un placeholder.
 */
export const AuditEntryDetail: React.FC<AuditEntryDetailProps> = ({ entry, className = '' }) => {
  const containerClasses = ['flex flex-col h-full', className]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!entry) {
    return (
      <div className={containerClasses}>
        <Placeholder />
      </div>
    );
  }

  const { color, label } = ACTION_CONFIG[entry.action];

  return (
    <div className={containerClasses}>
      {/* Header */}
      <div className="flex items-center gap-3 px-4 py-3 border-b border-slate-200 dark:border-slate-700 flex-shrink-0">
        <Badge color={color} label={label} aria-label={`Acción: ${label}`} />
        <span className="text-sm font-medium text-slate-800 dark:text-slate-200 truncate">
          {entry.actorFullName}
        </span>
        <AuditTimestamp timestamp={entry.timestamp} className="ml-auto flex-shrink-0" />
      </div>

      {/* Diff table */}
      <div className="flex-1 overflow-y-auto">
        {entry.details.length === 0 ? (
          <div className="flex items-center justify-center h-32 text-sm text-slate-400 dark:text-slate-600">
            Sin cambios de campos registrados
          </div>
        ) : (
          <table className="w-full text-sm border-collapse">
            <caption className="sr-only">Cambios registrados en esta entrada</caption>
            <thead>
              <tr className="border-b border-slate-200 dark:border-slate-700">
                <th
                  scope="col"
                  className="px-4 py-2 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wide w-1/3"
                >
                  Campo
                </th>
                <th
                  scope="col"
                  className="px-4 py-2 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wide w-1/3"
                >
                  Antes
                </th>
                <th
                  scope="col"
                  className="px-4 py-2 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wide w-1/3"
                >
                  Después
                </th>
              </tr>
            </thead>
            <tbody>
              {entry.details.map((detail, index) => {
                const oldEmpty = isEmptyAuditValue(detail.oldValue);
                const newEmpty = isEmptyAuditValue(detail.newValue);
                const oldFormatted = formatAuditValue(detail.oldValue);
                const newFormatted = formatAuditValue(detail.newValue);

                return (
                  <tr
                    key={`${detail.fieldName}-${index}`}
                    className="border-b border-slate-100 dark:border-slate-800 last:border-0"
                  >
                    <td className="px-4 py-2 font-medium text-slate-700 dark:text-slate-300">
                      {detail.fieldName}
                    </td>
                    <td className="px-4 py-2 bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-400">
                      {oldEmpty ? (
                        <span className="italic text-slate-400 dark:text-slate-600">{oldFormatted}</span>
                      ) : (
                        oldFormatted
                      )}
                    </td>
                    <td className="px-4 py-2 bg-green-50 dark:bg-green-950/30 text-green-700 dark:text-green-400">
                      {newEmpty ? (
                        <span className="italic text-slate-400 dark:text-slate-600">{newFormatted}</span>
                      ) : (
                        newFormatted
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

AuditEntryDetail.displayName = 'AuditEntryDetail';
