import type { DynamicEntityDefinition, SaveEavValuesDto } from '../types/DynamicEntity.types';

export const DynamicEntitiesApi = {
    getDefinition: async (baseUrl: string, featureCode: string, entityCode: string): Promise<DynamicEntityDefinition> => {
        const url = `${baseUrl}/dynamic-entities/definition?featureCode=${featureCode}&entityCode=${entityCode}`;
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch definition: ${response.statusText}`);
        return response.json();
    },

    saveValues: async (baseUrl: string, featureCode: string, entityCode: string, recordId: string, values: SaveEavValuesDto, idEntityMultiple?: string): Promise<void> => {
        const url = idEntityMultiple 
            ? `${baseUrl}/ea/${featureCode}/${entityCode}/${recordId}/${idEntityMultiple}`
            : `${baseUrl}/ea/${featureCode}/${entityCode}/${recordId}`;
        
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(values)
        });
        if (!response.ok) throw new Error(`Failed to save values: ${response.statusText}`);
    },

    getValues: async (baseUrl: string, featureCode: string, entityCode: string, recordId: string, idEntityMultiple?: string): Promise<SaveEavValuesDto> => {
        const url = idEntityMultiple 
            ? `${baseUrl}/ea/${featureCode}/${entityCode}/${recordId}/${idEntityMultiple}`
            : `${baseUrl}/ea/${featureCode}/${entityCode}/${recordId}`;
        
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch values: ${response.statusText}`);
        return response.json();
    },

    deleteRecord: async (baseUrl: string, featureCode: string, recordId: string, idEntityMultiple?: string): Promise<void> => {
        const url = idEntityMultiple
            ? `${baseUrl}/ea/${featureCode}/${recordId}/${idEntityMultiple}`
            : `${baseUrl}/ea/${featureCode}/${recordId}`;
        const response = await fetch(url, {
            method: 'DELETE'
        });
        if (!response.ok) throw new Error(`Failed to delete record: ${response.statusText}`);
    },

    getMultipleRecords: async (baseUrl: string, featureCode: string, entityCode: string, recordId: string): Promise<SaveEavValuesDto[]> => {
        const response = await fetch(`${baseUrl}/ea/${featureCode}/${entityCode}/${recordId}/multiple`);
        if (!response.ok) throw new Error(`Failed to fetch records: ${response.statusText}`);
        return response.json();
    }
};
