import { useState, useEffect, useRef, useCallback } from 'react';
import { clsx } from 'clsx';
import { MagnifyingGlassIcon, ArrowUpTrayIcon, PlusIcon, ChevronLeftIcon, ChevronRightIcon, EllipsisVerticalIcon, EyeIcon, PencilIcon, TrashIcon, NoSymbolIcon, GlobeAltIcon, BuildingOffice2Icon, ChevronDownIcon } from '@heroicons/react/24/outline';
import type { DocumentListProps, DocumentListCompany, RowAction } from './MasterDocument.types';
import { CrossingClassMenu } from './CrossingClassMenu';
import { ConfirmDialog } from './DocumentModalList';
import { PrintIcon } from './icons';

// Íconos por defecto para acciones de fila sin ícono explícito.
const DEFAULT_ROW_ACTION_ICONS: Record<string, typeof TrashIcon> = {
  delete: TrashIcon,
  cancel: NoSymbolIcon,
};

// ─── Row action dropdown ───────────────────────────────────

function RowMenu({
  row,
  onView,
  onEdit,
  onDelete,
  rowActions,
  onRowAction,
  onPrint,
  printLabel = 'Imprimir',
}: {
  row: Record<string, unknown>;
  onView?: (row: Record<string, unknown>) => void;
  onEdit?: (row: Record<string, unknown>) => void;
  onDelete?: (row: Record<string, unknown>) => void;
  /** Acciones gateadas por estado (DEF-4). Si se provee, sustituye a `onDelete`. */
  rowActions?: RowAction[];
  onRowAction?: (action: RowAction, row: Record<string, unknown>) => void;
  /** Impresión nativa: si se provee, agrega "Imprimir" al menú. */
  onPrint?: (row: Record<string, unknown>) => void;
  printLabel?: string;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function handleClick(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open]);

  // `getRowActions` (cuando se provee) gobierna las acciones destructivas y
  // toma precedencia sobre el `onDelete` legacy.
  const useRowActions = !!rowActions;
  const resolvedActions = rowActions ?? [];
  const hasLegacyDelete = !useRowActions && !!onDelete;

  if (!onView && !onEdit && !hasLegacyDelete && resolvedActions.length === 0 && !onPrint) return null;

  return (
    <div
      ref={ref}
      className={clsx(
        // Columna de acciones fija a la derecha durante el scroll horizontal.
        // `sticky` también establece el bloque contenedor del dropdown absoluto.
        'sticky right-0 flex items-center justify-center shrink-0 w-10 self-stretch',
        // Fondo sólido para que el contenido no se vea por debajo (normal + hover + dark).
        'bg-bg-primary group-hover:bg-primary-100',
        'dark:bg-dark-bg-primary dark:group-hover:bg-dark-bg-secondary',
        // Sombra sutil a la izquierda para separar la columna fija del contenido.
        'shadow-[-6px_0_6px_-6px_rgba(60,64,67,0.18)] dark:shadow-[-6px_0_6px_-6px_rgba(0,0,0,0.55)]',
        // El menú abierto debe pintar por encima de las celdas fijas de otras filas.
        open ? 'z-30' : 'z-10',
      )}
    >
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setOpen((o) => !o); }}
        className={clsx(
          'p-1.5 rounded-md transition-colors',
          'text-content-tertiary hover:text-content-primary hover:bg-background-secondary',
          'dark:text-dark-content-secondary dark:hover:text-dark-content-primary dark:hover:bg-dark-bg-secondary',
          open && 'bg-background-secondary dark:bg-dark-bg-secondary',
        )}
        aria-label="Acciones"
      >
        <EllipsisVerticalIcon className="w-4 h-4" />
      </button>

      {open && (
        <div className={clsx(
          'absolute right-0 top-full mt-1 z-50 min-w-[148px]',
          'rounded-lg border border-border-primary shadow-lg py-1',
          'bg-bg-primary dark:bg-dark-bg-primary dark:border-dark-border-primary',
        )}>
          {onView && (
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); setOpen(false); onView(row); }}
              className="flex items-center gap-2.5 w-full px-3 py-2 text-sm text-content-primary hover:bg-background-secondary transition-colors dark:text-dark-content-primary dark:hover:bg-dark-bg-secondary"
            >
              <EyeIcon className="w-4 h-4 shrink-0 text-content-secondary dark:text-dark-content-secondary" />
              Ver detalle
            </button>
          )}
          {onEdit && (
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); setOpen(false); onEdit(row); }}
              className="flex items-center gap-2.5 w-full px-3 py-2 text-sm text-content-primary hover:bg-background-secondary transition-colors dark:text-dark-content-primary dark:hover:bg-dark-bg-secondary"
            >
              <PencilIcon className="w-4 h-4 shrink-0 text-content-secondary dark:text-dark-content-secondary" />
              Editar
            </button>
          )}
          {/* Impresión nativa del kit (acción de presentación, no muta el documento) */}
          {onPrint && (
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); setOpen(false); onPrint(row); }}
              className="flex items-center gap-2.5 w-full px-3 py-2 text-sm text-content-primary hover:bg-background-secondary transition-colors dark:text-dark-content-primary dark:hover:bg-dark-bg-secondary"
            >
              <PrintIcon className="w-4 h-4 shrink-0 text-content-secondary dark:text-dark-content-secondary" />
              {printLabel}
            </button>
          )}

          {/* Legacy: borrar gobernado por flag global (retrocompat) */}
          {hasLegacyDelete && (
            <>
              <div className="my-1 border-t border-border-secondary dark:border-dark-border-primary" />
              <button
                type="button"
                onClick={(e) => { e.stopPropagation(); setOpen(false); onDelete!(row); }}
                className="flex items-center gap-2.5 w-full px-3 py-2 text-sm text-error-content hover:bg-error-bg/10 transition-colors"
              >
                <TrashIcon className="w-4 h-4 shrink-0" />
                Eliminar
              </button>
            </>
          )}

          {/* DEF-4: acciones gateadas por el estado de la fila */}
          {useRowActions && resolvedActions.length > 0 && (
            <>
              {(onView || onEdit) && (
                <div className="my-1 border-t border-border-secondary dark:border-dark-border-primary" />
              )}
              {resolvedActions.map((action) => {
                const isDanger = action.variant === 'danger';
                const DefaultIcon = DEFAULT_ROW_ACTION_ICONS[action.key];
                return (
                  <button
                    key={action.key}
                    type="button"
                    onClick={(e) => { e.stopPropagation(); setOpen(false); onRowAction?.(action, row); }}
                    className={clsx(
                      'flex items-center gap-2.5 w-full px-3 py-2 text-sm transition-colors',
                      isDanger
                        ? 'text-error-content hover:bg-error-bg/10'
                        : 'text-content-primary hover:bg-background-secondary dark:text-dark-content-primary dark:hover:bg-dark-bg-secondary',
                    )}
                  >
                    {action.icon ? (
                      <span className="w-4 h-4 shrink-0 inline-flex items-center justify-center">{action.icon}</span>
                    ) : DefaultIcon ? (
                      <DefaultIcon className={clsx('w-4 h-4 shrink-0', !isDanger && 'text-content-secondary dark:text-dark-content-secondary')} />
                    ) : null}
                    {action.label}
                  </button>
                );
              })}
            </>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Company Dropdown ──────────────────────────────────────

function CompanyDropdown({
  companies,
  selectedCompany,
  onCompanyChange,
}: {
  companies: DocumentListCompany[];
  selectedCompany?: DocumentListCompany;
  onCompanyChange?: (company: DocumentListCompany) => void;
}) {
  const [open, setOpen] = useState(false);
  const [menuPos, setMenuPos] = useState<{ top: number; left: number }>({ top: 0, left: 0 });
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  const updatePos = useCallback(() => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    setMenuPos({ top: rect.bottom + 4, left: rect.left });
  }, []);

  const handleToggle = () => {
    if (!open) updatePos();
    setOpen((o) => !o);
  };

  useEffect(() => {
    if (!open) return;
    function onMouseDown(e: MouseEvent) {
      if (
        triggerRef.current?.contains(e.target as Node) ||
        menuRef.current?.contains(e.target as Node)
      ) return;
      setOpen(false);
    }
    function onScroll() { updatePos(); }
    document.addEventListener('mousedown', onMouseDown);
    window.addEventListener('scroll', onScroll, true);
    window.addEventListener('resize', updatePos);
    return () => {
      document.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', updatePos);
    };
  }, [open, updatePos]);

  const isGlobal = !selectedCompany || String(selectedCompany.uuid) === '000';
  const Icon = isGlobal ? GlobeAltIcon : BuildingOffice2Icon;

  return (
    <div className="relative inline-block">
      <button
        ref={triggerRef}
        type="button"
        onClick={handleToggle}
        className={clsx(
          'flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-colors',
          'bg-[#E8F0FE] text-[#1557B0] border border-[#1A73E8]',
          'hover:bg-[#d2e3fc]',
          'dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-700 dark:hover:bg-blue-900/40',
        )}
      >
        <Icon className="w-3.5 h-3.5 shrink-0" aria-hidden="true" />
        <span className="max-w-[160px] truncate">
          {selectedCompany?.name ?? 'Seleccionar compañía'}
        </span>
        <ChevronDownIcon className={clsx('w-3 h-3 shrink-0 transition-transform', open && 'rotate-180')} aria-hidden="true" />
      </button>

      {open && (
        <div
          ref={menuRef}
          style={{ position: 'fixed', top: menuPos.top, left: menuPos.left }}
          className={clsx(
            'z-[9999] w-72',
            'rounded-lg border border-border-primary shadow-lg py-1',
            'bg-bg-primary dark:bg-dark-bg-primary dark:border-dark-border-primary',
          )}
        >
          {companies.map((company) => (
            <button
              key={String(company.uuid)}
              type="button"
              onClick={() => { onCompanyChange?.(company); setOpen(false); }}
              className={clsx(
                'flex flex-col w-full px-3 py-2 text-left transition-colors',
                'hover:bg-background-secondary dark:hover:bg-dark-bg-secondary',
                selectedCompany?.uuid === company.uuid && 'bg-purple-50 dark:bg-purple-900/20',
              )}
            >
              <span className="font-bold text-sm text-content-primary dark:text-dark-content-primary leading-tight">
                {company.name}
              </span>
              <span className="text-xs font-medium text-content-tertiary dark:text-dark-content-secondary uppercase tracking-wider mt-0.5">
                Código: {company.code}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── DocumentList ──────────────────────────────────────────

/**
 * Vista de lista de documentos con filtros, búsqueda avanzada y paginación.
 *
 * Renderiza un encabezado con título, chip de compañía y acciones (exportar,
 * crear nuevo), una barra de pills de estado, un panel de búsqueda avanzada
 * colapsable, la tabla de resultados y controles de paginación.
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - DocumentListProps
 *
 * @example
 * ```tsx
 * <DocumentList
 *   title="Pedidos de Venta"
 *   companyName="Siesa SAS"
 *   pills={[{ key: 'all', label: 'Todos', count: 42, active: true }]}
 *   columns={[{ key: 'number', header: 'Número' }]}
 *   rows={data}
 *   totalCount={42}
 *   page={1}
 *   pageSize={10}
 *   onPageChange={setPage}
 *   onRowClick={(row) => navigate(row.id)}
 *   {...otherProps}
 * />
 * ```
 */
export function DocumentList({
  title,
  subtitle,
  companies,
  selectedCompany,
  companyName,
  onCompanyChange,
  onExport,
  onCreateNew,
  createNewLabel = 'Nuevo',
  pills,
  onPillClick,
  searchFields,
  searchValues,
  onSearchChange,
  onSearch,
  onClearSearch,
  searchOpen,
  onToggleSearch,
  columns,
  rows,
  totalCount,
  onRowClick,
  onViewRow,
  onEditRow,
  onDeleteRow,
  getRowActions,
  onPrintRow,
  isPrintRowAvailable,
  printLabel,
  bulkMode = false,
  selectedRowIds = [],
  onRowSelect,
  getRowId = (row) => String(row.id ?? row.uuid ?? ''),
  bulkConvertOptions,
  onBulkConvert,
  emptyState,
  page,
  pageSize,
  onPageChange,
  loading,
  error,
  onRetry,
  className,
}: DocumentListProps) {
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const start = (page - 1) * pageSize + 1;
  const end = Math.min(page * pageSize, totalCount);

  // Confirmación de acciones de fila (DEF-4 / DEF-3): respeta
  // `requiresConfirmation` usando el ConfirmDialog del kit en lugar de window.confirm.
  const [pendingConfirm, setPendingConfirm] = useState<{ message: string; run: () => void } | null>(null);

  const handleRowAction = useCallback((action: RowAction, row: Record<string, unknown>) => {
    if (action.requiresConfirmation) {
      setPendingConfirm({
        message: action.confirmationMessage ?? '¿Desea ejecutar esta acción?',
        run: () => { setPendingConfirm(null); action.onClick(row); },
      });
    } else {
      action.onClick(row);
    }
  }, []);

  // Una fila ofrece menú si hay ver/editar, borrado legacy, acciones por estado
  // o impresión nativa.
  const hasRowMenu = !!(onViewRow || onEditRow || onDeleteRow || getRowActions || onPrintRow);

  return (
    <div
      className={clsx(
        'bg-bg-primary rounded-xl',
        'shadow-[0_1px_3px_rgba(60,64,67,.15),0_1px_2px_rgba(60,64,67,.10)]',
        'dark:bg-dark-bg-primary dark:shadow-none dark:border dark:border-dark-border-primary',
        className,
      )}
    >
      {/* Header */}
      <div className="px-5 pt-5 pb-4">
        <div className="flex items-start justify-between gap-4 flex-wrap">
          <div>
            <h1 className="text-2xl font-bold text-content-primary dark:text-dark-content-primary leading-tight">
              {title}
            </h1>
            {subtitle && (
              <p className="text-sm text-content-secondary dark:text-dark-content-secondary mt-0.5">
                {subtitle}
              </p>
            )}
            {/* Company selector — debajo del título */}
            {companies && companies.length > 0 ? (
              <div className="mt-2">
                <CompanyDropdown
                  companies={companies}
                  selectedCompany={selectedCompany}
                  onCompanyChange={onCompanyChange}
                />
              </div>
            ) : companyName ? (
              <div className="mt-2">
                <span className={clsx(
                  'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-semibold',
                  'bg-primary-100 text-primary-600 border border-primary-600/30',
                  'dark:bg-primary-600/10 dark:text-primary-400 dark:border-primary-600/30',
                )}>
                  {companyName}
                </span>
              </div>
            ) : null}
          </div>
          <div className="flex items-center gap-2">
            {onExport && (
              <button
                type="button"
                onClick={onExport}
                className={clsx(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-semibold',
                  'border border-border-primary text-content-tertiary hover:bg-background-secondary transition-colors',
                  'dark:border-dark-border-primary dark:text-dark-content-secondary dark:hover:bg-dark-bg-secondary',
                )}
              >
                <ArrowUpTrayIcon className="w-4 h-4" aria-hidden="true" />
                <span className="hidden sm:inline">Exportar</span>
              </button>
            )}

            <button
              type="button"
              onClick={onCreateNew}
              className={clsx(
                'flex items-center gap-1.5 px-4 py-1.5 rounded-md text-xs font-semibold',
                'bg-primary-inverse-background text-primary-inverse-content hover:bg-primary-700 transition-colors',
                'dark:bg-dark-bg-inverse dark:text-dark-content-inverse dark:hover:bg-dark-bg-inverse/90',
                'min-h-[36px]',
              )}
            >
              <PlusIcon className="w-4 h-4" aria-hidden="true" />
              {createNewLabel}
            </button>
          </div>
        </div>
      </div>

      {/* Filter pills */}
      {pills.length > 0 && (
        <div className="flex items-center gap-2 px-5 pb-3 overflow-x-auto">
          {pills.map((pill) => (
            <button
              key={pill.key}
              type="button"
              onClick={() => onPillClick(pill.key)}
              className={clsx(
                'flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap',
                'transition-all duration-150 shrink-0',
                pill.active && 'ring-2 ring-inset ring-black/15',
              )}
              style={{
                backgroundColor: pill.bg ?? 'var(--color-primary-600, #0e79fd)',
                color: pill.color ?? '#fff',
              }}
            >
              {pill.label}
              {pill.count != null && (
                <span
                  className={clsx(
                    'inline-flex items-center justify-center px-1.5 min-w-[18px] h-[18px] rounded-full text-xs font-bold',
                    pill.active ? 'bg-white/20 dark:bg-black/20 text-inherit' : 'bg-background-secondary text-content-tertiary',
                  )}
                >
                  {pill.count}
                </span>
              )}
            </button>
          ))}
        </div>
      )}

      {/* Advanced search — siempre visible el header, colapsa el body */}
      {onToggleSearch && (
        <div className="border-b border-border-secondary dark:border-dark-border-primary">
          <button
            type="button"
            onClick={onToggleSearch}
            className="flex items-center w-full px-5 py-3 text-left gap-2 hover:bg-background-secondary dark:hover:bg-dark-bg-secondary transition-colors"
          >
            <MagnifyingGlassIcon className="w-3.5 h-3.5 text-content-secondary dark:text-dark-content-secondary shrink-0" aria-hidden="true" />
            <span className="flex-1 text-sm font-bold text-content-primary dark:text-dark-content-primary">
              Búsqueda avanzada
            </span>
            <ChevronRightIcon className={clsx(
              'w-3.5 h-3.5 text-content-secondary dark:text-dark-content-secondary transition-transform',
              searchOpen && 'rotate-90',
            )} aria-hidden="true" />
          </button>
          {searchOpen && (
            <div className="px-5 pb-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3">
                {searchFields.map((field) => (
                  <div key={field.key} className="flex flex-col gap-1">
                    <label className="text-xs font-semibold uppercase tracking-wider text-content-secondary">
                      {field.label}
                    </label>
                    {field.type === 'select' ? (
                      <select
                        className="w-full rounded-md border border-border-primary bg-bg-primary px-3 py-2 text-sm text-content-primary focus:outline-hidden focus:border-primary-600 focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:border-dark-border-custom dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary dark:border-dark-border-primary dark:bg-dark-bg-primary dark:text-dark-content-primary"
                        value={String(searchValues[field.key] ?? '')}
                        onChange={(e) => onSearchChange(field.key, e.target.value)}
                      >
                        <option value="">{field.placeholder ?? 'Seleccionar...'}</option>
                        {field.options?.map((opt) => (
                          <option key={opt.value} value={opt.value}>{opt.label}</option>
                        ))}
                      </select>
                    ) : (
                      <input
                        type={field.type}
                        className="w-full rounded-md border border-border-primary bg-bg-primary px-3 py-2 text-sm text-content-primary focus:outline-hidden focus:border-primary-600 focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 dark:focus:border-dark-border-custom dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary dark:border-dark-border-primary dark:bg-dark-bg-primary dark:text-dark-content-primary"
                        value={String(searchValues[field.key] ?? '')}
                        onChange={(e) => onSearchChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                      />
                    )}
                  </div>
                ))}
              </div>
              <div className="flex items-center justify-end gap-2 mt-3">
                <button
                  type="button"
                  onClick={onClearSearch}
                  className="px-3 py-1.5 rounded-md text-xs font-semibold text-content-tertiary hover:bg-background-secondary transition-colors dark:text-dark-content-secondary dark:hover:bg-dark-bg-secondary"
                >
                  Limpiar
                </button>
                <button
                  type="button"
                  onClick={onSearch}
                  className="flex items-center gap-1.5 px-4 py-1.5 rounded-md text-xs font-semibold bg-primary-inverse-background text-primary-inverse-content hover:bg-primary-700 transition-colors dark:bg-dark-bg-inverse dark:text-dark-content-inverse dark:hover:bg-dark-bg-inverse/90"
                >
                  <MagnifyingGlassIcon className="w-3.5 h-3.5" aria-hidden="true" />
                  Buscar
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Results header */}
      <div className="flex items-center gap-2 px-5 py-2.5 bg-background-secondary dark:bg-dark-bg-secondary border-b border-border-secondary dark:border-dark-border-primary">
        <span className="flex-1 text-sm font-bold text-content-primary dark:text-dark-content-primary">Resultados</span>
        <span
          className="inline-flex items-center px-[10px] py-[3px] rounded-full text-xs font-semibold"
          style={{ backgroundColor: '#E8F0FE', color: '#1A73E8' }}
        >
          {totalCount} registro{totalCount !== 1 ? 's' : ''}
        </span>
      </div>

      {/* Bulk selection bar */}
      {bulkMode && (
        <div className={clsx(
          'flex items-center justify-between gap-3 px-5 py-2.5',
          'bg-primary-custom-100 dark:bg-dark-bg-custom',
          'border-b border-primary-custom-300 dark:border-dark-border-custom',
        )}>
          <div className="flex items-center gap-3">
            <input
              type="checkbox"
              checked={selectedRowIds.length > 0 && selectedRowIds.length === rows.length}
              ref={(el) => {
                if (el) el.indeterminate = selectedRowIds.length > 0 && selectedRowIds.length < rows.length;
              }}
              onChange={(e) => {
                rows.forEach((row) => {
                  const id = getRowId(row);
                  const isSelected = selectedRowIds.includes(id);
                  if (e.target.checked && !isSelected) onRowSelect?.(id, true);
                  if (!e.target.checked && isSelected) onRowSelect?.(id, false);
                });
              }}
              className="w-4 h-4 rounded accent-primary-custom-600 cursor-pointer"
              aria-label="Seleccionar todos"
            />
            <span className="text-sm font-semibold text-primary-custom-700 dark:text-dark-content-custom">
              {selectedRowIds.length > 0
                ? `${selectedRowIds.length} documento${selectedRowIds.length !== 1 ? 's' : ''} seleccionado${selectedRowIds.length !== 1 ? 's' : ''}`
                : 'Ningún documento seleccionado'}
            </span>
          </div>

          {bulkConvertOptions && bulkConvertOptions.length > 0 && (
            <CrossingClassMenu
              options={bulkConvertOptions}
              onSelect={(classId) => onBulkConvert?.(classId, selectedRowIds)}
              disabled={selectedRowIds.length === 0}
            />
          )}
        </div>
      )}

      {/* Error state */}
      {error && (
        <div className="flex items-center justify-center gap-3 px-5 py-8">
          <span className="text-sm text-error-content">{error}</span>
          {onRetry && (
            <button
              type="button"
              onClick={onRetry}
              className="px-3 py-1.5 rounded-md text-xs font-semibold bg-error-bg text-error-content hover:bg-error-bg/80 transition-colors"
            >
              Reintentar
            </button>
          )}
        </div>
      )}

      {/* Loading skeleton */}
      {loading && !error && (
        <div className="px-5 py-4">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="flex gap-4 py-3 border-b border-border-secondary dark:border-dark-border-primary last:border-0">
              {columns.map((col) => (
                <div
                  key={col.key}
                  className="h-4 rounded bg-gradient-to-r from-background-secondary to-background-secondary dark:from-dark-bg-secondary dark:to-dark-bg-secondary animate-pulse"
                  style={{ flex: col.width ? `0 0 ${col.width}` : '1 1 0' }}
                />
              ))}
              {hasRowMenu && (
                <div className="w-10 shrink-0" />
              )}
            </div>
          ))}
        </div>
      )}

      {/* Table */}
      {!loading && !error && (
        <>
          {rows.length === 0 && emptyState ? (
            <div className="flex flex-col items-center justify-center py-16 text-center px-5">
              {emptyState.icon && (
                <div className="mb-4 text-border-primary dark:text-dark-border-primary">{emptyState.icon}</div>
              )}
              <p className="text-base font-semibold text-content-primary dark:text-dark-content-primary">
                {emptyState.title}
              </p>
              {emptyState.description && (
                <p className="text-sm text-content-secondary dark:text-dark-content-secondary mt-1 max-w-sm">
                  {emptyState.description}
                </p>
              )}
              {emptyState.action && (
                <button
                  type="button"
                  onClick={emptyState.action.onClick}
                  className="mt-4 px-4 py-2 rounded-md text-sm font-semibold bg-primary-inverse-background text-primary-inverse-content hover:bg-primary-700 transition-colors dark:bg-dark-bg-inverse dark:text-dark-content-inverse dark:hover:bg-dark-bg-inverse/90"
                >
                  {emptyState.action.label}
                </button>
              )}
            </div>
          ) : (
            // Contenedor único de scroll horizontal: encabezado y filas scrollean en
            // sincronía. El wrapper interno `min-w-max` da algo que desplazar cuando la
            // suma de columnas excede el ancho disponible; `min-w-0` evita que el desborde
            // empuje el layout (y arrastre el scroll de página).
            <div className="overflow-x-auto min-w-0">
              <div className="min-w-max">
              {/* Column headers */}
              <div className="flex bg-background-secondary dark:bg-dark-bg-secondary border-b border-border-secondary dark:border-dark-border-primary">
                {bulkMode && (
                  <div className="w-10 shrink-0 px-4 py-2 text-xs font-bold uppercase tracking-wide text-content-secondary dark:text-dark-content-secondary">
                    ✓
                  </div>
                )}
                {columns.map((col) => (
                  <div
                    key={col.key}
                    className={clsx(
                      'px-4 py-2 text-xs font-bold uppercase tracking-wide text-content-secondary',
                      col.align === 'right' && 'text-right',
                      col.align === 'center' && 'text-center',
                      'dark:text-dark-content-secondary',
                    )}
                    style={{ width: col.width, flex: col.width ? `0 0 ${col.width}` : '1 1 0' }}
                  >
                    {col.header}
                  </div>
                ))}
                {hasRowMenu && (
                  <div
                    aria-label="Acciones"
                    className={clsx(
                      'sticky right-0 z-10 w-10 shrink-0 self-stretch',
                      // Mismo fondo que la barra de encabezado para no transparentar al hacer scroll.
                      'bg-background-secondary dark:bg-dark-bg-secondary',
                      'shadow-[-6px_0_6px_-6px_rgba(60,64,67,0.18)] dark:shadow-[-6px_0_6px_-6px_rgba(0,0,0,0.55)]',
                    )}
                  />
                )}
              </div>

              {/* Rows */}
              {rows.map((row, rowIdx) => (
                <div
                  key={rowIdx}
                  role="button"
                  tabIndex={0}
                  onClick={() => onRowClick(row)}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') onRowClick(row); }}
                  className={clsx(
                    'flex w-full items-center',
                    'border-b border-border-secondary dark:border-dark-border-primary last:border-0',
                    'hover:bg-primary-100 hover:border-l-[3px] hover:border-l-primary-300',
                    'transition-all duration-150 ease-out cursor-pointer',
                    'dark:hover:bg-dark-bg-secondary',
                    'group',
                  )}
                >
                  {bulkMode && (
                    <div className="w-10 shrink-0 flex items-center justify-center px-2" onClick={(e) => e.stopPropagation()}>
                      <input
                        type="checkbox"
                        checked={selectedRowIds.includes(getRowId(row))}
                        onChange={(e) => onRowSelect?.(getRowId(row), e.target.checked)}
                        className="w-4 h-4 rounded accent-primary-custom-600 cursor-pointer"
                        aria-label="Seleccionar fila"
                      />
                    </div>
                  )}
                  {columns.map((col) => (
                    <div
                      key={col.key}
                      className={clsx(
                        'px-4 py-3 text-sm truncate',
                        col.mono && 'tabular-nums font-medium',
                        col.align === 'right' && 'text-right',
                        col.align === 'center' && 'text-center',
                        'text-content-primary dark:text-dark-content-primary',
                      )}
                      style={{ width: col.width, flex: col.width ? `0 0 ${col.width}` : '1 1 0' }}
                    >
                      {col.render ? col.render(row) : (String(row[col.dataKey ?? col.key] ?? '').trim() || '—')}
                    </div>
                  ))}
                  {hasRowMenu && (
                    <RowMenu
                      row={row}
                      onView={onViewRow}
                      onEdit={onEditRow}
                      onDelete={onDeleteRow}
                      rowActions={getRowActions?.(row)}
                      onRowAction={handleRowAction}
                      onPrint={
                        onPrintRow && (isPrintRowAvailable?.(row) ?? true)
                          ? onPrintRow
                          : undefined
                      }
                      printLabel={printLabel}
                    />
                  )}
                </div>
              ))}
              </div>
            </div>
          )}
        </>
      )}

      {/* Pagination */}
      {!loading && !error && rows.length > 0 && (
        <div className="flex items-center justify-between px-5 py-2.5 bg-background-secondary dark:bg-dark-bg-secondary border-t border-border-secondary dark:border-dark-border-primary">
          <span className="text-xs text-content-secondary dark:text-dark-content-secondary">
            Mostrando {start}-{end} de {totalCount}
          </span>
          <div className="flex items-center gap-1">
            <button
              type="button"
              disabled={page <= 1}
              onClick={() => onPageChange(page - 1)}
              className="p-1.5 rounded-md hover:bg-bg-primary disabled:opacity-30 disabled:cursor-not-allowed text-content-tertiary transition-colors dark:hover:bg-dark-bg-primary dark:text-dark-content-secondary"
              aria-label="Página anterior"
            >
              <ChevronLeftIcon className="w-4 h-4" aria-hidden="true" />
            </button>
            {Array.from({ length: Math.min(totalPages, 5) }).map((_, i) => {
              const pageNum = i + 1;
              return (
                <button
                  key={pageNum}
                  type="button"
                  onClick={() => onPageChange(pageNum)}
                  className={clsx(
                    'w-7 h-7 rounded-md text-xs font-semibold transition-colors',
                    pageNum === page
                      ? 'bg-primary-inverse-background text-primary-inverse-content dark:bg-dark-bg-inverse dark:text-dark-content-inverse'
                      : 'text-content-tertiary hover:bg-bg-primary dark:text-dark-content-secondary dark:hover:bg-dark-bg-primary',
                  )}
                >
                  {pageNum}
                </button>
              );
            })}
            <button
              type="button"
              disabled={page >= totalPages}
              onClick={() => onPageChange(page + 1)}
              className="p-1.5 rounded-md hover:bg-bg-primary disabled:opacity-30 disabled:cursor-not-allowed text-content-tertiary transition-colors dark:hover:bg-dark-bg-primary dark:text-dark-content-secondary"
              aria-label="Página siguiente"
            >
              <ChevronRightIcon className="w-4 h-4" aria-hidden="true" />
            </button>
          </div>
        </div>
      )}

      {/* Confirmación de acción de fila (DEF-4) */}
      {pendingConfirm && (
        <ConfirmDialog
          message={pendingConfirm.message}
          onConfirm={pendingConfirm.run}
          onCancel={() => setPendingConfirm(null)}
        />
      )}
    </div>
  );
}
