/**
 * DirtyStateDialog — warns user before discarding unsaved form changes.
 *
 * Appears when:
 * - User clicks "Cancelar" while isDirty=true
 * - User clicks backdrop in sidebar mode while isDirty=true
 * - User clicks a different row while form has unsaved changes
 *
 * "Continuar editando": dismisses dialog, form stays open.
 * "Descartar cambios": closes form, discards all unsaved changes.
 *
 * @module components/modals/DirtyStateDialog
 * @see FMPV-MVWC-E003-S004 I-002
 */
import React from 'react';
import { Button } from '../../../Button/Button';

export interface DirtyStateDialogProps {
  isOpen: boolean;
  onContinue: () => void;
  onDiscard: () => void;
}

export function DirtyStateDialog({ isOpen, onContinue, onDiscard }: DirtyStateDialogProps) {
  // Always rendered in DOM to avoid animation jank (R-002)
  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black/40 z-[70] flex items-center justify-center"
      role="alertdialog"
      aria-modal="true"
      aria-labelledby="dirty-dialog-title"
    >
      <div
        data-testid="dirty-state-dialog"
        className="bg-bg-primary dark:bg-dark-bg-secondary border border-transparent dark:border-dark-border-primary rounded-lg shadow-xl p-6 w-[400px]"
      >
        <h2
          id="dirty-dialog-title"
          className="text-base font-semibold text-content-primary dark:text-dark-content-primary mb-2"
        >
          ¿Descartar cambios?
        </h2>
        <p className="text-sm text-content-tertiary dark:text-dark-content-tertiary mb-6">
          Los cambios sin guardar se perderán.
        </p>
        <div className="flex gap-3 justify-end">
          <Button
            data-testid="dirty-dialog-continue"
            onClick={onContinue}
          >
            Continuar editando
          </Button>
          <Button
            data-testid="dirty-dialog-discard"
            onClick={onDiscard}
          >
            Descartar cambios
          </Button>
        </div>
      </div>
    </div>
  );
}
