/**
 * ChangeStatusModal — confirmation dialog for changing a record's active status.
 *
 * Singleton instance at MasterPatternView root level.
 * Body text adapts based on current record.isActive.
 * Optional scope note for GLOBAL + company context.
 *
 * Styles match mock .modal-overlay / .modal / .modal-header / .modal-close / .btn patterns.
 *
 * @module components/modals/ChangeStatusModal
 * @see FMPV-MVWC-E003-S005 I-001
 */
import React from 'react';
import { Power, X } from 'lucide-react';
import { Button } from '../../../Button/Button';
import type { MasterPatternViewEntity } from '../../types/service.types';

export interface ChangeStatusModalProps<T extends MasterPatternViewEntity = MasterPatternViewEntity> {
  isOpen: boolean;
  record: T | null;
  onCancel: () => void;
  onConfirm: (id: string, newStatus: boolean) => void;
  isLoading: boolean;
  companyName?: string;
}

export function ChangeStatusModal<T extends MasterPatternViewEntity = MasterPatternViewEntity>({
  isOpen,
  record,
  onCancel,
  onConfirm,
  isLoading,
  companyName,
}: ChangeStatusModalProps<T>) {
  if (!isOpen || !record) return null;

  const isCurrentlyActive = record.isActive;
  const actionText = isCurrentlyActive ? 'desactivar' : 'activar';
  const bodyText = `¿Desea ${actionText} este registro?`;
  const recordLabel = (record as any).name ?? (record as any).code ?? record.id;

  const handleConfirm = () => {
    onConfirm(record.id, !isCurrentlyActive);
  };

  return (
    /* Overlay — matches mock .modal-overlay */
    <div
      className="fixed inset-0 flex items-center justify-center z-[9000]"
      style={{ background: 'rgba(15,23,42,.45)', backdropFilter: 'blur(2px)' }}
      role="dialog"
      aria-modal="true"
    >
      {/* Modal — matches mock .modal */}
      <div
        data-testid="change-status-modal"
        className="bg-bg-primary dark:bg-dark-bg-secondary border border-transparent dark:border-dark-border-primary flex flex-col overflow-hidden"
        style={{
          borderRadius: 12,
          boxShadow: '0 24px 64px rgba(0,0,0,.22),0 4px 16px rgba(0,0,0,.1)',
          maxHeight: '78vh',
          width: 420,
        }}
      >
        {/* Header — matches mock .modal-header */}
        <div
          className="flex items-start justify-between border-b border-border-primary dark:border-dark-border-primary gap-3"
          style={{ padding: '18px 20px 14px' }}
        >
          {/* Left: icon + title/desc */}
          <div className="flex items-start gap-3">
            {/* Icon wrap amber — matches mock .modal-icon-wrap.amber */}
            <div
              className="flex-shrink-0 flex items-center justify-center bg-[#fffbeb] dark:bg-[rgba(217,119,6,0.15)] text-[#d97706] dark:text-[#fbbf24]"
              style={{ width: 36, height: 36, borderRadius: 8 }}
            >
              <Power size={18} />
            </div>
            <div>
              <div className="text-sm font-bold text-content-primary dark:text-dark-content-primary leading-snug">Cambiar estado</div>
              <div className="text-xs text-content-tertiary dark:text-dark-content-tertiary mt-0.5 leading-relaxed">{recordLabel}</div>
            </div>
          </div>

          {/* Close button — matches mock .modal-close */}
          <button
            type="button"
            data-testid="change-status-close"
            onClick={onCancel}
            className="flex-shrink-0 flex items-center justify-center p-1 rounded-md border-0 bg-transparent text-content-secondary dark:text-dark-content-secondary cursor-pointer hover:bg-background-secondary dark:hover:bg-dark-bg-secondary hover:text-content-tertiary dark:hover:text-dark-content-tertiary transition-colors leading-none"
          >
            <X size={16} />
          </button>
        </div>

        {/* Body — matches mock .modal-body */}
        <div className="flex-1 overflow-y-auto" style={{ padding: '16px 20px' }}>
          <p data-testid="change-status-body" className="text-content-primary dark:text-dark-content-primary" style={{ fontSize: 13, lineHeight: 1.6 }}>
            {bodyText}
          </p>
          {companyName && (
            <p
              data-testid="change-status-scope-note"
              className="text-content-tertiary dark:text-dark-content-tertiary"
              style={{ fontSize: 13, marginTop: 8 }}
            >
              Solo se modificará el estado para <strong>{companyName}</strong>.
            </p>
          )}
        </div>

        {/* Footer — matches mock .modal-footer */}
        <div
          className="flex items-center justify-end gap-2 border-t border-border-primary dark:border-dark-border-primary bg-background-secondary dark:bg-dark-bg-primary"
          style={{ padding: '12px 20px' }}
        >
          <Button
            data-testid="change-status-cancel"
            type="outline"
            size="l"
            onClick={onCancel}
            disabled={isLoading}
          >
            Cancelar
          </Button>
          <Button
            data-testid="change-status-confirm"
            type="default"
            size="l"
            onClick={handleConfirm}
            disabled={isLoading}
          >
            {isLoading ? '...' : 'Confirmar'}
          </Button>
        </div>
      </div>
    </div>
  );
}
