import React from 'react';
import { Lock, Globe } from 'lucide-react';
import type { WizardFormData } from './types';

const AVAILABLE_ROLES = [
  { id: 'admin', label: 'Administrador' },
  { id: 'ventas', label: 'Ventas' },
  { id: 'compras', label: 'Compras' },
  { id: 'inventario', label: 'Inventario' },
];

interface Step5PermissionsProps {
  esPrivado: boolean;
  rolesPermitidos: string[];
  onUpdatePrivacy: (isPrivate: boolean) => void;
  onUpdateRoles: (roles: string[]) => void;
}

export const Step5Permissions: React.FC<Step5PermissionsProps> = ({
  esPrivado,
  rolesPermitidos,
  onUpdatePrivacy,
  onUpdateRoles,
}) => {
  const toggleRole = (roleId: string) => {
    if (rolesPermitidos.includes(roleId)) {
      onUpdateRoles(rolesPermitidos.filter(r => r !== roleId));
    } else {
      onUpdateRoles([...rolesPermitidos, roleId]);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <h3 className="text-lg font-semibold text-gray-800">Publicación y Permisos</h3>

      <div className="p-4 border border-gray-200 rounded-xl bg-white space-y-4">
        <label className="flex items-start gap-3 cursor-pointer">
          <input
            type="radio"
            name="privacidad"
            checked={esPrivado === true}
            onChange={() => onUpdatePrivacy(true)}
            className="mt-1 text-blue-600 focus:ring-blue-500"
          />
          <div className="flex items-start gap-2">
            <Lock className="w-4 h-4 mt-0.5 text-amber-600 flex-shrink-0" />
            <div>
              <span className="block font-medium text-gray-800">Widget Privado (Solo yo)</span>
              <span className="text-sm text-gray-500">Solo tú podrás ver este widget en tu catálogo personal.</span>
            </div>
          </div>
        </label>

        <label className="flex items-start gap-3 cursor-pointer border-t border-gray-100 pt-4">
          <input
            type="radio"
            name="privacidad"
            checked={esPrivado === false}
            onChange={() => onUpdatePrivacy(false)}
            className="mt-1 text-blue-600 focus:ring-blue-500"
          />
          <div className="flex items-start gap-2">
            <Globe className="w-4 h-4 mt-0.5 text-blue-600 flex-shrink-0" />
            <div>
              <span className="block font-medium text-gray-800">Widget Público (Corporativo)</span>
              <span className="text-sm text-gray-500">Estará disponible para los usuarios con los roles seleccionados. Si no seleccionas ninguno, será visible para todos.</span>
            </div>
          </div>
        </label>

        {esPrivado === false && (
          <div className="ml-8 mt-2 p-3 bg-gray-50 rounded-lg border border-gray-200">
            <p className="text-xs font-medium text-gray-700 mb-2">Roles con acceso:</p>
            <div className="flex flex-wrap gap-2">
              {AVAILABLE_ROLES.map(role => {
                const selected = rolesPermitidos.includes(role.id);
                return (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() => toggleRole(role.id)}
                    className={`px-3 py-1.5 text-xs font-semibold rounded-full border transition-colors ${
                      selected
                        ? 'bg-blue-100 text-blue-800 border-blue-300'
                        : 'bg-white text-gray-500 border-gray-200 hover:border-blue-300 hover:text-blue-600'
                    }`}
                  >
                    {role.label}
                  </button>
                );
              })}
            </div>
            {rolesPermitidos.length === 0 && (
              <p className="text-[11px] text-gray-500 mt-2 italic">Sin roles seleccionados → visible para todos los usuarios.</p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};
