import React, { forwardRef, useId } from 'react';
import type { CheckboxProps } from './Checkbox.types';

import { cn } from "../../lib/utils";

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      id: providedId,
      className = '',
      label,
      description,
      fullWidth = false,
      size = 'md',
      error = false,
      invalid = false,
      labelPosition = 'end',
      errorMessage,
      disabled,
      indeterminate,
      ...props
    },
    ref
  ) => {
    const fallbackId = useId();
    const id = providedId ?? fallbackId;

    // Configurar el ref y el estado indeterminate cuando se monta el input
    const inputRef = React.useRef<HTMLInputElement>(null);
    React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement);

    React.useEffect(() => {
      if (inputRef.current) {
        inputRef.current.indeterminate = indeterminate ?? false;
      }
    }, [indeterminate]);

    const isError = error || invalid;

    const sizeClasses = {
      sm: 'w-4 h-4',
      md: 'w-5 h-5',
      lg: 'w-6 h-6',
    };

    const textSizes = {
      sm: 'text-sm',
      md: 'text-base',
      lg: 'text-lg',
    };

    const containerClasses = [
      'flex items-start gap-3',
      labelPosition === 'start' ? 'flex-row-reverse justify-end w-full' : 'flex-row',
      fullWidth ? 'w-full' : 'w-auto',
      disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer',
      className,
    ].join(' ');

    const inputClasses = [
      'relative shrink-0',
      'appearance-none',
      isError ? 'border border-destructive dark:border-destructive shadow-sm' : 'border border-zinc-200 dark:border-zinc-600',
      'rounded',
      'bg-white dark:bg-gray-800',
      'checked:bg-primary checked:border-primary-500 dark:checked:bg-primary-200 dark:checked:border-primary-300',
      isError ? 'focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-red-400 focus-visible:ring-offset-2 dark:focus-visible:ring-red-500/50 focus-visible:ring-offset-red-100 dark:focus-visible:ring-offset-gray-900 border-destructive dark:border-destructive text-destructive data-[state=checked]:bg-primary data-[state=checked]:border-destructive checked:bg-primary! checked:border-destructive! dark:checked:bg-primary-200! dark:checked:border-primary-300!' : 'focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-primary-400 focus-visible:ring-offset-2 dark:focus-visible:ring-primary-500/50 focus-visible:ring-offset-primary-100 dark:focus-visible:ring-offset-gray-900',
      'transition-colors duration-200',
      'cursor-inherit',
      sizeClasses[size],
      // Checkmark icon when checked
      "after:content-[''] after:absolute after:hidden checked:after:block",
      'after:left-1/2 after:top-1/2 after:-translate-x-1/2 after:-translate-y-1/2',
      'after:w-[35%] after:h-[65%] after:border-solid after:border-white dark:after:border-primary',
      'after:border-b-2 after:border-r-2 after:rotate-45',
      'after:mt-[-10%]', // small adjustment for visual centering
      // Indeterminate state styles
      'indeterminate:bg-primary indeterminate:border-primary-500 dark:indeterminate:bg-primary-200 dark:indeterminate:border-primary-300',
      'indeterminate:after:content-[""] indeterminate:after:absolute indeterminate:after:block indeterminate:after:bg-white',
      'indeterminate:after:left-1/2 indeterminate:after:top-1/2 indeterminate:after:-translate-x-1/2 indeterminate:after:-translate-y-1/2',
      'indeterminate:after:w-[60%] indeterminate:after:h-[2px] indeterminate:after:rotate-0 indeterminate:after:border-0 indeterminate:after:mt-0',
    ].join(' ');

    return (
      <div className={containerClasses}>
        <div className={[
          "flex items-center h-full pt-0.5",
          labelPosition === 'start' ? "ml-auto" : ""
        ].join(' ')}>
          <input
            type="checkbox"
            id={id}
            ref={inputRef}
            className={inputClasses}
            disabled={disabled}
            aria-invalid={isError}
            aria-describedby={isError && errorMessage ? `${id}-error` : description ? `${id}-description` : undefined}
            {...props}
          />
        </div>

        {(label || description || (isError && errorMessage)) && (
          <div className="flex flex-col gap-1 flex-1">
            {label && (
              <label
                htmlFor={id}
                className={cn(
                  'font-medium text-zinc-900 dark:text-zinc-100 cursor-inherit select-none',
                  isError && 'text-destructive dark:text-destructive',
                  textSizes[size]
                )}
              >
                {label}
              </label>
            )}

            {description && (
              <p
                id={`${id}-description`}
                className={`text-sm select-none ${isError ? 'text-destructive dark:text-destructive' : 'text-zinc-400'}`}
              >
                {description}
              </p>
            )}

            {isError && errorMessage && (
              <p
                id={`${id}-error`}
                className="text-sm text-destructive dark:text-destructive select-none"
              >
                {errorMessage}
              </p>
            )}
          </div>
        )}
      </div>
    );
  }
);

Checkbox.displayName = 'Checkbox';