/**
 * ToolbarActions — right-side toolbar buttons: Create + global custom actions.
 *
 * - "Crear" always visible and enabled; shows warning toast when canCreate=false (NEVER-HIDE)
 * - globalActions render custom action buttons after "Crear"
 * - Uses native styled buttons to guarantee mock-matching appearance
 *
 * @module components/toolbar/ToolbarActions
 * @see FMPV-MVWC-E002-S002 I-002
 */
import React, { useCallback } from 'react';
import { Plus, Download, Upload } from 'lucide-react';
import { Button } from '../../../Button/Button';
import type { MasterPatternViewDefinition } from '../../types/definition.types';
import type { MasterPatternViewPermissions } from '../../types/permissions.types';
import type { MasterPatternViewCustomAction, MasterPatternViewDefaultActions } from '../../types/props.types';
import type { MasterPatternViewEntity } from '../../types/service.types';
import { isActionAllowed, getDisabledToastMessage } from '../../engine/permissionEngine';
import { useToast, type ToastCallback } from '../../hooks/useToast';

export interface ToolbarActionsProps<T extends MasterPatternViewEntity = MasterPatternViewEntity> {
  definition: MasterPatternViewDefinition;
  permissions?: MasterPatternViewPermissions;
  defaultActions?: MasterPatternViewDefaultActions<T>;
  onCreateClick: () => void;
  globalActions?: MasterPatternViewCustomAction<T>[];
  selectedRecords?: T[];
  toast?: ToastCallback;
  showExport?: boolean;
  showImport?: boolean;
  onExport?: () => void;
  onImport?: () => void;
}


export function ToolbarActions<T extends MasterPatternViewEntity = MasterPatternViewEntity>({
  definition,
  permissions,
  defaultActions,
  onCreateClick,
  globalActions = [],
  selectedRecords = [],
  toast: toastProp,
  showExport = false,
  showImport = false,
  onExport,
  onImport,
}: ToolbarActionsProps<T>) {
  const { showWarning } = useToast(toastProp);
  const canCreate = isActionAllowed(permissions, 'CREATE', definition.type);

  const handleCreateClick = useCallback(() => {
    if (!canCreate) {
      showWarning(getDisabledToastMessage('CREATE'));
      return;
    }
    onCreateClick();
  }, [canCreate, showWarning, onCreateClick]);

  return (
    <div className="flex items-center gap-2" data-testid="toolbar-actions">
      {/* "Crear" — hidden only when defaultActions.create.show === false; otherwise NEVER-HIDE */}
      {defaultActions?.create?.show !== false && (
        <Button
          type="default"
          size="l"
          leftIcon={<Plus size={15} />}
          onClick={handleCreateClick}
          data-testid="toolbar-create-button"
        >
          Crear
        </Button>
      )}

      {/* Export button */}
      {showExport && (
        <Button
          type="outline"
          size="l"
          leftIcon={<Download size={15} />}
          onClick={onExport}
          data-testid="toolbar-export-button"
        >
          Exportar
        </Button>
      )}

      {/* Import button */}
      {showImport && (
        <Button
          type="outline"
          size="l"
          leftIcon={<Upload size={15} />}
          onClick={onImport}
          data-testid="toolbar-import-button"
        >
          Importar
        </Button>
      )}

      {/* Custom global actions */}
      {globalActions.map((action) => {
        const isDisabled = action.isDisabled?.() ?? false;
        return (
          <Button
            key={action.key}
            type="default"
            size="l"
            leftIcon={action.icon}
            onClick={() => !isDisabled && action.onExecute()}
            disabled={isDisabled}
            data-testid={`global-action-${action.key}`}
          >
            {action.label}
          </Button>
        );
      })}
    </div>
  );
}
