import React, { useEffect, useState, useMemo } from 'react';
import { useDynamicEntitiesContext } from '../core/DynamicEntitiesProvider';
import { PencilSquareIcon, DocumentTextIcon } from '@heroicons/react/24/outline';
import { FeatureService } from './services/FeatureService';
import type { Feature } from './services/FeatureService';
import { Button } from '../../Button/Button';
import { Switch } from '../../Switch/Switch';

export interface FeatureListProps {
    onSelectFeature?: (id: string) => void;
    onCreatePlansAndCriteria?: (feature: Feature) => void;
    searchTerm?: string;
}

export const FeatureList: React.FC<FeatureListProps> = ({ onSelectFeature, onCreatePlansAndCriteria, searchTerm = '' }) => {
    const { baseUrl } = useDynamicEntitiesContext();
    const service = useMemo(() => new FeatureService(baseUrl), [baseUrl]);

    const [features, setFeatures] = useState<Feature[]>([]);
    const [loading, setLoading] = useState(true);
    const [debouncedSearch, setDebouncedSearch] = useState('');
    const [togglingId, setTogglingId] = useState<string | null>(null);

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearch(searchTerm);
        }, 300);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const loadFeatures = async () => {
        setLoading(true);
        try {
            const data = await service.getAll({ page: 1, limit: 100, search: debouncedSearch });
            setFeatures(data.data);
        } catch (error) {
            console.error('Error loading features:', error);
            alert('Error cargando features. Revisa la consola.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadFeatures();
    }, [service, debouncedSearch]);

    const handleToggleFileManagement = async (feature: Feature) => {
        if (togglingId === feature.id) return;
        setTogglingId(feature.id);
        try {
            await service.setFileManagement(feature.id, !feature.hasFileManagement);
            setFeatures(prev =>
                prev.map(f => f.id === feature.id ? { ...f, hasFileManagement: !f.hasFileManagement } : f)
            );
        } catch (error) {
            console.error('Error actualizando gestión de archivos:', error);
            alert('Error al actualizar la gestión de archivos. Revisa la consola.');
        } finally {
            setTogglingId(null);
        }
    };

    return (
        <div className="bg-white rounded-2xl w-full p-5">
            {loading ? (
                <div className="p-6 text-gray-500">Cargando...</div>
            ) : (
                <div className="w-full overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr>
                                <th className="px-5 py-4 text-sm font-medium text-gray-400 border-b border-gray-200">Código</th>
                                <th className="px-5 py-4 text-sm font-medium text-gray-400 border-b border-gray-200">Nombre</th>
                                <th className="px-5 py-4 text-sm font-medium text-gray-400 border-b border-gray-200">Tipo</th>
                                <th className="px-5 py-4 text-sm font-medium text-gray-400 border-b border-gray-200 text-center">Gestión de Archivos</th>
                                <th className="px-5 py-4 text-sm font-medium text-gray-400 border-b border-gray-200 text-center w-[100px]">Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {features.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="px-5 py-6 text-center text-gray-500">
                                        No hay maestros creados.
                                    </td>
                                </tr>
                            )}
                            {features.map((feature) => (
                                <tr key={feature.id} className="group">
                                    <td className="px-5 py-4 text-sm text-gray-900 border-b border-gray-200">
                                        {feature.code}
                                    </td>
                                    <td className="px-5 py-4 text-sm text-gray-900 border-b border-gray-200">
                                        {feature.description || feature.name}
                                    </td>
                                    <td className="px-5 py-4 text-sm border-b border-gray-200">
                                        <span className="inline-flex items-center px-2 py-0.5 rounded-md text-xs font-normal bg-[#dbeefe] text-[#0e79fd]">
                                            {feature.type === 'Transaction' ? 'Transacción' :
                                                feature.type === 'Document' ? 'Documento' :
                                                    'Maestro'}
                                        </span>
                                    </td>
                                    <td className="px-5 py-4 text-sm border-b border-gray-200">
                                        <div className="flex items-center justify-center w-full">
                                            <Switch
                                                checked={!!feature.hasFileManagement}
                                                onChange={() => handleToggleFileManagement(feature)}
                                                disabled={togglingId === feature.id}
                                            />
                                        </div>
                                    </td>
                                    <td className="px-5 py-4 text-sm border-b border-gray-200 text-center">
                                        <div className="flex items-center justify-center gap-2">
                                            <Button
                                                type="outline"
                                                size="xs"
                                                onClick={() => onSelectFeature && onSelectFeature(feature.id)}
                                                leftIcon={<PencilSquareIcon className="h-3 w-3" />}
                                                ariaLabel="Editar"
                                                title="Entidad Dinámica"
                                            >
                                                ED
                                            </Button>
                                            {feature.allowsPlansAndCriteria && (
                                                <Button
                                                    type="outline"
                                                    size="xs"
                                                    onClick={() => onCreatePlansAndCriteria && onCreatePlansAndCriteria(feature)}
                                                    leftIcon={<DocumentTextIcon className="h-3 w-3" />}
                                                    ariaLabel="Planes y Criterios"
                                                    title="Planes y Criterios"
                                                >
                                                    PC
                                                </Button>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};
