import React, { useState, useEffect } from 'react';
import { Button } from '../Button/Button';
import { CloseIcon, ExclamationCircleIcon, BuildingOffice2Icon } from './icons';
import type { MasterCrudCompany, MasterCrudField } from './MasterCrud.types';

interface LinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  recordId: string | number;
  record: any;
  companies: MasterCrudCompany[];
  fields: MasterCrudField[];
  onConfirm: (recordId: string | number, companyUuids: (string | number)[]) => void;
  isLinked: (companyUuid: string | number) => boolean;
  variant?: 'success' | 'manual';
  /** Función de traducción inyectada por el padre */
  t: (key: string, defaultValue?: string) => string;
}

/**
 * LinkModal - Modal para vinculación de registros a múltiples compañías.
 */
export const LinkModal: React.FC<LinkModalProps> = ({
  isOpen,
  onClose,
  recordId,
  record,
  companies,
  fields,
  onConfirm,
  isLinked,
  variant = 'manual',
  t,
}) => {
  // ===== ESTADO LOCAL DE SELECCIÓN =====
  const [selectedUuids, setSelectedUuids] = useState<(string | number)[]>([]);
  const [initialUuids, setInitialUuids] = useState<(string | number)[]>([]);

  const targetCompanies = companies.filter(c => c.uuid !== '000');

  // Inicializar estado con las vinculaciones actuales al abrir
  useEffect(() => {
    if (isOpen) {
      const initialLinks = targetCompanies
        .filter(c => isLinked(c.uuid))
        .map(c => c.uuid);
      setSelectedUuids(initialLinks);
      setInitialUuids(initialLinks);
    }
  }, [isOpen, recordId]);

  if (!isOpen) return null;

  // ===== COMPARACIÓN DE CAMBIOS =====
  const hasChanges = JSON.stringify([...selectedUuids].sort()) !== JSON.stringify([...initialUuids].sort());

  // ===== MANEJADORES LOCALES =====
  const handleToggleLink = (uuid: string | number) => {
    setSelectedUuids(prev => 
      prev.includes(uuid) 
        ? prev.filter(c => c !== uuid) 
        : [...prev, uuid]
    );
  };

  const handleLinkAll = () => {
    setSelectedUuids(targetCompanies.map(c => c.uuid));
  };

  const handleConfirm = () => {
    onConfirm(recordId, selectedUuids);
    onClose();
  };

  // Construir título dinámico para el modo manual
  const getDynamicTitle = () => {
    if (variant === 'success') return t('recordCreatedSuccess', 'Haz creado el registro exitosamente');
    
    const titleValues = fields
      .filter(f => f.config?.showInLinkModalTitle)
      .map(f => {
        const val = record[f.accessorKey as string];
        return val ? String(val) : '';
      })
      .filter(v => v !== '');

    const suffix = titleValues.length > 0 ? ` ${titleValues.join(' - ')}` : '';
    return `${t('recordLinking', 'Vinculación de registro')}${suffix}`;
  };

  const getDescription = () => {
    if (variant === 'success') {
      return t('globalRecordSaved', 'El registro se guardó de forma Global; ahora puedes asignarlo a las compañías de tu elección');
    }
    return t('assignRecordToCompanies', 'Puedes asignar este registro a las compañías de tu elección');
  };

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4 animate-in fade-in duration-200">
      <div className="bg-white dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary rounded-xl shadow-2xl flex flex-col w-full max-w-2xl overflow-hidden relative">
        
        {/* Botón Cerrar (X) */}
        <div className="absolute right-4 top-4 z-10">
          <Button 
            type="outline" 
            size="xs" 
            iconOnly 
            leftIcon={<CloseIcon className="w-4 h-4" />} 
            onClick={onClose} 
            ariaLabel="Cerrar" 
            className="!bg-white dark:!bg-dark-bg-primary"
          />
        </div>

        {/* Header */}
        <div className="p-[20px] flex gap-5 items-center">
          <div className="bg-[#ecfccb] dark:bg-lime-900/20 flex items-center justify-center rounded-full shrink-0 size-[40px]">
            <ExclamationCircleIcon className="size-6 text-lime-700 dark:text-lime-400" />
          </div>
          <div className="flex flex-col justify-center">
            <h3 className="text-[20px] font-bold leading-[28px] tracking-tight text-content-primary dark:text-dark-content-primary">
              {getDynamicTitle()}
            </h3>
            <p className="text-[14px] font-normal italic leading-[20px] text-content-tertiary dark:text-content-tertiary">
              {getDescription()}
            </p>
          </div>
        </div>

        {/* Body - Lista de compañías */}
        <div className="px-[20px] pb-[20px] flex flex-col gap-[20px] overflow-y-auto max-h-[400px]">
          <div className="flex flex-col items-start w-full">
            {targetCompanies.map((company) => {
              const isCurrentlyLinked = selectedUuids.includes(company.uuid);
              return (
                <div 
                  key={company.uuid}
                  className="border border-border-primary dark:border-dark-border-primary h-[64px] px-[8px] flex items-center justify-between rounded-[8px] w-full mb-3 last:mb-0 transition-colors hover:bg-background-secondary dark:hover:bg-dark-bg-inverse/5"
                >
                  <div className="flex items-center gap-[8px]">
                    <div className="bg-[#dbeefe] dark:bg-primary-900/20 flex items-center justify-center rounded-[16px] shrink-0 size-[32px]">
                      <BuildingOffice2Icon className="size-[18px] text-primary-600 dark:text-primary-400" />
                    </div>
                    <span className="text-[16px] font-medium leading-[24px] text-content-primary dark:text-dark-content-primary truncate max-w-[300px]">
                      {company.name}
                    </span>
                  </div>
                  
                  {isCurrentlyLinked ? (
                    <Button 
                      type="default" 
                      size="xs" 
                      onClick={() => handleToggleLink(company.uuid)}
                      className="!bg-error-content !border-error-border hover:!bg-error-content/90 !text-white"
                    >
                      {t('unlink', 'Desvincular')}
                    </Button>
                  ) : (
                    <Button 
                      type="outline" 
                      size="xs" 
                      onClick={() => handleToggleLink(company.uuid)}
                    >
                      {t('link', 'Vincular')}
                    </Button>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="px-[24px] py-[16px] pb-[24px] flex items-center justify-end gap-[12px] shrink-0 w-full border-t border-border-secondary dark:border-dark-border-primary">
          <Button type="plain" size="l" onClick={onClose}>
            {t('cancelText', 'Cancelar')}
          </Button>
          <Button 
            type="outline" 
            size="l" 
            onClick={handleLinkAll}
          >
            {t('linkAll', 'Vincular todos')}
          </Button>
          <Button type="default" size="l" onClick={handleConfirm} disabled={!hasChanges}>
            {t('confirmText', 'Confirmar')}
          </Button>
        </div>
      </div>
    </div>
  );
};
