import { useState, useMemo, useCallback } from 'react';
import { clsx } from 'clsx';

import { ActionBar } from './ActionBar';
import { ContextStrip } from './ContextStrip';
import { HeaderRenderer } from './HeaderRenderer';
import { LinesSection } from './LinesSection';
import { FactBox } from './FactBox';
import { ContentLayout } from './ContentLayout';
import { LineFormModal } from './LineFormModal';
import { ConflictModal } from './ConflictModal';
import { SkeletonDocument } from './Skeletons';
import { CrossingSourceSelector } from './CrossingSourceSelector';
import { StaleDataBanner } from './StaleDataBanner';
import { CrossingClassMenu } from './CrossingClassMenu';
import { PendingLinesPanel } from './PendingLinesPanel';
import { DocumentTraceabilityTree } from './DocumentTraceabilityTree';
import { LineCloseModal } from './LineCloseModal';
import { CrossingGenerateModal } from './CrossingGenerateModal';

import type { MasterDocumentProps, FieldDescriptor, FieldErrorMap } from './MasterDocument.types';

// ─── Helpers ──────────────────────────────────────────────

function groupFieldsBySection(fields: FieldDescriptor[]): Record<string, FieldDescriptor[]> {
  const map: Record<string, FieldDescriptor[]> = {};
  for (const f of fields) {
    (map[f.section] ??= []).push(f);
  }
  return map;
}

// ─── MasterDocument ───────────────────────────────────────

/**
 * MasterDocument — componente de presentación que compone el documento maestro
 * completo: barra de acciones, tira de contexto, encabezado, líneas y FactBox.
 *
 * Es un componente puramente presentacional: recibe todos los datos y callbacks
 * como props y no contiene lógica de negocio. Para la versión con lógica
 * completa, usar `SmartMasterDocument` dentro de un `MasterDocumentProvider`.
 *
 * @see SmartMasterDocument — versión inteligente con template y adaptador
 * @see MasterDocumentProvider — proveedor de contexto para el modo smart
 *
 * @example
 * ```tsx
 * <MasterDocument
 *   documentId="FA-001"
 *   docTypeBadge="Factura"
 *   docState="draft"
 *   mode="edit"
 *   headerFields={fields}
 *   headerValues={values}
 *   lines={lines}
 *   lineColumns={columns}
 *   onHeaderFieldChange={handleChange}
 *   onLineSave={handleSave}
 *   onDeleteLine={handleDelete}
 * />
 * ```
 */
export function MasterDocument({
  // Identity
  documentId,
  documentNumber,
  docTypeBadge,
  breadcrumbLabel,
  onBreadcrumbClick,

  // State
  docState,
  stateBadge,
  transitions,
  onTransition,

  // Mode
  mode,

  // Actions
  actions,

  // Context strip
  contextItems,
  currencyPanel,

  // Header
  headerLayout,
  headerFields,
  headerValues,
  headerErrors,
  onHeaderFieldChange,

  // Lookup/Searcher
  lookupConfigs,
  fetcher,
  onRecordSelect,

  // Lines
  linesTitle = 'Líneas del documento',
  lines,
  lineColumns,
  lineFields,
  lineComputedRules,
  lineServerRules,
  onEvaluateServerRule,
  lineWidgetSlot,
  onLineFormValuesChange,
  lineModalSections,
  serialSupport,
  serialReadOnly,
  validateSerial,
  fetchAvailableSerials,
  lineAlerts,
  canAddLine = true,
  onAddLine,
  onEditLine,
  onViewLine,
  onDeleteLine,
  onDuplicateLine,
  lineEditable = true,
  onLineSave,

  // FactBox
  factBoxSections,

  // Conflict
  conflict,

  // Forbidden / 403
  forbidden,

  // Crossing
  crossing,

  // Loading / Error
  loading,

  // In-flight: deshabilita el guardado de línea mientras hay una mutación en curso
  busy,

  // Style
  className,
}: MasterDocumentProps) {
  // ── Internal state ────────────────────────────────────────
  const [factBoxOpen, setFactBoxOpen] = useState(true);
  const [lineModal, setLineModal] = useState<{
    open: boolean;
    lineId: string | null;
    initialData?: Record<string, unknown>;
    readOnly?: boolean;
  }>({ open: false, lineId: null });
  const [lineErrors, setLineErrors] = useState<FieldErrorMap | undefined>();

  // ── Derived data ──────────────────────────────────────────
  const fieldsBySection = useMemo(
    () => groupFieldsBySection(headerFields),
    [headerFields],
  );

  // Derivado internamente para evaluar `lockedWhen.hasLines` de los campos.
  const hasLines = lines.length > 0;

  // ── Line modal handlers ───────────────────────────────────
  const handleEditLine = useCallback(
    (lineId: string) => {
      // Cuando las líneas no son editables, no abrir el modal de edición.
      if (!lineEditable) return;
      const lineData = lines.find((l) => l.id === lineId);
      setLineModal({
        open: true,
        lineId,
        initialData: lineData ? { ...lineData } : undefined,
      });
      onEditLine(lineId);
    },
    [lineEditable, lines, onEditLine],
  );

  // Abre la línea en modo solo-lectura ("Ver"). Solo se cablea desde
  // LinesSection cuando `lineEditable === false`.
  const handleViewLine = useCallback(
    (lineId: string) => {
      const lineData = lines.find((l) => l.id === lineId);
      setLineModal({
        open: true,
        lineId,
        initialData: lineData ? { ...lineData } : undefined,
        readOnly: true,
      });
      onViewLine?.(lineId);
    },
    [lines, onViewLine],
  );

  const handleAddLine = useCallback(() => {
    setLineModal({ open: true, lineId: null, initialData: undefined });
    onAddLine();
  }, [onAddLine]);

  const handleLineModalConfirm = useCallback(
    async (data: Record<string, unknown>) => {
      const errors = (await onLineSave?.(lineModal.lineId, data)) as FieldErrorMap | undefined;
      if (errors && Object.keys(errors).length > 0) {
        setLineErrors(errors);
      } else {
        setLineErrors(undefined);
        setLineModal({ open: false, lineId: null });
      }
    },
    [lineModal.lineId, onLineSave],
  );

  // Guarda la línea actual y deja el modal abierto para ingresar otra
  const handleLineModalConfirmAndAddAnother = useCallback(
    async (data: Record<string, unknown>): Promise<FieldErrorMap | undefined> => {
      const errors = (await onLineSave?.(null, data)) as FieldErrorMap | undefined;
      if (errors && Object.keys(errors).length > 0) {
        setLineErrors(errors);
        return errors;
      }
      setLineErrors(undefined);
      // El modal permanece abierto con lineId: null → próxima línea nueva
      setLineModal({ open: true, lineId: null, initialData: undefined });
      return undefined;
    },
    [onLineSave],
  );

  const handleLineModalClose = useCallback(() => {
    setLineErrors(undefined);
    setLineModal({ open: false, lineId: null });
  }, []);

  // ── Loading state ─────────────────────────────────────────
  if (loading) {
    return <SkeletonDocument className={className} />;
  }

  // ── Render ────────────────────────────────────────────────
  return (
    <div className={clsx('w-full h-full flex flex-col', className)}>
      {/* Sticky header: ActionBar + ContextStrip — siempre visible al hacer scroll */}
      <div className="sticky top-0 z-20 shrink-0">
        <ActionBar
          breadcrumbLabel={breadcrumbLabel}
          onBreadcrumbClick={onBreadcrumbClick}
          documentId={documentId}
          documentNumber={documentNumber}
          stateBadge={stateBadge}
          docTypeBadge={docTypeBadge}
          transitions={transitions}
          onTransition={onTransition}
          actions={actions}
          onToggleFactBox={factBoxSections ? () => setFactBoxOpen((prev) => !prev) : undefined}
          factBoxOpen={factBoxOpen}
        />
        <ContextStrip items={contextItems} currencyPanel={currencyPanel} />
      </div>

      {/* Main content area with optional FactBox */}
      <ContentLayout
        factBox={
          factBoxSections ? (
            <FactBox
              sections={factBoxSections}
              open={factBoxOpen}
              onClose={() => setFactBoxOpen(false)}
            />
          ) : undefined
        }
        factBoxOpen={factBoxOpen}
        onFactBoxClose={() => setFactBoxOpen(false)}
      >
        <div className="flex flex-col gap-[10px] px-5 pt-4 pb-8">
          {/* Forbidden / 403 banner */}
          {forbidden && (
            <div
              role="alert"
              className="flex items-start justify-between gap-3 px-4 py-2.5 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800"
            >
              <span className="text-sm text-red-700 dark:text-red-400">{forbidden.message}</span>
              {forbidden.onDismiss && (
                <button
                  type="button"
                  onClick={forbidden.onDismiss}
                  aria-label="Cerrar aviso"
                  className="shrink-0 text-xs font-semibold text-red-600 hover:underline dark:text-red-400"
                >
                  Cerrar
                </button>
              )}
            </div>
          )}

          {/* Header Renderer */}
          <HeaderRenderer
            mode={headerLayout.mode}
            columns={headerLayout.columns}
            sections={headerLayout.sections}
            fieldsBySection={fieldsBySection}
            values={headerValues}
            errors={headerErrors}
            onFieldChange={onHeaderFieldChange}
            docState={docState}
            mode_form={mode}
            hasLines={hasLines}
            lookupConfigs={lookupConfigs}
            fetcher={fetcher}
            onRecordSelect={onRecordSelect}
          />

          {/* Crossing source selector — rendered below header when crossing is active */}
          {crossing?.sourceSelector && (
            <CrossingSourceSelector
              selectedDocuments={crossing.sourceSelector.selectedDocuments}
              onAdd={crossing.sourceSelector.onAdd}
              onRemove={crossing.sourceSelector.onRemove}
              locked={crossing.sourceSelector.locked}
              searchDocuments={crossing.sourceSelector.searchDocuments}
            />
          )}

          {/* Generate error banner — shown when crossing generate fails */}
          {crossing?.generateError && (
            <div className="flex items-center justify-between gap-3 px-4 py-2.5 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800">
              <span className="text-sm text-red-700 dark:text-red-400">{crossing.generateError}</span>
              <button
                type="button"
                onClick={crossing.onClearGenerateError}
                className="shrink-0 text-xs font-semibold text-red-600 hover:underline dark:text-red-400"
              >
                Cerrar
              </button>
            </div>
          )}

          {/* Page-level business rule errors (BR-11, BR-13, BR-15, BR-16) */}
          {crossing?.pageErrors?.map((msg, idx) => (
            <div
              key={idx}
              className="flex items-start justify-between gap-3 px-4 py-2.5 rounded-lg bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700"
            >
              <span className="text-sm text-amber-800 dark:text-amber-300">{msg}</span>
              {crossing.onDismissPageError && (
                <button
                  type="button"
                  onClick={() => crossing.onDismissPageError!(idx)}
                  aria-label="Cerrar aviso"
                  className="shrink-0 text-xs font-semibold text-amber-700 hover:underline dark:text-amber-400"
                >
                  Cerrar
                </button>
              )}
            </div>
          ))}

          {/* Crossing tab bar — rendered when traceability is configured */}
          {crossing && (
            <div className="flex gap-1 px-0 pt-1 pb-0 bg-bg-primary dark:bg-dark-bg-primary">
              <button
                type="button"
                onClick={() => crossing.onTabChange('lines')}
                className={clsx(
                  'px-3 py-1.5 rounded-md text-xs font-semibold transition-colors',
                  crossing.activeTab === 'lines'
                    ? 'bg-primary-custom-100 text-primary-custom-700 dark:bg-dark-bg-custom dark:text-dark-content-custom'
                    : 'text-content-secondary dark:text-dark-content-secondary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary',
                )}
              >
                Líneas
              </button>
              <button
                type="button"
                onClick={() => crossing.onTabChange('traceability')}
                className={clsx(
                  'px-3 py-1.5 rounded-md text-xs font-semibold transition-colors',
                  crossing.activeTab === 'traceability'
                    ? 'bg-primary-custom-100 text-primary-custom-700 dark:bg-dark-bg-custom dark:text-dark-content-custom'
                    : 'text-content-secondary dark:text-dark-content-secondary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary',
                )}
              >
                {crossing.traceabilityLabel || 'Trazabilidad'}
              </button>
            </div>
          )}

          {/* Lines tab content */}
          {(!crossing || crossing.activeTab === 'lines') && (
            <>
              {/* CrossingClassMenu — right-aligned, shown when in selection mode */}
              {crossing?.selectionMode && crossing.classMenuOptions.length > 0 && (
                <div className="flex justify-end">
                  <CrossingClassMenu
                    options={crossing.classMenuOptions}
                    onSelect={crossing.onSelectClass}
                    disabled={!crossing.canGenerate}
                  />
                </div>
              )}

              {/* StaleDataBanner — rendered above LinesSection when data may be stale */}
              {crossing?.pendingLinesFetchedAt && (
                <StaleDataBanner
                  fetchedAt={crossing.pendingLinesFetchedAt}
                  onRefresh={crossing.onRefreshPendingLines}
                  isRefreshing={crossing.pendingLinesLoading}
                />
              )}

              {crossing?.selectionMode ? (
                /* FE-02: panel de líneas pendientes del origen con cantidad a cruzar */
                <PendingLinesPanel
                  lines={crossing.pendingLines}
                  selectedLineIds={crossing.selectedLineIds}
                  quantities={crossing.quantitiesToCross}
                  errors={crossing.lineSelectionErrors}
                  loading={crossing.pendingLinesLoading}
                  onLineSelect={crossing.onLineSelect}
                  onTrySelectTerminalLine={crossing.onTrySelectTerminalLine}
                  onQuantityChange={crossing.onQuantityChange}
                  formatNumber={crossing.formatNumber}
                />
              ) : (
                <LinesSection
                  title={linesTitle}
                  lines={lines}
                  columns={lineColumns}
                  lineFields={lineFields}
                  alerts={lineAlerts}
                  canAddLine={canAddLine && mode !== 'view'}
                  onAddLine={handleAddLine}
                  onEditLine={handleEditLine}
                  onViewLine={handleViewLine}
                  onDeleteLine={onDeleteLine}
                  onDuplicateLine={onDuplicateLine}
                  lineEditable={lineEditable}
                  lineStatuses={crossing?.lineStatuses}
                  onOpenLineCloseModal={crossing?.onOpenLineCloseModal}
                  lineActions={crossing?.lineActions}
                />
              )}
            </>
          )}

          {/* Traceability tab content */}
          {crossing?.activeTab === 'traceability' && (
            <DocumentTraceabilityTree
              tree={crossing.traceabilityTree}
              onNodeClick={crossing.onTraceabilityNodeClick}
              loading={crossing.traceabilityLoading}
              error={crossing.traceabilityError}
              onRetry={crossing.onRetryTraceability}
            />
          )}
        </div>
      </ContentLayout>

      {/* Line Form Modal */}
      {onLineSave && (
        <LineFormModal
          open={lineModal.open}
          onClose={handleLineModalClose}
          onConfirm={handleLineModalConfirm}
          onConfirmAndAddAnother={lineModal.lineId === null ? handleLineModalConfirmAndAddAnother : undefined}
          fields={lineFields}
          initialData={lineModal.initialData}
          docState={docState}
          computedRules={lineComputedRules}
          serverRules={lineServerRules}
          onEvaluateServerRule={onEvaluateServerRule}
          sections={lineModalSections}
          widgetSlot={lineWidgetSlot}
          onFormValuesChange={onLineFormValuesChange}
          lookupConfigs={lookupConfigs}
          fetcher={fetcher}
          headerValues={headerValues}
          serialSupport={serialSupport}
          serialReadOnly={serialReadOnly}
          validateSerial={validateSerial}
          fetchAvailableSerials={fetchAvailableSerials}
          errors={lineErrors}
          busy={busy}
          readOnly={lineModal.readOnly}
          title={lineModal.readOnly ? 'Ver línea' : lineModal.lineId ? 'Editar línea' : 'Nueva línea'}
          confirmLabel={lineModal.lineId ? 'Guardar cambios' : 'Agregar línea'}
          cancelLabel={lineModal.readOnly ? 'Cerrar' : undefined}
          columns={2}
        />
      )}

      {/* Conflict Modal */}
      {conflict && (
        <ConflictModal
          open
          modifiedBy={conflict.modifiedBy}
          modifiedAgo={conflict.modifiedAgo}
          onReload={conflict.onReload}
          onKeepEditing={conflict.onKeepEditing}
          dismissable={conflict.dismissable}
          message={conflict.message}
        />
      )}

      {/* Line Close Modal — always rendered, controlled by open prop */}
      {crossing && (
        <LineCloseModal
          open={crossing.lineCloseModal.open}
          onClose={crossing.onCloseLineCloseModal}
          onConfirm={crossing.onConfirmLineClose}
          mode={crossing.lineCloseModal.mode}
          lineDescription={crossing.lineCloseModal.lineDescription}
          isLoading={crossing.lineCloseModal.isLoading}
          error={crossing.lineCloseModal.error}
        />
      )}

      {/* Crossing Generate Modal — always rendered, controlled by open prop */}
      {crossing && (
        <CrossingGenerateModal
          open={crossing.generateModal.open}
          classLabel={crossing.generateModal.classLabel}
          fields={crossing.generateHeaderFields ?? []}
          onConfirm={crossing.onConfirmGenerate}
          onCancel={crossing.onCancelGenerateModal}
          isLoading={crossing.generateModal.isLoading}
          error={crossing.generateModal.error}
        />
      )}
    </div>
  );
}
