import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'
import { ChevronDown, Loader2, X } from 'lucide-react'
import { cn, interpolateTemplate, normalizeFilters } from './utils'
import type { FilterExpression } from './types/filter.types'
import {
  useClickOutside,
  useDebouncedSearch,
  useFloatingDropdown,
  useKeyboardNavigation,
  useTranslationSafe,
  useVirtualList,
} from './hooks'
import { SearchInput } from './parts/SearchInput'
import { LiveRegion } from './parts/LiveRegion'
import type { LookupFieldProps, LookupFieldRef, LookupRecord } from './LookupField.types'
import './LookupField.css'

const DEFAULT_PAGE_SIZE = 10
const SCROLL_THRESHOLD_PX = 50
const DEFAULT_MIN_CHARS = 1

function LookupFieldInner<TRecord extends LookupRecord = LookupRecord>(
  {
    entity,
    label,
    displayFields,
    value,
    onChange,
    fetcher,
    clearable = true,
    placeholder,
    className,
    pageSize = DEFAULT_PAGE_SIZE,
    onError,
    searchFields,
    minChars = DEFAULT_MIN_CHARS,
    displayValue,
    displayTemplate,
    renderSelected,
    filters,
    getFilters,
    dependencies,
    orderBy,
    bindFields,
    readOnly = false,
    disabled = false,
    error = false,
    onFocus: onFocusProp,
    onBlur: onBlurProp,
    onReady,
    onInvalidValue,
    noResultsText,
    searchPlaceholder,
    required = false,
    showRequiredIndicator,
    validateOnBlur = true,
    onValidationChange,
    errorText,
  }: LookupFieldProps<TRecord>,
  ref: React.Ref<LookupFieldRef<TRecord>>
) {
  const { t } = useTranslationSafe()

  // Compute effective orderBy with default (AC: 2)
  const effectiveOrderBy = useMemo(
    () =>
      orderBy ?? {
        field: displayFields[0] as string,
        direction: 'asc' as const,
      },
    [orderBy, displayFields]
  )

  const id = useId()
  const [isOpen, setIsOpen] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [apiError, setApiError] = useState<Error | null>(null)
  const [records, setRecords] = useState<TRecord[]>([])
  const [selectedRecord, setSelectedRecord] = useState<TRecord | null>(null)
  const [currentPage, setCurrentPage] = useState(1)
  const [hasMorePages, setHasMorePages] = useState(true)
  const [isLoadingMore, setIsLoadingMore] = useState(false)
  const abortControllerRef = useRef<AbortController | null>(null)
  const previousRecordRef = useRef<TRecord | null>(null)
  const previousDependenciesRef = useRef(JSON.stringify(dependencies ?? []))
  const optionsRef = useRef<HTMLDivElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const debouncedSearchQuery = useDebouncedSearch(searchQuery)
  const [announcement, setAnnouncement] = useState('')

  // Refs for onReady callback (Task 6) [UPDATED v0.4 - removed totalRecordsRef]
  const hasCalledOnReadyRef = useRef(false)

  // Ref to track selectedRecord for imperative methods (always up-to-date)
  const selectedRecordRef = useRef<TRecord | null>(null)
  // Keep ref in sync with state
  selectedRecordRef.current = selectedRecord

  // Refs for focus tracking (Tasks 4, 5)
  const componentRef = useRef<HTMLDivElement>(null)
  const isFocusWithinRef = useRef(false)
  const onInvalidValueRef = useRef(onInvalidValue)

  // Keep onInvalidValue ref in sync
  useEffect(() => {
    onInvalidValueRef.current = onInvalidValue
  }, [onInvalidValue])

  // Floating UI positioning (AC: 8, Story 2.11)
  const { refs: floatingRefs, floatingStyles } = useFloatingDropdown({
    enabled: isOpen,
  })

  // Click outside detection - close dropdown when clicking outside (AC: 4, Story 2.11)
  // Note: mousedown fires BEFORE focus changes, so we need to manually trigger onBlur
  // if focus was within the component when clicking outside
  const handleClickOutside = useCallback(() => {
    if (isOpen) {
      // Trigger onBlur if focus was within (mousedown preempts natural blur)
      if (isFocusWithinRef.current) {
        isFocusWithinRef.current = false
        onBlurProp?.(selectedRecordRef.current)
      }
      setIsOpen(false)
      setSearchQuery('')
    }
  }, [isOpen, onBlurProp])

  // Exclude the portaled floating dropdown from outside-click detection
  useClickOutside(componentRef, handleClickOutside, isOpen, [floatingRefs.floating])

  // Virtualization for large lists (Story 2.13, AC: 1, 8)
  const { virtualItems, totalSize } = useVirtualList({
    count: records.length,
    parentRef: optionsRef,
    enabled: isOpen && records.length > 0,
  })

  // State for invalid value detection (Task 7)
  const [isInvalidValue, setIsInvalidValue] = useState(false)

  // State for required field validation (Story 2.12)
  const [validationError, setValidationError] = useState(false)

  // Navigation context cache state (Story 2.13, AC: 2, 7)
  const [cachedRecords, setCachedRecords] = useState<TRecord[]>([])
  const [cachedScrollPosition, setCachedScrollPosition] = useState<number>(0)
  const [cachedCurrentPage, setCachedCurrentPage] = useState<number>(1)
  const [cacheValid, setCacheValid] = useState<boolean>(false)
  const cachedSearchQueryRef = useRef<string>('')
  // Ref to prevent fetchMoreRecords during cache restoration (fixes duplicate records bug)
  const isRestoringCacheRef = useRef<boolean>(false)
  // Ref to track current page immediately (state updates are async)
  const currentPageRef = useRef<number>(1)

  // Compute combined error state: external error OR internal validation error
  const showError = error || validationError

  // Compute effective showRequiredIndicator (defaults to required prop value)
  const effectiveShowRequiredIndicator = showRequiredIndicator ?? required

  // Ref for onValidationChange to avoid stale closures
  const onValidationChangeRef = useRef(onValidationChange)
  useEffect(() => {
    onValidationChangeRef.current = onValidationChange
  }, [onValidationChange])

  // Compute effective filters (getFilters takes precedence over static filters)
  const getEffectiveFilters = useCallback((): FilterExpression | undefined => {
    if (getFilters) {
      return normalizeFilters(getFilters())
    }
    return normalizeFilters(filters)
  }, [filters, getFilters])

  const fetchRecords = useCallback(
    async (search: string = '') => {
      // Cancel any pending request
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }

      const controller = new AbortController()
      abortControllerRef.current = controller

      try {
        setIsLoading(true)
        setApiError(null)
        setAnnouncement(t('announcements.loading'))

        const effectiveFilters = getEffectiveFilters()

        // Combine fields with deduplication: Id + displayFields + bindFields (PascalCase standard)
        const allFields = [...new Set(['Id', ...displayFields, ...(bindFields ?? [])])]

        const response = await fetcher<TRecord>(entity, {
          fields: allFields,
          search: search.length >= minChars ? search : '',
          searchFields: searchFields ?? displayFields,
          page: 1,
          pageSize,
          filters: effectiveFilters,
          orderBy: effectiveOrderBy,
        })

        // Check if request was aborted
        if (controller.signal.aborted) return

        setRecords(response.data)

        // Call onReady after first successful data load (AC: 4 - fires only once) [UPDATED v0.4 - removed totalRecords]
        if (!hasCalledOnReadyRef.current && onReady) {
          hasCalledOnReadyRef.current = true
          // Delay slightly to ensure imperativeRef is up to date
          setTimeout(() => {
            onReady({ firstPageLoaded: true }, imperativeRef)
          }, 0)
        }

        // Announce results loaded or no results (AC: 7)
        if (response.data.length === 0) {
          setAnnouncement(t('announcements.noResults'))
        } else {
          setAnnouncement(t('announcements.opened', { count: response.data.length }))
        }

        // Detect end of data on initial load (AC: 5)
        if (response.data.length < pageSize) {
          setHasMorePages(false)
        }
      } catch (err) {
        // Don't set error state for aborted requests
        if (err instanceof Error && err.name === 'AbortError') return

        const fetchError = err instanceof Error ? err : new Error('Unknown error')
        setApiError(fetchError)
        onError?.(fetchError)
      } finally {
        if (!controller.signal.aborted) {
          setIsLoading(false)
        }
      }
    },
    // Note: imperativeRef is accessed via closure, not dependency, to avoid circular dep
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      entity,
      displayFields,
      bindFields,
      searchFields,
      pageSize,
      minChars,
      onError,
      onReady,
      getEffectiveFilters,
      effectiveOrderBy,
      fetcher,
    ]
  )

  const fetchMoreRecords = useCallback(
    async (search: string = '') => {
      // Skip if currently restoring cache (prevents duplicate records bug)
      if (isRestoringCacheRef.current) return
      if (isLoadingMore || !hasMorePages) return
      // Use ref instead of state to get current page (state updates are async)
      const actualCurrentPage = currentPageRef.current

      try {
        setIsLoadingMore(true)
        setAnnouncement(t('announcements.loadingMore'))

        const effectiveFilters = getEffectiveFilters()
        const nextPage = actualCurrentPage + 1

        // Combine fields with deduplication: Id + displayFields + bindFields (PascalCase standard)
        const allFields = [...new Set(['Id', ...displayFields, ...(bindFields ?? [])])]

        const response = await fetcher<TRecord>(entity, {
          fields: allFields,
          search: search.length >= minChars ? search : '',
          searchFields: searchFields ?? displayFields,
          page: nextPage,
          pageSize,
          filters: effectiveFilters,
          orderBy: effectiveOrderBy,
        })

        // Append new records to existing list (AC: 4)
        setRecords((prev) => [...prev, ...response.data])
        currentPageRef.current = nextPage
        setCurrentPage(nextPage)

        // Announce loaded count
        setAnnouncement(t('announcements.resultsLoaded', { count: response.data.length }))

        // Detect end of data (AC: 5)
        if (response.data.length < pageSize) {
          setHasMorePages(false)
        }
      } catch (err) {
        if (err instanceof Error && err.name === 'AbortError') return
        const error = err instanceof Error ? err : new Error('Unknown error')
        onError?.(error)
      } finally {
        setIsLoadingMore(false)
      }
    },
    [
      entity,
      displayFields,
      bindFields,
      searchFields,
      pageSize,
      minChars,
      // Note: currentPage removed - using currentPageRef instead for immediate updates
      isLoadingMore,
      hasMorePages,
      onError,
      getEffectiveFilters,
      effectiveOrderBy,
      fetcher,
      t,
    ]
  )

  // Helper to fetch a single record by ID (for setValue and invalid value detection)
  const fetchAndSetRecordById = useCallback(
    async (recordId: string): Promise<TRecord | null> => {
      try {
        const allFields = [...new Set(['Id', ...displayFields, ...(bindFields ?? [])])]
        console.log('[LookupField] fetchAndSetRecordById:', { recordId, entity, allFields })
        const response = await fetcher<TRecord>(entity, {
          fields: allFields,
          filters: [[{ Id: recordId }]],
          page: 1,
          pageSize: 1,
        })
        console.log('[LookupField] fetchAndSetRecordById response:', response)
        return response.data[0] ?? null
      } catch (err) {
        console.error('[LookupField] fetchAndSetRecordById error:', err)
        return null
      }
    },
    [entity, displayFields, bindFields, fetcher]
  )

  // Validation function for required field (Story 2.12, AC: 4, 6, 10; Story 2.14, AC: 1)
  // Used by both blur validation and imperative validate() method
  const performValidation = useCallback((): boolean => {
    // Skip validation for disabled or readOnly - can't interact, so always valid
    if (disabled || readOnly) {
      setValidationError(false)
      onValidationChangeRef.current?.(true)
      return true
    }

    // Check if required and no selection
    if (required && !selectedRecordRef.current) {
      setValidationError(true)
      onValidationChangeRef.current?.(false)
      return false
    }

    // Valid - clear any existing validation error
    setValidationError(false)
    onValidationChangeRef.current?.(true)
    return true
  }, [required, readOnly, disabled])

  const handleScroll = useCallback(() => {
    const container = optionsRef.current
    if (!container) return

    // Skip if already loading or no more pages
    if (isLoadingMore || !hasMorePages) return

    const { scrollTop, scrollHeight, clientHeight } = container
    const isNearBottom = scrollHeight - scrollTop - clientHeight < SCROLL_THRESHOLD_PX

    if (isNearBottom) {
      fetchMoreRecords(debouncedSearchQuery)
    }
  }, [isLoadingMore, hasMorePages, fetchMoreRecords, debouncedSearchQuery])

  // Auto-focus search input when dropdown opens
  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      searchInputRef.current.focus({ preventScroll: true })
    }
  }, [isOpen])

  // Fetch when debounced search changes or dropdown opens (Story 2.13: cache restore)
  useEffect(() => {
    if (isOpen) {
      // Only fetch if search is empty or has >= minChars
      if (debouncedSearchQuery.length === 0 || debouncedSearchQuery.length >= minChars) {
        // Check if we can restore from cache (Story 2.13, AC: 3, 10)
        const canRestoreFromCache =
          cacheValid &&
          cachedSearchQueryRef.current === debouncedSearchQuery &&
          cachedRecords.length > 0

        if (canRestoreFromCache) {
          // Restore from cache instead of fetching
          // Set flag to prevent fetchMoreRecords from being called during scroll restoration
          isRestoringCacheRef.current = true
          setRecords(cachedRecords)
          currentPageRef.current = cachedCurrentPage
          setCurrentPage(cachedCurrentPage)
          setHasMorePages(true) // Assume there might be more pages
          // Restore scroll position after render, then clear the restoring flag
          requestAnimationFrame(() => {
            if (optionsRef.current) {
              optionsRef.current.scrollTop = cachedScrollPosition
            }
            // Clear flag after scroll position is restored (use setTimeout to ensure scroll event has been processed)
            setTimeout(() => {
              isRestoringCacheRef.current = false
            }, 0)
          })
        } else {
          // Fresh fetch - reset pagination state
          currentPageRef.current = 1
          setCurrentPage(1)
          setHasMorePages(true)
          setRecords([])
          fetchRecords(debouncedSearchQuery)
        }
      }
    }
  }, [
    isOpen,
    debouncedSearchQuery,
    fetchRecords,
    minChars,
    cacheValid,
    cachedRecords,
    cachedCurrentPage,
    cachedScrollPosition,
  ])

  // Reset search and pagination when dropdown closes
  useEffect(() => {
    if (!isOpen) {
      setSearchQuery('')
      currentPageRef.current = 1
      setCurrentPage(1)
      setHasMorePages(true)
      setIsLoadingMore(false)
    }

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }
    }
  }, [isOpen])

  // Track previous value to detect value prop changes (initialized to undefined to detect initial value)
  const previousValueRef = useRef<string | null | undefined>(undefined)

  // Ref for fetchAndSetRecordById to avoid effect re-runs
  const fetchAndSetRecordByIdRef = useRef(fetchAndSetRecordById)
  fetchAndSetRecordByIdRef.current = fetchAndSetRecordById

  // Request ID to handle React 18 Strict Mode and race conditions
  const valueSyncRequestIdRef = useRef(0)

  // Sync external value prop with internal selectedRecord state (controlled mode)
  // Only depends on value - uses refs for callbacks to avoid re-runs
  useEffect(() => {
    // On first run, previousValueRef is undefined, so we should process the initial value
    const isInitialRun = previousValueRef.current === undefined
    const valueChanged = isInitialRun || previousValueRef.current !== value
    previousValueRef.current = value

    // value null/undefined/'' means "no selection" in controlled mode — clear the visual state.
    // LineFormModal resetea los searchers a '' (no null), así que tratamos vacío igual que null
    // para evitar un fetch por Id: '' que deja el valor anterior pintado.
    if (value === null || value === undefined || value === '') {
      // Invalida cualquier fetch(idAnterior) en vuelo: el .then de ese fetch
      // chequea isStale contra este request-id, así que al incrementarlo aquí
      // su resultado se descarta y no repinta el registro viejo (race del
      // remontaje del modal: value pasa a '' mientras el fetch del id anterior
      // aún no resuelve).
      ++valueSyncRequestIdRef.current
      setSelectedRecord(null)
      setIsInvalidValue(false)
      return
    }

    // If value didn't change, skip
    if (!valueChanged) {
      return
    }

    // Si el registro ya está en memoria (lo acaba de seleccionar el usuario),
    // no re-fetchar: evita el parpadeo de "[record not found]"
    const currentRecord = selectedRecordRef.current
    if (currentRecord) {
      const recordId = String(currentRecord['Id'] ?? currentRecord['id'] ?? '')
      if (recordId === value) {
        setIsInvalidValue(false)
        return
      }
    }

    // Increment request ID to invalidate any pending requests
    const currentRequestId = ++valueSyncRequestIdRef.current

    fetchAndSetRecordByIdRef.current(value).then((record) => {
      const isStale = valueSyncRequestIdRef.current !== currentRequestId
      if (isStale) return
      if (record) {
        setSelectedRecord(record)
        setIsInvalidValue(false)
      } else {
        // Record not found - invalid value
        setIsInvalidValue(true)
        setSelectedRecord(null)
        onInvalidValueRef.current?.(value)
      }
    })
  }, [value])

  // Dependencies-based reload (AC: 7, 8)
  const dependenciesKey = JSON.stringify(dependencies ?? [])
  useEffect(() => {
    if (previousDependenciesRef.current !== dependenciesKey) {
      previousDependenciesRef.current = dependenciesKey

      // Abort any pending requests to prevent race conditions
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }

      // Invalidate cache on dependencies change (Story 2.13, AC: 6)
      setCacheValid(false)

      // Reset state on dependency change
      setRecords([])
      setSelectedRecord(null)
      currentPageRef.current = 1
      setCurrentPage(1)
      setHasMorePages(true)
      setIsOpen(false)
      setSearchQuery('')
      // Note: Don't trigger fetch here - it will happen when dropdown opens
    }
  }, [dependenciesKey])

  // Invalidate cache on filters change (Story 2.13, AC: 4)
  const filtersKey = JSON.stringify(filters ?? [])
  const previousFiltersRef = useRef(filtersKey)
  useEffect(() => {
    if (previousFiltersRef.current !== filtersKey) {
      previousFiltersRef.current = filtersKey
      setCacheValid(false)
    }
  }, [filtersKey])

  /**
   * Gets display text for the selected value in the trigger.
   * Implements priority order: renderSelected > displayTemplate > displayValue > all displayFields concatenated
   */
  const getSelectedDisplay = useCallback(
    (record: TRecord): string => {
      // Priority 1: renderSelected function
      if (renderSelected) {
        return renderSelected(record)
      }

      // Priority 2: displayTemplate with interpolation
      if (displayTemplate) {
        return interpolateTemplate(displayTemplate, record)
      }

      // Priority 3: single displayValue field
      if (displayValue) {
        const value = record[displayValue]
        return value !== undefined && value !== null ? String(value) : ''
      }

      // Default: concatenate all displayFields separated by " - "
      return displayFields
        .map((field) => {
          const value = record[field]
          return value !== undefined && value !== null ? String(value) : ''
        })
        .join(' - ')
    },
    [renderSelected, displayTemplate, displayValue, displayFields]
  )

  const handleTriggerClick = () => {
    if (disabled) return // Check disabled FIRST (Story 2.14, AC: 8)
    if (readOnly) return
    setIsOpen((prev) => !prev)
  }

  /**
   * Gets display text for dropdown option items.
   * Always uses displayFields (separated by " - ") regardless of display props.
   */
  const getOptionDisplay = (record: TRecord): string => {
    return displayFields.map((field) => String(record[field] ?? '')).join(' - ')
  }

  const handleSelectRecord = (record: TRecord) => {
    previousRecordRef.current = selectedRecord
    setSelectedRecord(record)
    selectedRecordRef.current = record // Update ref immediately for blur callbacks
    setIsInvalidValue(false) // Clear invalid state on valid selection

    // Clear validation error on selection (Story 2.12, AC: 9)
    if (validationError) {
      setValidationError(false)
      onValidationChangeRef.current?.(true)
    }

    // Save navigation context cache before closing (Story 2.13, AC: 2, 3)
    setCachedRecords(records)
    setCachedScrollPosition(optionsRef.current?.scrollTop ?? 0)
    setCachedCurrentPage(currentPage)
    cachedSearchQueryRef.current = searchQuery
    setCacheValid(true)

    onChange(record, previousRecordRef.current)
    setSearchQuery('')
    setIsOpen(false)
    setApiError(null)
    // Return focus to trigger after selection (fixes Tab behavior)
    // Set flag to prevent handleTriggerFocus from reopening dropdown
    justSelectedRef.current = true
    triggerRef.current?.focus({ preventScroll: true })
    // Announce selection
    const displayText = getSelectedDisplay(record)
    setAnnouncement(t('announcements.selected', { value: displayText }))
  }

  const handleClear = (event: React.MouseEvent) => {
    event.stopPropagation()
    previousRecordRef.current = selectedRecord
    setSelectedRecord(null)
    selectedRecordRef.current = null // Update ref immediately
    setIsInvalidValue(false)
    onChange(null, previousRecordRef.current)
    setAnnouncement(t('announcements.cleared'))
  }

  // Keyboard-triggered clear (no event needed)
  const handleKeyboardClear = useCallback(() => {
    if (!selectedRecordRef.current && !isInvalidValue) return
    previousRecordRef.current = selectedRecordRef.current
    setSelectedRecord(null)
    selectedRecordRef.current = null // Update ref immediately
    setIsInvalidValue(false)
    onChange(null, previousRecordRef.current)
    setAnnouncement(t('announcements.cleared'))
  }, [isInvalidValue, onChange, t])

  // Close handler for keyboard navigation (Tab)
  // Finds the next tabbable element outside the component and focuses it
  const handleClose = useCallback(() => {
    // Set flag to prevent trigger from reopening dropdown when it receives focus during Tab navigation
    isTabNavigatingRef.current = true

    // Close the dropdown
    setIsOpen(false)
    setSearchQuery('')
    setAnnouncement(t('announcements.closed'))

    // Find and focus the next tabbable element after the component
    // This ensures Tab navigation works correctly even when the dropdown is unmounted
    // Use setTimeout to ensure this runs after React's state update and re-render
    setTimeout(() => {
      if (!componentRef.current) return

      // Get all tabbable elements in the document (in DOM order)
      const tabbableSelector =
        'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
      const allTabbable = Array.from(document.querySelectorAll<HTMLElement>(tabbableSelector))

      // Find the index of our component's trigger button in the tab order
      const componentIndex = allTabbable.findIndex((el) => componentRef.current?.contains(el))

      // Find the first tabbable element AFTER the component (not inside it)
      let nextElement: HTMLElement | null = null
      for (let i = componentIndex + 1; i < allTabbable.length; i++) {
        if (!componentRef.current?.contains(allTabbable[i])) {
          nextElement = allTabbable[i]
          break
        }
      }

      if (nextElement) {
        nextElement.focus({ preventScroll: true })
      }
    }, 0)
  }, [t])

  // Escape handler - close AND return focus to trigger
  const handleEscapeClose = useCallback(() => {
    setIsOpen(false)
    setSearchQuery('')
    setAnnouncement(t('announcements.closed'))
    triggerRef.current?.focus({ preventScroll: true })
  }, [t])

  // Imperative clear (no event needed, for ref.clear())
  const handleImperativeClear = useCallback(() => {
    previousRecordRef.current = selectedRecordRef.current
    setSelectedRecord(null)
    setIsInvalidValue(false)
    onChange(null, previousRecordRef.current)
    setAnnouncement(t('announcements.cleared'))
  }, [onChange, t])

  // Create imperative ref object (uses refs to always get latest values)
  const imperativeRef = useMemo<LookupFieldRef<TRecord>>(
    () => ({
      clear: handleImperativeClear,
      focus: () => triggerRef.current?.focus({ preventScroll: true }),
      reload: () => fetchRecords(debouncedSearchQuery),
      getValue: () => selectedRecordRef.current,
      setValue: async (recordId: string) => {
        const record = await fetchAndSetRecordById(recordId)
        if (record) {
          previousRecordRef.current = selectedRecordRef.current
          setSelectedRecord(record)
          setIsInvalidValue(false)
          onChange(record, previousRecordRef.current)
        } else {
          // Record not found - set invalid state and notify
          setIsInvalidValue(true)
          setSelectedRecord(null)
          onInvalidValue?.(recordId)
        }
      },
      open: () => setIsOpen(true),
      close: () => setIsOpen(false),
      validate: performValidation,
    }),
    [
      handleImperativeClear,
      fetchRecords,
      debouncedSearchQuery,
      fetchAndSetRecordById,
      onChange,
      onInvalidValue,
      performValidation,
    ]
  )

  // Expose ref to parent
  useImperativeHandle(ref, () => imperativeRef, [imperativeRef])

  // Keyboard navigation hook
  const { highlightedIndex, setHighlightedIndex, handleKeyDown } = useKeyboardNavigation({
    records,
    isOpen,
    onSelect: handleSelectRecord,
    onClose: handleClose,
    onEscape: handleEscapeClose,
    onClear: handleKeyboardClear,
    searchQuery,
  })

  // Reset highlightedIndex when dropdown opens or records change
  useEffect(() => {
    if (isOpen) {
      setHighlightedIndex(-1)
    }
  }, [isOpen, records, setHighlightedIndex])

  // Scroll highlighted option into view
  useEffect(() => {
    if (highlightedIndex >= 0 && optionsRef.current) {
      const highlightedOption = optionsRef.current.querySelector(
        `[data-index="${highlightedIndex}"]`
      ) as HTMLElement
      if (highlightedOption?.scrollIntoView) {
        highlightedOption.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
      }
    }
  }, [highlightedIndex])

  // Track if focus came from mouse click (to distinguish Tab vs Click)
  const wasClickedRef = useRef(false)
  // Track if focus is from programmatic selection (to prevent dropdown reopening)
  const justSelectedRef = useRef(false)
  // Track if Tab navigation is in progress (to prevent dropdown reopening)
  const isTabNavigatingRef = useRef(false)

  const handleTriggerMouseDown = () => {
    wasClickedRef.current = true
  }

  // Handle keydown on trigger (when dropdown is closed)
  const handleTriggerKeyDown = (event: React.KeyboardEvent) => {
    // Block keyboard when disabled (Story 2.14, AC: 6)
    if (disabled) return
    // Only handle when dropdown is closed
    if (isOpen) return

    // Backspace clears selection when clearable is enabled, not readOnly, and there's a value
    if (event.key === 'Backspace' && clearable && !readOnly && (selectedRecord || isInvalidValue)) {
      event.preventDefault()
      handleKeyboardClear()
    }
  }

  // Handle focus on trigger to open dropdown (Tab key behavior - AC1)
  const handleTriggerFocus = () => {
    if (disabled) return // Block focus handling when disabled (Story 2.14)
    if (readOnly) return
    // Skip opening if focus came from programmatic selection
    if (justSelectedRef.current) {
      justSelectedRef.current = false
      return
    }
    // Skip opening if Tab navigation is closing the dropdown
    if (isTabNavigatingRef.current) {
      isTabNavigatingRef.current = false
      return
    }
    // Only open on keyboard focus (Tab), not on click-focus
    if (wasClickedRef.current) {
      wasClickedRef.current = false
      return
    }
    if (!isOpen) {
      setIsOpen(true)
    }
  }

  // Handle component-level focus (fires once when focus enters component)
  const handleComponentFocus = useCallback(() => {
    // Skip focus callbacks when disabled (Story 2.14, AC: 1)
    if (disabled) return
    // Only fire onFocus if focus is entering the component (not moving within)
    if (!isFocusWithinRef.current) {
      isFocusWithinRef.current = true
      // Use ref to get latest selectedRecord (avoids stale closure)
      onFocusProp?.(selectedRecordRef.current)
    }
  }, [onFocusProp, disabled])

  // Handle component-level blur (fires once when focus leaves component entirely)
  const handleComponentBlur = useCallback(
    (event: React.FocusEvent) => {
      // Skip blur callbacks when disabled (Story 2.14, AC: 1)
      if (disabled) return

      // Check if focus is moving outside the component
      const relatedTarget = event.relatedTarget as Node | null
      const isLeavingComponent = !componentRef.current?.contains(relatedTarget)

      if (isLeavingComponent) {
        isFocusWithinRef.current = false

        // Perform validation on blur if enabled (Story 2.12, AC: 3, 4, 10)
        if (validateOnBlur && !readOnly) {
          performValidation()
        }

        // Use ref to get latest selectedRecord (avoids stale closure)
        onBlurProp?.(selectedRecordRef.current)
      }
    },
    [onBlurProp, validateOnBlur, readOnly, disabled, performValidation]
  )

  const renderDropdownContent = () => {
    // Show min chars message when user has typed but fewer than minChars
    if (searchQuery.length > 0 && searchQuery.length < minChars) {
      return <div className="lookup-field__empty">{t('minChars', { count: minChars })}</div>
    }

    if (isLoading) {
      return (
        <div className="lookup-field__loading">
          <Loader2 className="h-4 w-4 animate-spin" />
          <span>{t('loading')}</span>
        </div>
      )
    }

    if (apiError) {
      return <div className="lookup-field__error">{t('error')}</div>
    }

    if (records.length === 0) {
      return <div className="lookup-field__empty">{noResultsText ?? t('noResults')}</div>
    }

    // Fallback to non-virtualized rendering when virtualizer can't calculate items
    // (happens in test environments where container has no dimensions)
    const useVirtualizedRendering = virtualItems.length > 0

    return (
      <div ref={optionsRef} className="lookup-field__options" onScroll={handleScroll}>
        {useVirtualizedRendering ? (
          // Virtualized list container (Story 2.13, AC: 1, 8)
          <div
            style={{
              height: `${totalSize}px`,
              width: '100%',
              position: 'relative',
            }}
          >
            {virtualItems.map((virtualItem) => {
              const record = records[virtualItem.index]
              const index = virtualItem.index
              return (
                <div
                  key={record.Id}
                  id={`${id}-option-${record.Id}`}
                  data-index={index}
                  className={cn(
                    'lookup-field__option',
                    index === highlightedIndex && 'lookup-field__option--highlighted'
                  )}
                  role="option"
                  aria-selected={selectedRecord?.Id === record.Id}
                  tabIndex={-1}
                  onClick={() => handleSelectRecord(record)}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: `${virtualItem.size}px`,
                    transform: `translateY(${virtualItem.start}px)`,
                  }}
                >
                  {getOptionDisplay(record)}
                </div>
              )
            })}
          </div>
        ) : (
          // Non-virtualized fallback for test environments
          records.map((record, index) => (
            <div
              key={record.Id}
              id={`${id}-option-${record.Id}`}
              data-index={index}
              className={cn(
                'lookup-field__option',
                index === highlightedIndex && 'lookup-field__option--highlighted'
              )}
              role="option"
              aria-selected={selectedRecord?.Id === record.Id}
              tabIndex={-1}
              onClick={() => handleSelectRecord(record)}
            >
              {getOptionDisplay(record)}
            </div>
          ))
        )}
        {/* Loading more spinner at bottom (AC: 3) */}
        {isLoadingMore && (
          <div className="lookup-field__loading-more">
            <Loader2 className="h-4 w-4 animate-spin" />
          </div>
        )}
        {/* No end indicator per FR30 (AC: 6) */}
      </div>
    )
  }

  const setTriggerRef = useCallback(
    (node: HTMLButtonElement | null) => {
      // Combine refs: triggerRef for internal use, floatingRefs.setReference for positioning
      triggerRef.current = node
      floatingRefs.setReference(node)
    },
    [floatingRefs]
  )

  return (
    <div
      ref={componentRef}
      className={cn(
        'lookup-field flex flex-col gap-2',
        disabled && 'lookup-field--disabled',
        readOnly && 'lookup-field--readonly',
        showError && 'lookup-field--error',
        className
      )}
      role="combobox"
      aria-expanded={!disabled && isOpen}
      aria-haspopup="listbox"
      aria-labelledby={`${id}-label`}
      aria-controls={isOpen ? `${id}-listbox` : undefined}
      aria-disabled={disabled || undefined}
      aria-readonly={(!disabled && readOnly) || undefined}
      aria-invalid={showError || undefined}
      aria-required={required || undefined}
      onKeyDown={disabled ? undefined : handleKeyDown}
      onFocus={handleComponentFocus}
      onBlur={handleComponentBlur}
    >
      <LiveRegion message={announcement} />
      <label id={`${id}-label`} htmlFor={id} className="lookup-field__label">
        {label}
        {effectiveShowRequiredIndicator && (
          <span className="lookup-field__required-indicator">
            {t('validation.requiredIndicator')}
          </span>
        )}
      </label>
      <button
        ref={setTriggerRef}
        id={id}
        type="button"
        className="lookup-field__trigger"
        onClick={handleTriggerClick}
        onMouseDown={handleTriggerMouseDown}
        onKeyDown={handleTriggerKeyDown}
        onFocus={handleTriggerFocus}
        disabled={disabled}
        tabIndex={disabled ? -1 : 0}
      >
        <span className="lookup-field__selected-text">
          {isInvalidValue
            ? t('notFound')
            : selectedRecord
              ? getSelectedDisplay(selectedRecord)
              : (placeholder ?? t('placeholder'))}
        </span>
        <ChevronDown
          className={cn('lookup-field__chevron', isOpen && 'lookup-field__chevron--open')}
          aria-hidden="true"
        />
        {clearable && selectedRecord && !readOnly && !disabled && (
          <X className="lookup-field__clear" onClick={handleClear} aria-label="Clear selection" />
        )}
      </button>
      {errorText && (
        <span className="lookup-field__error-text" role="alert">
          {errorText}
        </span>
      )}
      {isOpen && createPortal(
        <div
          ref={floatingRefs.setFloating}
          style={{
            ...floatingStyles,
            zIndex: 9999, // Ensure it's above modals
          }}
          className="lookup-field__dropdown"
        >
          <SearchInput
            ref={searchInputRef}
            value={searchQuery}
            onChange={setSearchQuery}
            placeholder={searchPlaceholder ?? t('searchPlaceholder')}
            listboxId={`${id}-listbox`}
            activeDescendantId={
              highlightedIndex >= 0 && records[highlightedIndex]
                ? `${id}-option-${records[highlightedIndex].Id}`
                : undefined
            }
          />
          <div id={`${id}-listbox`} role="listbox" aria-label={label}>
            {renderDropdownContent()}
          </div>
        </div>,
        document.body
      )}
    </div>
  )
}

// Export with forwardRef for generic component support
export const LookupField = forwardRef(LookupFieldInner) as <
  TRecord extends LookupRecord = LookupRecord,
>(
  props: LookupFieldProps<TRecord> & { ref?: React.Ref<LookupFieldRef<TRecord>> }
) => React.ReactElement

// Set displayName for debugging
;(LookupField as React.FC).displayName = 'LookupField'
