export interface MasterDocumentPageProps {
  /** Clase del documento. Fallback: template.identity.documentClass */
  documentClass?: string;

  /** Compañía del contexto del usuario (obligatorio) */
  companyId: string;

  /** Centro de operación del contexto del usuario (obligatorio) */
  operationCenterId: string;

  /** Si se pasa, arranca directo en el documento (edit/view). Si no, en el listado. */
  documentId?: string;
}

// ════════════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════════════

function buildColumns(
  templateCols: DocumentListColumnTemplate[],
  formatCurrency: (n: number) => string,
): DocumentListColumn[] {
  return templateCols.map((col) => {
    const base: DocumentListColumn = {
      key: col.key,
      dataKey: col.dataKey,
      header: col.header,
      align: col.align,
      mono: col.mono,
      width: col.width,
    };
    if (col.badgeMap) {
      const map = col.badgeMap;
      base.render = (row) => {
        const val = String(row[col.key] ?? '');
        const badge = map[val];
        if (!badge) return val;
        return <StateBadge label={badge.label} bg={badge.bg} color={badge.color} />;
      };
    } else if (col.format === 'currency') {
      base.render = (row) => {
        const val = row[col.key];
        return typeof val === 'number' ? formatCurrency(val) : String(val ?? '');
      };
    }
    return base;
  });
}

function buildPills(pills: DocumentListPillTemplate[], activeKey: string): FilterPill[] {
  return pills.map((p) => ({
    key: p.key,
    label: p.label,
    bg: p.bg,
    color: p.color,
    active: p.key === activeKey,
  }));
}

function buildSearchFields(filters: DocumentListFilterTemplate[]): SearchField[] {
  return filters.map((f) => ({
    key: f.key,
    label: f.label,
    type: f.type,
    options: f.options as SearchField['options'],
    placeholder: f.placeholder,
  }));
}

