// GLOBAL COMPANY SENTINEL
// ════════════════════════════════════════════════════════════

const GLOBAL_COMPANY: DocumentListCompany = {
  uuid: '000',
  code: '000',
  name: 'Global — Todas las compañías',
};

// ════════════════════════════════════════════════════════════
// VIEWS
// ════════════════════════════════════════════════════════════

type View =
  | { kind: 'list' }
  | { kind: 'wizard' }
  | { kind: 'document'; documentId: string; viewOnly?: boolean }
  | { kind: 'new'; initialState: import('../adapter/MasterDocumentAdapter.types').DocumentState }
  | { kind: 'create'; documentTypeId: string };

// ════════════════════════════════════════════════════════════
// COMPONENT
// ════════════════════════════════════════════════════════════

/**
 * MasterDocumentPage — Punto de entrada único por clase de documento.
 *
 * Recibe la compañía y centro de operación del contexto del usuario.
 * El wizard solo pide el tipo de documento — compañía y CO ya están seteados.
 *
 * @example
 * ```tsx
 * <MasterDocumentProvider template={pedidoVentaTemplate} adapter={adapter}>
 *   <MasterDocumentPage
 *     companyId="C001"
 *     operationCenterId="CO001"
 *   />
 * </MasterDocumentProvider>
 * ```
 */
export function MasterDocumentPage({
  documentClass,
  companyId,
  operationCenterId,
  documentId,
}: MasterDocumentPageProps) {
  const adapter = useMasterDocumentAdapter();
  const template = useMasterDocumentTemplate();
  const iconRegistry = useIconRegistry();
  const print = useMasterDocumentPrint();

  const docClass = documentClass ?? template.identity.documentClass;
  const listConfig = template.list;
  const wizardConfig = template.wizard;

  // ── View state ──────────────────────────────────────────
  const [view, setView] = useState<View>(
    documentId ? { kind: 'document', documentId } : { kind: 'list' },
  );

  useEffect(() => {
    if (documentId) setView({ kind: 'document', documentId });
  }, [documentId]);

  // ── List state ──────────────────────────────────────────
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const [activePill, setActivePill] = useState('all');
  const [searchValues, setSearchValues] = useState<Record<string, unknown>>({});
  const [searchOpen, setSearchOpen] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | undefined>();

  // ── Company selector del listado ────────────────────────
  const [availableCompanies, setAvailableCompanies] = useState<DocumentListCompany[]>([]);
  const [selectedListCompany, setSelectedListCompany] = useState<DocumentListCompany>(GLOBAL_COMPANY);

  const pageSize = listConfig?.defaultPageSize ?? 10;

  // ── Wizard state ────────────────────────────────────────
  const [companies, setCompanies] = useState<WizardOption[]>([]);
  const [operationCenters, setOperationCenters] = useState<WizardOption[]>([]);
  const [documentTypes, setDocumentTypes] = useState<WizardOption[]>([]);
  const [selectedType, setSelectedType] = useState<string>();
  const [companiesLoading, setCompaniesLoading] = useState(false);
  const [cosLoading, setCosLoading] = useState(false);
  const [typesLoading, setTypesLoading] = useState(false);
  const [confirmLoading, setConfirmLoading] = useState(false);

  // Cache SWR: evita flash de loading cuando los datos ya fueron fetched antes
  const wizardCacheRef = useRef<Map<string, WizardOption[]>>(new Map());

  // Cancela respuestas en vuelo cuando el paso 1 o 2 cambia de selección
  const latestCOKeyRef = useRef('');
  const latestTypesKeyRef = useRef('');

  // Selecciones locales del wizard (arrancan con el contexto, el usuario puede sobreescribir)
  const [wizardCompanyId, setWizardCompanyId] = useState(companyId);
  const [wizardCOId, setWizardCOId] = useState(operationCenterId);

  // ── Bulk conversion state ───────────────────────────────
  const [selectedRowIds, setSelectedRowIds] = useState<string[]>([]);
  const [bulkConvertOptions, setBulkConvertOptions] = useState<CrossingClassOption[]>([]);

  // ── Bulk conversion ─────────────────────────────────────
  const baseUrl = (adapter as any).baseUrl ?? 'http://localhost:5204'; // eslint-disable-line @typescript-eslint/no-explicit-any
  const crossingFetch = useMemo(() => createCrossingFetch(adapter, baseUrl), [adapter, baseUrl]);
  const {
    job: bulkJob,
    showResults: showBulkResults,
    startJob: startBulkJob,
    cancelJob: cancelBulkJob,
    closeProgress: closeBulkProgress,
    openResults: openBulkResults,
    closeResults: closeBulkResults,
    retryFailed: retryBulkFailed,
  } = useBulkConversion({ crossingFetch });

  useEffect(() => {
    if (!template.crossing?.enabled) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    crossingFetch<any>('GET', '/api/v1/crossing/rules')
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .then((payload: any) => {
        const rules: any[] = Array.isArray(payload) ? payload : (payload?.data ?? []); // eslint-disable-line @typescript-eslint/no-explicit-any
        setBulkConvertOptions(rules.map((rule: any) => ({ // eslint-disable-line @typescript-eslint/no-explicit-any
          id: rule.child_class_id,
          label: rule.child_class_label,
          description: rule.description,
        })));
      })
      .catch(() => {});
  }, [template.crossing?.enabled, crossingFetch]);

  // ── Fetch companies for list selector ──────────────────
  useEffect(() => {
    if (!adapter.listCompanies) return;
    adapter.listCompanies()
      .then((fetchedCompanies) => {
        setAvailableCompanies(fetchedCompanies);
        const match = fetchedCompanies.find((c) => String(c.uuid) === String(companyId));
        if (match) {
          setSelectedListCompany(match);
        } else if (fetchedCompanies.length > 0) {
          setSelectedListCompany(fetchedCompanies[0]);
        }
      })
      .catch(() => { /* no-op */ });
  }, [adapter]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Fetch list ──────────────────────────────────────────
  const fetchList = useCallback(async (
    pageNum: number,
    pillKey: string,
    filters: Record<string, unknown>,
    companyFilter: DocumentListCompany = selectedListCompany,
  ) => {
    if (!adapter.listDocuments) return;
    setListLoading(true);
    setListError(undefined);
    try {
      const pillConfig = Array.isArray(listConfig?.pills) ? listConfig.pills.find((p) => p.key === pillKey) : undefined;
      const isGlobal = String(companyFilter.uuid) === '000';
      const request: DocumentListRequest = {
        page: pageNum,
        pageSize,
        companyId: isGlobal ? undefined : String(companyFilter.uuid),
        stateFilter: pillConfig?.stateFilter ?? undefined,
        filters: {
          ...filters,
          documentClass: docClass,
          operationCenterId,
        },
      };
      const response = await adapter.listDocuments(request);
      setRows(response.rows);
      setTotalCount(response.totalCount);
    } catch (err) {
      setListError(String(err));
    } finally {
      setListLoading(false);
    }
  }, [adapter, listConfig, pageSize, docClass, selectedListCompany, operationCenterId]);

  useEffect(() => {
    if (view.kind === 'list') {
      fetchList(page, activePill, searchValues);
    }
  }, [view.kind, page, activePill, fetchList]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Wizard SWR helper ───────────────────────────────────
  // Muestra datos cacheados inmediatamente (sin loading) y revalida en background.
  // Solo muestra skeleton en el primer fetch real (sin cache).
  // latestKeyRef: si la clave ya no coincide cuando llega la respuesta, la descarta
  // (previene que un fetch en vuelo pise datos de una selección posterior).
  const fetchWizardStep = useCallback(async (
    entity: string,
    request: Record<string, unknown>,
    setter: (opts: WizardOption[]) => void,
    mapper: (item: Record<string, unknown>) => WizardOption,
    setLoading: (v: boolean) => void,
    latestKeyRef?: React.MutableRefObject<string>,
  ) => {
    const key = `${entity}:${JSON.stringify(request)}`;
    if (latestKeyRef) latestKeyRef.current = key;

    const cached = wizardCacheRef.current.get(key);
    if (cached) {
      setter(cached);
    } else {
      setLoading(true);
    }
    try {
      const res = await adapter.fetcher(entity, request as never);
      if (latestKeyRef && latestKeyRef.current !== key) return;
      const opts = (res.data as Record<string, unknown>[]).map(mapper);
      wizardCacheRef.current.set(key, opts);
      setter(opts);
    } catch { /* no-op */ } finally {
      if (!latestKeyRef || latestKeyRef.current === key) setLoading(false);
    }
  }, [adapter]);

  // ── Wizard: sincroniza selecciones + carga datos cuando se abre ──
  // El filtrado de los pasos dependientes (CO y tipo de documento) depende
  // EXCLUSIVAMENTE del estado interno del wizard (wizardCompanyId/wizardCOId),
  // nunca del listado/contexto. La única conveniencia es pre-seleccionar la
  // compañía + CO del contexto cuando el listado está en una compañía específica;
  // en "Global" (uuid='000') todo arranca vacío y deshabilitado.
  useEffect(() => {
    if (view.kind !== 'wizard') return;

    const isGlobal = String(selectedListCompany.uuid) === '000';
    const initialCompanyId = isGlobal ? '' : String(selectedListCompany.uuid);
    // El CO solo se pre-selecciona junto a una compañía específica. Sin compañía
    // (caso Global) no se pre-llena para evitar un estado inconsistente.
    const initialCOId = initialCompanyId ? operationCenterId : '';

    setWizardCompanyId(initialCompanyId);
    setWizardCOId(initialCOId);
    setSelectedType(undefined);

    // Los pasos dependientes arrancan vacíos; solo se llenan vía los fetches de
    // abajo cuando hay selección en el wizard. Invalida fetches en vuelo de una
    // apertura previa para evitar condiciones de carrera.
    setOperationCenters([]);
    setDocumentTypes([]);
    latestCOKeyRef.current = '';
    latestTypesKeyRef.current = '';

    if (!wizardConfig) return;

    const companyStep = wizardConfig.steps.find((s) => s.key === 'company');
    const coStep      = wizardConfig.steps.find((s) => s.key === 'co');
    const typeStep    = wizardConfig.steps.find((s) => s.key === 'docType')
      ?? wizardConfig.steps[wizardConfig.steps.length - 1];

    // La lista de compañías es independiente: siempre se carga.
    if (companyStep) {
      void fetchWizardStep(
        companyStep.entity,
        { page: 1, pageSize: 100, fields: [] },
        setCompanies,
        (item) => ({ id: String(item.Id ?? item.id ?? ''), label: String(item.name ?? item.nombre ?? item.label ?? '') }),
        setCompaniesLoading,
      );
    }

    // CObs: solo si hay compañía pre-seleccionada en el wizard, filtrando por ella.
    if (coStep && initialCompanyId) {
      void fetchWizardStep(
        coStep.entity,
        { page: 1, pageSize: 100, fields: [], filters: { companyId: initialCompanyId } },
        setOperationCenters,
        (item) => ({ id: String(item.Id ?? item.id ?? ''), label: [item.code, item.name].filter(Boolean).join(' — ') }),
        setCosLoading,
        latestCOKeyRef,
      );
    }

    // Tipos: solo si hay compañía + CO pre-seleccionados en el wizard, filtrando
    // por AMBOS valores del wizard (nunca por el contexto/listado).
    if (typeStep && initialCompanyId && initialCOId) {
      void fetchWizardStep(
        typeStep.entity,
        { page: 1, pageSize: 50, fields: [], filters: { companyId: initialCompanyId, operationCenterId: initialCOId, documentClass: docClass } },
        setDocumentTypes,
        (item) => ({ id: String(item.Id ?? item.id ?? ''), label: String(item.name ?? item.nombre ?? item.label ?? ''), description: String(item.description ?? '') }),
        setTypesLoading,
        latestTypesKeyRef,
      );
    }
  }, [view.kind, wizardConfig, fetchWizardStep, selectedListCompany, operationCenterId, docClass]);

  // ── Wizard: handler de cambio de compañía ──
  const handleWizardCompanyChange = useCallback((id: string) => {
    setWizardCompanyId(id);
    setWizardCOId('');
    setSelectedType(undefined);
    setOperationCenters([]);
    setDocumentTypes([]);
    // Invalida cualquier fetch en vuelo de pasos dependientes
    latestCOKeyRef.current = '';
    latestTypesKeyRef.current = '';
    if (!wizardConfig) return;
    const coStep = wizardConfig.steps.find((s) => s.key === 'co');
    if (!coStep) return;
    void fetchWizardStep(
      coStep.entity,
      { page: 1, pageSize: 100, fields: [], filters: { companyId: id } },
      setOperationCenters,
      (item) => ({ id: String(item.Id ?? item.id ?? ''), label: [item.code, item.name].filter(Boolean).join(' — ') }),
      setCosLoading,
      latestCOKeyRef,
    );
  }, [fetchWizardStep, wizardConfig]);

  // ── Wizard: handler de cambio de centro de operación ──
  const handleWizardCOChange = useCallback((id: string) => {
    setWizardCOId(id);
    setSelectedType(undefined);
    setDocumentTypes([]);
    latestTypesKeyRef.current = '';
    if (!wizardConfig) return;
    const typeStep = wizardConfig.steps.find((s) => s.key === 'docType')
      ?? wizardConfig.steps[wizardConfig.steps.length - 1];
    if (!typeStep) return;
    void fetchWizardStep(
      typeStep.entity,
      { page: 1, pageSize: 50, fields: [], filters: { companyId: wizardCompanyId, operationCenterId: id, documentClass: docClass } },
      setDocumentTypes,
      (item) => ({ id: String(item.Id ?? item.id ?? ''), label: String(item.name ?? item.nombre ?? item.label ?? ''), description: String(item.description ?? '') }),
      setTypesLoading,
      latestTypesKeyRef,
    );
  }, [fetchWizardStep, wizardConfig, wizardCompanyId, docClass]);

  // ── Wizard confirm ──────────────────────────────────────
  // Llama a getNewDocument para traer el template pre-poblado del backend
  // sin persistir. El POST real ocurre solo al guardar por primera vez.
  const handleWizardConfirm = useCallback(async () => {
    if (!selectedType) return;
    const typeId = selectedType;
    setSelectedType(undefined);

    if (adapter.getNewDocument) {
      setConfirmLoading(true);
      try {
        const initialState = await adapter.getNewDocument(
          docClass, wizardCompanyId, wizardCOId, typeId,
        );
        setView({ kind: 'new', initialState });
      } catch {
        setView({ kind: 'create', documentTypeId: typeId });
      } finally {
        setConfirmLoading(false);
      }
    } else {
      setView({ kind: 'create', documentTypeId: typeId });
    }
  }, [selectedType, adapter, docClass, wizardCompanyId, wizardCOId]);

  // ── Build list props ────────────────────────────────────
  const columns = useMemo(
    () => Array.isArray(listConfig?.columns) ? buildColumns(listConfig!.columns, adapter.formatCurrency) : [],
    [listConfig?.columns, adapter.formatCurrency],
  );
  const pills = useMemo(
    () => Array.isArray(listConfig?.pills) ? buildPills(listConfig!.pills, activePill) : [],
    [listConfig?.pills, activePill],
  );
  const searchFields = useMemo(
    () => Array.isArray(listConfig?.filters) ? buildSearchFields(listConfig!.filters) : [],
    [listConfig?.filters],
  );

  // ── Company change in list ──────────────────────────────
  const handleListCompanyChange = useCallback((company: DocumentListCompany) => {
    setSelectedListCompany(company);
    setPage(1);
    fetchList(1, activePill, searchValues, company);
  }, [fetchList, activePill, searchValues]);

  // ── Navigation ──────────────────────────────────────────
  const handleRowClick = useCallback((row: Record<string, unknown>) => {
    const id = String(row.id ?? row.documentId ?? '');
    if (id) setView({ kind: 'document', documentId: id });
  }, []);

  const handleViewRow = useCallback((row: Record<string, unknown>) => {
    const id = String(row.id ?? row.documentId ?? '');
    if (id) setView({ kind: 'document', documentId: id, viewOnly: true });
  }, []);

  const handleEditRow = useCallback((row: Record<string, unknown>) => {
    const id = String(row.id ?? row.documentId ?? '');
    if (id) setView({ kind: 'document', documentId: id, viewOnly: false });
  }, []);

  // ── Estado de la fila (DEF-4) ────────────────────────────
  // Resuelve el `docState` de una fila del listado. El campo es configurable vía
  // template.list.rowStateField; si no, prueba claves comunes.
  const rowStateField = listConfig?.rowStateField;
  const getRowState = useCallback((row: Record<string, unknown>): string => {
    if (rowStateField) return String(row[rowStateField] ?? '');
    return String(row.docState ?? row.state ?? row.estado ?? '');
  }, [rowStateField]);

  const getRowId = useCallback(
    (row: Record<string, unknown>) => String(row.id ?? row.documentId ?? ''),
    [],
  );

  // ── Acciones disponibles por estado (DEF-4) ──────────────
  // getAvailableActions(documentId, docState) es la fuente de verdad de qué
  // acciones (delete/cancel) ofrece cada fila. El resultado depende del estado,
  // así que se cachea por docState: una página de N filas con M estados ⇒ M
  // llamadas, no N. Si el adapter no lo implementa, no hay gateo por estado y se
  // mantiene el comportamiento legacy vía onDeleteRow.
  const [availableByState, setAvailableByState] = useState<Record<string, string[]>>({});

  const distinctRowStates = useMemo(
    () => [...new Set(rows.map(getRowState))].filter(Boolean).sort().join(','),
    [rows, getRowState],
  );

  useEffect(() => {
    if (!adapter.getAvailableActions) return;
    const states = distinctRowStates ? distinctRowStates.split(',') : [];
    if (states.length === 0) {
      setAvailableByState({});
      return;
    }
    let cancelled = false;
    Promise.all(
      states.map(async (st) => {
        const repRow = rows.find((r) => getRowState(r) === st);
        const repId = repRow ? getRowId(repRow) : '';
        try {
          const keys = await adapter.getAvailableActions!(repId, st);
          return [st, keys] as const;
        } catch {
          return [st, [] as string[]] as const;
        }
      }),
    ).then((entries) => {
      if (!cancelled) setAvailableByState(Object.fromEntries(entries));
    });
    return () => { cancelled = true; };
  }, [distinctRowStates, adapter, rows, getRowState, getRowId]);

  // Resuelve un ícono del template (string) a ReactNode vía el iconRegistry.
  const resolveIcon = useCallback(
    (iconName?: string): ReactNode => {
      if (!iconName) return undefined;
      const Icon = iconRegistry[iconName];
      return Icon ? <Icon className="w-4 h-4" /> : undefined;
    },
    [iconRegistry],
  );

  // Construye un DocumentState mínimo para ejecutar la acción vía el adapter,
  // preservando documentId y docState reales de la fila.
  const buildRowState = useCallback((id: string, docState: string): DocumentState => ({
    documentId: id,
    mode: 'edit',
    docState,
    headerValues: {},
    lines: [],
    headerErrors: {},
    lineErrors: {},
    loading: false,
    saving: false,
    factBoxData: {},
  }), []);

  // Ejecuta una acción de fila vía el adapter, igual que el action bar del
  // detalle. DEF-3: el error ya NO se traga — se propaga como feedback (toast).
  const runRowAction = useCallback(async (
    actionKey: string,
    id: string,
    docState: string,
  ) => {
    if (!id) return;
    try {
      if (actionKey === 'delete' && adapter.deleteDocument) {
        await adapter.deleteDocument(id);
      } else {
        const result = await adapter.executeAction(actionKey, buildRowState(id, docState));
        if (result && result.success === false) {
          throw new Error(result.message || 'No se pudo completar la acción.');
        }
      }
      fetchList(page, activePill, searchValues);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      toast.error('Error', { description: message });
    }
  }, [adapter, buildRowState, fetchList, page, activePill, searchValues]);

  // ── Row actions (DEF-4) ──────────────────────────────────
  // Por fila, devuelve las acciones gateadas por el estado de esa fila. Reutiliza
  // el actionRegistry para label/variant/ícono/confirmación; delete y cancel caen
  // a defaults sensatos cuando el registry no los define.
  const getRowActions = useCallback((row: Record<string, unknown>): RowAction[] => {
    const st = getRowState(row);
    const id = getRowId(row);
    const keys = availableByState[st] ?? [];
    const registry = template.actionRegistry ?? {};
    const actions: RowAction[] = [];

    if (keys.includes('delete')) {
      const entry = registry.delete;
      actions.push({
        key: 'delete',
        label: entry?.label ?? 'Eliminar',
        icon: resolveIcon(entry?.icon),
        variant: entry?.variant ?? 'danger',
        requiresConfirmation: entry?.requiresConfirmation ?? true,
        confirmationMessage: entry?.confirmationMessage
          ?? '¿Eliminar este documento? Esta acción no se puede deshacer.',
        onClick: () => { void runRowAction('delete', id, st); },
      });
    }

    if (keys.includes('cancel')) {
      const entry = registry.cancel;
      actions.push({
        key: 'cancel',
        label: entry?.label ?? 'Anular',
        icon: resolveIcon(entry?.icon),
        variant: entry?.variant ?? 'danger',
        // El adapter puede abrir su propio modal de motivo, por eso cancel no
        // exige confirmación por defecto (sí la respeta si el registry la declara).
        requiresConfirmation: entry?.requiresConfirmation ?? false,
        confirmationMessage: entry?.confirmationMessage,
        onClick: () => { void runRowAction('cancel', id, st); },
      });
    }

    return actions;
  }, [getRowState, getRowId, availableByState, template.actionRegistry, resolveIcon, runRowAction]);

  // ── Impresión nativa por fila ────────────────────────────
  // Construye el PrintContext de una fila y delega en la API del provider
  // (openPrint / isPrintAvailable). NO pasa por el adapter: es presentación.
  const buildRowPrintContext = useCallback((row: Record<string, unknown>): PrintContext => ({
    source: 'row',
    documentId: getRowId(row),
    documentNumber: (row._documentNumber as string | undefined) ?? null,
    docState: getRowState(row) || null,
    row,
  }), [getRowId, getRowState]);

  const isPrintRowAvailable = useCallback(
    (row: Record<string, unknown>) => print?.isPrintAvailable(buildRowPrintContext(row)) ?? false,
    [print, buildRowPrintContext],
  );

  const onPrintRow = useCallback(
    (row: Record<string, unknown>) => print?.openPrint(buildRowPrintContext(row)),
    [print, buildRowPrintContext],
  );

  // Legacy (retrocompat): borrado gobernado por flag global, sólo cuando el
  // adapter NO implementa getAvailableActions. Antes tragaba el error (DEF-3);
  // ahora lo propaga como feedback.
  const handleDeleteRow = useCallback(async (row: Record<string, unknown>) => {
    const id = getRowId(row);
    if (!id) return;
    if (!window.confirm('¿Eliminar este documento? Esta acción no se puede deshacer.')) return;
    try {
      if (adapter.deleteDocument) {
        await adapter.deleteDocument(id);
      } else {
        await adapter.executeAction('delete', buildRowState(id, getRowState(row)));
      }
      fetchList(page, activePill, searchValues);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      toast.error('Error', { description: message });
    }
  }, [adapter, buildRowState, getRowId, getRowState, fetchList, page, activePill, searchValues]);

  const handleBackToList = useCallback(() => {
    setView({ kind: 'list' });
  }, []);

  const adapterWithNav = useMemo(() => {
    const wrapped = { ...adapter };
    const origAction = adapter.executeAction;
    wrapped.executeAction = async (key, state) => {
      if (key === 'navigate_back') {
        handleBackToList();
        return { success: true };
      }
      if (key.startsWith('navigate_document:')) {
        const docId = key.replace('navigate_document:', '');
        if (docId) setView({ kind: 'document', documentId: docId });
        return { success: true };
      }
      return origAction(key, state);
    };
    return wrapped;
  }, [adapter, handleBackToList]);

  // ═══════════════════════════════════════════════════════
  // RENDER
  // ═══════════════════════════════════════════════════════

  if ((view.kind === 'list' || view.kind === 'wizard') && listConfig) {
    return (
      <>
        <DocumentList
          title={listConfig.title}
          subtitle={listConfig.subtitle}
          companies={availableCompanies}
          selectedCompany={selectedListCompany}
          onCompanyChange={handleListCompanyChange}
          onCreateNew={() => setView({ kind: 'wizard' })}
          createNewLabel={listConfig.createNewLabel}
          pills={pills}
          onPillClick={(key) => { setActivePill(key); setPage(1); }}
          searchFields={searchFields}
          searchValues={searchValues}
          onSearchChange={(k, v) => setSearchValues((prev) => ({ ...prev, [k]: v }))}
          onSearch={() => fetchList(1, activePill, searchValues)}
          onClearSearch={() => { setSearchValues({}); fetchList(1, activePill, {}); }}
          searchOpen={searchOpen}
          onToggleSearch={() => setSearchOpen((o) => !o)}
          columns={columns}
          rows={rows}
          totalCount={totalCount}
          onRowClick={handleRowClick}
          onViewRow={handleViewRow}
          onEditRow={handleEditRow}
          {...(adapter.getAvailableActions
            ? { getRowActions }
            : { onDeleteRow: handleDeleteRow })}
          {...(print
            ? { onPrintRow, isPrintRowAvailable, printLabel: print.label }
            : {})}
          page={page}
          pageSize={pageSize}
          onPageChange={setPage}
          loading={listLoading}
          error={listError}
          onRetry={() => fetchList(page, activePill, searchValues)}
          bulkMode={!!(template.crossing?.enabled && template.crossing?.allowBulkConvert)}
          selectedRowIds={selectedRowIds}
          onRowSelect={(id, selected) =>
            setSelectedRowIds((prev) =>
              selected ? [...prev.filter((x) => x !== id), id] : prev.filter((x) => x !== id)
            )
          }
          bulkConvertOptions={bulkConvertOptions}
          onBulkConvert={(classId, ids, headerValues) => { void startBulkJob(classId, ids, headerValues); }}
        />

        <DocumentCreationWizard
          open={view.kind === 'wizard'}
          onClose={() => setView({ kind: 'list' })}
          companies={companies}
          selectedCompany={wizardCompanyId}
          onSelectCompany={handleWizardCompanyChange}
          operationCenters={operationCenters}
          selectedCO={wizardCOId}
          onSelectCO={handleWizardCOChange}
          documentTypes={documentTypes}
          selectedType={selectedType}
          onSelectType={setSelectedType}
          onConfirm={handleWizardConfirm}
          loadingStep={
            companiesLoading ? 1
            : cosLoading ? 2
            : (typesLoading || confirmLoading) ? 3
            : undefined
          }
        />

        {bulkJob && (
          <BulkConversionProgress
            job={bulkJob}
            onCancel={() => { void cancelBulkJob(); }}
            onClose={closeBulkProgress}
            onViewResults={openBulkResults}
          />
        )}
        <BulkResultsSummary
          open={showBulkResults}
          results={bulkJob?.results ?? []}
          onRetryFailed={(ids) => { void retryBulkFailed(ids); }}
          onClose={closeBulkResults}
        />
      </>
    );
  }

  if (view.kind === 'new') {
    return <SmartMasterDocument initialState={view.initialState} onSaved={handleBackToList} onNavigateToList={handleBackToList} adapterOverride={adapterWithNav} />;
  }

  const docId = view.kind === 'document' ? view.documentId : undefined;
  const docViewOnly = view.kind === 'document' ? view.viewOnly : undefined;
  return <SmartMasterDocument documentId={docId} viewOnly={docViewOnly} onSaved={handleBackToList} onNavigateToList={handleBackToList} adapterOverride={adapterWithNav} />;
}
