import { useSortable, SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Button } from '../../Button/Button';
import { Select } from '../../Select/Select';
import { AdvancedSearchRule } from './AdvancedSearchRule';
import { CloseIcon as XMarkIcon, PlusIcon, DragHandleIcon, FunnelIcon } from '../icons';
import type { MasterCrudField, AdvancedFilter } from '../MasterCrud.types';

interface AdvancedSearchGroupProps {
  group: AdvancedFilter;
  fields: MasterCrudField[];
  onUpdate: (id: string, updates: Partial<AdvancedFilter>) => void;
  onRemove: (id: string) => void;
  onAddRule: (groupId: string) => void;
  onAddGroup: (groupId: string) => void;
  isRoot?: boolean;
  showConnectors?: boolean;
  t: (key: string, defaultValue?: string) => string;
}

export const AdvancedSearchGroup: React.FC<AdvancedSearchGroupProps> = ({
  group,
  fields,
  onUpdate,
  onRemove,
  onAddRule,
  onAddGroup,
  isRoot = false,
  showConnectors = true,
  t,
}) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: group.id, disabled: isRoot });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : undefined,
    opacity: isDragging ? 0.5 : undefined,
  };

  const children = group.children || [];

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`
        flex flex-col relative
        ${isRoot ? '' : 'p-3 border border-border-primary/50 dark:border-dark-border-primary/30 rounded-lg bg-gray-50/20 dark:bg-gray-800/5'}
      `}
    >
      {/* Cabecera del Grupo (Control de lógica centralizado) */}
      {!isRoot && (
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-3">
            <div
              {...attributes}
              {...listeners}
              className="p-1 text-content-tertiary cursor-grab active:cursor-grabbing hover:text-primary-600 transition-colors"
            >
              <DragHandleIcon className="w-3.5 h-3.5" />
            </div>

            {showConnectors && (
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-bold uppercase text-content-primary dark:text-dark-content-primary tracking-wider">{t('joinBy', 'Unir por')}:</span>
                <div className="w-28">
                  <Select
                    options={[{ value: 'AND', label: t('and', 'Y') }, { value: 'OR', label: t('or', 'O') }]}
                    value={group.connector}
                    onChange={(val) => onUpdate(group.id, { connector: val as 'AND' | 'OR' })}
                    selectSize="xs"
                    className="!border-border-primary dark:!border-dark-border-primary !bg-white dark:!bg-dark-bg-primary"
                    showLabel={false}
                    showDescription={false}
                  />
                </div>
              </div>
            )}
          </div>

          <button
            type="button"
            onClick={() => onRemove(group.id)}
            className="p-1 text-content-tertiary hover:text-error-content transition-colors"
            title={t('removeGroup', 'Eliminar grupo')}
          >
            <XMarkIcon className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* Si es root, mostrar el conector global si hay más de un hijo */}
      {isRoot && children.length > 1 && showConnectors && (
        <div className="flex items-center gap-2 mb-4">
          <span className="text-[10px] font-bold uppercase text-content-primary dark:text-dark-content-primary tracking-wider px-1.5 py-0.5 rounded">{t('joinBy', 'Unir por')}:</span>
          <div className="w-28">
            <Select
              options={[{ value: 'AND', label: t('and', 'Y') }, { value: 'OR', label: t('or', 'O') }]}
              value={group.connector}
              onChange={(val) => onUpdate(group.id, { connector: val as 'AND' | 'OR' })}
              selectSize="xs"
              className="!border-border-primary dark:!border-dark-border-primary !bg-white dark:!bg-dark-bg-primary"
              showLabel={false}
              showDescription={false}
            />
          </div>
        </div>
      )}

      {/* Lista de Hijos con Línea de Conexión */}
      <div className={`flex flex-col gap-3 relative ${!isRoot ? 'ml-1 border-l border-primary-200 dark:border-dark-border-primary/50 pl-4' : ''}`}>
        <SortableContext items={children.map(c => c.id)} strategy={verticalListSortingStrategy}>
          {children.map((child, index) => (
            <div key={child.id} className="w-full" style={{ zIndex: children.length - index + 1 }}>
              {child.isGroup ? (
                <AdvancedSearchGroup
                  group={child}
                  fields={fields}
                  onUpdate={onUpdate}
                  onRemove={onRemove}
                  onAddRule={onAddRule}
                  onAddGroup={onAddGroup}
                  showConnectors={showConnectors}
                  t={t}
                />
              ) : (
                <AdvancedSearchRule
                  filter={child}
                  fields={fields}
                  onUpdate={onUpdate}
                  onRemove={onRemove}
                  index={index}
                  t={t}
                />
              )}
            </div>
          ))}
        </SortableContext>

        {/* Botones de acción del grupo - Siempre ocupan el ancho total para no mezclarse con las reglas */}
        <div className="w-full flex items-center gap-3 mt-1.5 opacity-70 hover:opacity-100 transition-opacity">
          <button
            type="button"
            onClick={() => onAddRule(group.id)}
            className="flex items-center gap-1 text-[9px] font-bold text-primary-600 hover:text-primary-700 transition-colors uppercase tracking-tight"
          >
            <PlusIcon className="w-3 h-3" />
            {t('addRule', 'Añadir Regla')}
          </button>
          {showConnectors && (
            <button
              type="button"
              onClick={() => onAddGroup(group.id)}
              className="flex items-center gap-1 text-[9px] font-semibold text-content-primary dark:text-dark-content-primary hover:text-primary-600 transition-colors uppercase tracking-tight"
            >
              <PlusIcon className="w-3 h-3" />
              {t('addGroup', 'Añadir Grupo')}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};
