import { forwardRef, useCallback } from 'react'
import { Search, X } from 'lucide-react'
import { cn } from '../utils/cn'

interface SearchInputProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
  className?: string
  listboxId?: string
  activeDescendantId?: string
}

export const SearchInput = forwardRef<HTMLInputElement, SearchInputProps>(function SearchInput(
  { value, onChange, placeholder = 'Search...', className, listboxId, activeDescendantId },
  ref
) {
  const handleClear = useCallback(() => {
    onChange('')
  }, [onChange])

  return (
    <div className={cn('lookup-field__search-container', className)}>
      <Search className="lookup-field__search-icon" />
      <input
        ref={ref}
        type="text"
        className="lookup-field__search"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        aria-label={placeholder}
        aria-autocomplete="list"
        aria-controls={listboxId}
        aria-activedescendant={activeDescendantId}
      />
      {value && (
        <button
          type="button"
          className="lookup-field__search-clear"
          onClick={handleClear}
          aria-label="Clear search"
          tabIndex={-1}
        >
          <X className="h-4 w-4" />
        </button>
      )}
    </div>
  )
})
