/**
 * CompanySelector — toolbar company context switcher.
 *
 * For GLOBAL type (showGlobalOption=true): shows "Global" first + companies.
 * For COMPANY type: shows companies only.
 *
 * States:
 * - 0 companies (no showGlobalOption): static "Global" chip, click shows toast
 * - 0 companies + showGlobalOption: static "Global" chip (no dropdown needed)
 * - 1 company (no showGlobalOption): static chip with company name
 * - 1+ companies + showGlobalOption: clickable chip with Global + companies dropdown
 * - 2+ companies (no showGlobalOption): clickable chip with companies dropdown
 *
 * Chip shows Globe icon when activeCompanyId is 'global'/undefined, Building2 otherwise.
 *
 * @module components/toolbar/CompanySelector
 * @see FMPV-MVWC-E004-S002 I-001
 */
import React, { useState, useRef, useEffect } from 'react';
import { Globe, Building2, ChevronDown, Check } from 'lucide-react';
import type { MasterPatternViewCompany } from '../../types/service.types';
import type { ToastCallback } from '../../hooks/useToast';
import { useToast } from '../../hooks/useToast';

export interface CompanySelectorProps {
  companies: MasterPatternViewCompany[];
  activeCompanyId?: string;
  onCompanyChange: (company: MasterPatternViewCompany) => void;
  toast?: ToastCallback;
  /** When true, prepends a "Global" option to the dropdown (for GLOBAL master types). */
  showGlobalOption?: boolean;
  /** When true, renders the chip as non-interactive (grayed out, no dropdown). */
  disabled?: boolean;
}

const GLOBAL_SENTINEL: MasterPatternViewCompany = { id: 'global', name: 'Global', code: '' };

export function CompanySelector({
  companies,
  activeCompanyId,
  onCompanyChange,
  toast: toastProp,
  showGlobalOption = false,
  disabled = false,
}: CompanySelectorProps) {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const { showWarning } = useToast(toastProp);

  // Close dropdown on outside click
  useEffect(() => {
    if (!dropdownOpen) return;
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [dropdownOpen]);

  const isGlobalActive = !activeCompanyId || activeCompanyId === 'global';
  const chipClass =
    'inline-flex items-center gap-1.5 bg-[#eff8ff] dark:bg-dark-bg-custom border border-[#93d1fd] dark:border-dark-border-custom rounded-md px-3 py-1.5 text-xs font-semibold text-[#1355b7] dark:text-dark-content-custom leading-none cursor-pointer hover:bg-[#dbeefe] dark:hover:bg-[#0c2547] hover:border-[#3c9bf6] dark:hover:border-dark-content-custom transition-colors select-none';
  const chipDisabledClass =
    'inline-flex items-center gap-1.5 bg-background-secondary dark:bg-dark-bg-secondary border border-border-primary dark:border-dark-border-primary rounded-md px-3 py-1.5 text-xs font-semibold text-content-tertiary dark:text-dark-content-tertiary leading-none cursor-not-allowed select-none opacity-60';

  // No companies and no global option — static chip with toast
  if ((!companies || companies.length === 0) && !showGlobalOption) {
    return (
      <button
        type="button"
        data-testid="company-chip-global"
        className={disabled ? chipDisabledClass : chipClass}
        onClick={disabled ? undefined : () => showWarning('No hay compañías configuradas para este maestro.')}
        disabled={disabled}
      >
        <Globe size={13} style={{ flexShrink: 0 }} />
        <span>Global</span>
        <ChevronDown size={11} style={{ flexShrink: 0 }} />
      </button>
    );
  }

  // Single company, no global option — static non-interactive chip
  if (companies.length === 1 && !showGlobalOption) {
    return (
      <div
        data-testid="company-chip"
        className={`inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-semibold leading-none select-none ${
          disabled
            ? 'bg-background-secondary dark:bg-dark-bg-secondary border border-border-primary dark:border-dark-border-primary text-content-tertiary dark:text-dark-content-tertiary opacity-60'
            : 'bg-[#eff8ff] dark:bg-dark-bg-custom border border-[#93d1fd] dark:border-dark-border-custom text-[#1355b7] dark:text-dark-content-custom'
        }`}
      >
        <Building2 size={13} style={{ flexShrink: 0 }} />
        <span className="max-w-[160px] truncate">{companies[0].name}</span>
      </div>
    );
  }

  // Dropdown: Global + companies (showGlobalOption) OR companies only
  const activeCompany = companies.find((c) => c.id === activeCompanyId);
  const activeLabel = isGlobalActive ? 'Global' : (activeCompany?.name ?? companies[0]?.name ?? 'Global');
  const ActiveIcon = isGlobalActive ? Globe : Building2;

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        data-testid="company-dropdown-trigger"
        className={disabled ? chipDisabledClass : chipClass}
        onClick={disabled ? undefined : () => setDropdownOpen((v) => !v)}
        disabled={disabled}
      >
        <ActiveIcon size={13} style={{ flexShrink: 0 }} />
        <span className="max-w-[160px] truncate">{activeLabel}</span>
        <ChevronDown
          size={11}
          style={{ flexShrink: 0, transform: dropdownOpen ? 'rotate(180deg)' : 'none', transition: 'transform 150ms' }}
        />
      </button>

      {dropdownOpen && (
        <div
          data-testid="company-dropdown"
          className="absolute left-0 top-full mt-1 z-50 min-w-[200px] bg-bg-primary dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary rounded-lg shadow-md py-1"
        >
          {/* Global option — first, for GLOBAL master types */}
          {showGlobalOption && (
            <>
              <button
                type="button"
                data-testid="company-option-global"
                className="w-full flex items-center gap-2 px-3 py-2 text-xs text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary transition-colors"
                onClick={() => {
                  onCompanyChange(GLOBAL_SENTINEL);
                  setDropdownOpen(false);
                }}
              >
                {isGlobalActive
                  ? <Check size={12} className="text-[#0e79fd] flex-shrink-0" />
                  : <span className="w-3 flex-shrink-0" />}
                <Globe size={12} className="flex-shrink-0 text-[#1355b7]" />
                <span className="font-medium">Global</span>
              </button>
              {companies.length > 0 && (
                <hr className="my-1 border-border-primary dark:border-dark-border-primary" />
              )}
            </>
          )}

          {/* Companies */}
          {companies.map((company) => {
            const isActive = company.id === activeCompanyId;
            return (
              <button
                key={company.id}
                type="button"
                data-testid={`company-option-${company.id}`}
                className="w-full flex items-center gap-2 px-3 py-2 text-xs text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary transition-colors"
                onClick={() => {
                  onCompanyChange(company);
                  setDropdownOpen(false);
                }}
              >
                {isActive
                  ? <Check size={12} className="text-[#0e79fd] flex-shrink-0" />
                  : <span className="w-3 flex-shrink-0" />}
                <Building2 size={12} className="flex-shrink-0 text-[#1355b7]" />
                <span className="font-medium truncate">{company.name}</span>
                <span className="text-content-secondary dark:text-dark-content-secondary ml-auto">{company.code}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}
